W_EXTRA.push({"id":"HGW","title":"홍계월전","unit":"회","persons":{"홍계월":{"name":"홍계월","alias":["계월","평국","홍평국","원수","위왕"],"sex":"F","note":"주인공. 선녀 적강으로 태어나 다섯 살부터 남복, 평국이라는 이름으로 장원·대원수·좌승상 청주후, 뒤에 대사마 대장군 위왕 직첩. 탄로 뒤에도 벼슬 유지."},"홍무":{"name":"홍무","alias":["홍시랑","시랑","위국공","위공","초왕"],"sex":"M","note":"계월의 친부. 전 이부시랑, 모함으로 낙향. 장사랑에게 잡혀 거짓 항복했다가 벽파도로 귀양. 딸의 공으로 위국공, 끝에 초왕."},"양부인":{"name":"양부인","alias":["양씨","부인","정렬부인"],"sex":"F","note":"계월의 친모. 양처사의 딸. 맹길에게 잡혔다가 춘낭과 달아나 고소대에서 삭발, 꿈의 인도로 벽파도에서 남편을 만남."},"양윤":{"name":"양윤","alias":["시비 양윤"],"sex":"F","note":"홍씨 집 시비. 계월을 업고 피란, 부인과 함께 잡히고 함께 삭발, 벽파도에서 시랑을 먼저 찾아냄."},"춘낭":{"name":"춘낭","alias":[],"sex":"F","note":"번양 땅 양각로의 딸로 맹길에게 잡혀 첩이 된 여인. 꾀를 내어 부인과 양윤을 데리고 달아남. 끝까지 홍씨 일가와 함께함."},"선녀":{"name":"선녀","alias":["상제의 시녀"],"sex":"F","note":"태몽에 나타나 출산 때 아이를 씻기고, 피란 중 강에 빠지려는 부인을 배로 구함. 도반선생을 모시러 가던 길이라 함."},"곽도사":{"name":"곽도사","alias":["도사","선생","명현동 선생"],"sex":"M","note":"강호 땅(월호산 명현동)의 은사. 어린 계월의 관상을 보고, 뒤에 평국과 보국을 가르치며 천문을 보고 봉서를 줌. 7회 익주 천명산 도사도 봉서가 '선생의 필적'이라 같은 인물로 보임."},"정도사":{"name":"정도사","alias":[],"sex":"M","note":"홍무의 옛 동료. 참소로 벼슬을 내놓고 양주 호계촌에 은거. 홍무가 그를 찾아갔다 오는 길에 난을 만남."},"여공":{"name":"여공","alias":["기주후","우복야 기주후","오왕","시아버지"],"sex":"M","note":"무릉포 사람. 강에 떠가던 계월을 건져 친자식처럼 기름. 계월이 여자인 줄 몰랐음. 뒤에 시아버지가 되어 늘 계월 편을 듦. 끝에 오왕."},"공렬부인":{"name":"공렬부인","alias":["여공 부인","시어머니"],"sex":"F","note":"여공의 부인, 보국의 어머니. 6회 난리 때 행방을 잃었다가 위국공과 함께 돌아옴."},"보국":{"name":"보국","alias":["중군","중군장","부제후","대사마 대장군","승상 보국","좌승상"],"sex":"M","note":"여공의 아들, 계월과 동갑. 함께 배우고 부장원. 평국의 중군으로 두 번 위기에서 구출됨. 천자 중매로 계월과 혼인, 영춘 사건 뒤 갈등. 2차 출정에서 단독으로 오·초 두 왕을 사로잡음."},"영춘":{"name":"영춘","alias":["애첩 영춘"],"sex":"F","note":"보국의 애첩. 영춘각에 거처. 계월 행차에 난간에 앉아 움직이지 않았다 하여 계월에게 베임."},"천자":{"name":"천자","alias":["황상","폐하","성상"],"sex":"M","note":"대명 천자. 이름 없음. 홍무를 귀양 보내고, 평국을 대원수로 세우며 혼인을 중매함. 맹길에게 쫓겨 항서를 쓰려다 평국에게 구출됨. 난 뒤 국호를 고쳐 즉위."},"황후":{"name":"황후","alias":[],"sex":"F","note":"6회 난리에 불타 죽은 줄 알았으나 태자와 함께 위국공의 호위로 돌아옴."},"태자":{"name":"태자","alias":["황태자"],"sex":"M","note":"황후와 함께 피란, 위국공이 모시고 돌아옴."},"맹길":{"name":"맹길","alias":["장맹길","수적 맹길"],"sex":"M","note":"소상강 근처 출신 수적 우두머리. 양부인을 납치하고 계월을 강에 던짐. 5회 초왕의 선봉(장맹길)으로 다시 등장해 황성을 기습, 계월에게 잡혀 처형."},"장사랑":{"name":"장사랑","alias":["북방 절도사 장사랑"],"sex":"M","note":"양주 목사 주도와 함께 반란. 홍무를 붙잡아 거짓 항복시킴. 유성에게 붙잡힘."},"주도":{"name":"주도","alias":["양주 목사"],"sex":"M","note":"장사랑과 합세한 반란자. 이름만 나옴."},"유성":{"name":"유성","alias":[],"sex":"M","note":"장사랑의 난을 진압한 대원수."},"정덕기":{"name":"정덕기","alias":["전 양주 자사"],"sex":"M","note":"붙잡힌 홍무를 알아보고 천자에게 아룀."},"서달":{"name":"서달","alias":["대왕"],"sex":"M","note":"서관과 함께 1차 반란을 일으킨 북방의 우두머리. 벽파도로 달아났다 잡히나, 계월이 부모 상봉의 계기를 준 은인이라며 본국으로 돌려보냄."},"서관":{"name":"서관","alias":[],"sex":"M","note":"서달과 함께 반란을 일으킨 인물. 3회 장계에 이름만 나옴."},"악대":{"name":"악대","alias":["비사장군"],"sex":"M","note":"서달의 선봉. 평국과 맞대결 끝에 베임."},"철통골":{"name":"철통골","alias":["비룡장군"],"sex":"M","note":"서달의 선봉. 천문동 화공을 꾸밈. 벽파도에서 처형."},"무길":{"name":"무길","alias":["정서장군"],"sex":"M","note":"서달 쪽 장수. 보국에게 베임."},"충관":{"name":"충관","alias":["총서장군"],"sex":"M","note":"서달 쪽 장수. 거짓 패주로 보국을 포위에 빠뜨림."},"마하명":{"name":"마하명","alias":[],"sex":"M","note":"서달 쪽 중군장. 평국에게 베임."},"김성담":{"name":"김성담","alias":["석탐","옥문관 관수"],"sex":"M","note":"옥문관을 지키는 장수. 3회 p3에서는 김성담, p8에서는 석탐으로 나와 표기가 다름."},"오왕":{"name":"오왕","alias":[],"sex":"M","note":"초왕과 함께 2차 반란. 보국에게 사로잡혀 처형."},"초왕":{"name":"초왕","alias":[],"sex":"M","note":"오왕과 함께 반란, 맹길을 선봉으로 삼음. 보국에게 사로잡혀 처형."},"구덕지":{"name":"구덕지","alias":[],"sex":"M","note":"오왕의 대원수. 베는 장면 없이 그 머리가 황성으로 보내짐."},"운평":{"name":"운평","alias":[],"sex":"M","note":"오·초 쪽 장수. 보국에게 베임."},"관평":{"name":"관평","alias":[],"sex":"M","note":"맹길이 황성 기습을 떠나며 본진을 맡긴 장수."},"정연태":{"name":"정연태","alias":["정현태","우승상"],"sex":"M","note":"우승상. 평국의 재출전을 건의하고, 천자를 업고 북문으로 피란. 5회와 6회 표기가 다름."},"어의":{"name":"어의","alias":[],"sex":"M","note":"평국의 맥을 짚고 남자의 맥이 아니라고 천자에게 아룀."},"일봉암 여승":{"name":"일봉암 여승","alias":[],"sex":"F","note":"갈대밭에서 부인 일행을 배에 태워 맹길에게서 구함."},"고소대 노승":{"name":"고소대 노승","alias":["노승"],"sex":"미상","note":"부인을 상좌로 받아 삭발시키고 떠날 때 은 봉지를 줌."},"육환장 짚은 스님":{"name":"육환장 짚은 스님","alias":[],"sex":"M","note":"부인의 꿈에 나타나 벽파도로 가라 일러 줌. 부인은 부처의 인도로 여김."},"천명산 도사":{"name":"천명산 도사","alias":["도사"],"sex":"M","note":"익주 천명산 초당에서 위국공과 황후·태자를 머물게 하고 천기를 보아 돌아가라 함. 평국에게 봉서를 전하게 함. 봉서가 선생 필적이라 곽도사로 보임(원문 주석)."}},"places":{},"paras":[{"c":1,"sub":"제 일 회: 홍시랑이 만ᄅᆡ에 사속이 업다가 계월을 탄ᄉᆡᆼᄒᆞ고 길에셔 도젹을 만나 권속이 흣터지다","t":"이야기하자면, 대명(大明) 성화(成化) 연간에 형주(荊州) 구계촌에 한 사람이 있었는데, 성은 홍이요 이름은 무였다. 대대로 이름난 가문의 자손으로 젊어서 과거에 급제하여 벼슬이 이부시랑에 이르렀고, 충성스럽고 효성스러우며 곧은 성품이라 천자께서 아끼시어 나랏일을 함께 의논하셨다. 그러자 조정의 모든 관원이 시기하여 모함하니, 죄 없이 관직을 빼앗기고 고향에 돌아와 농사에 힘썼다. 살림은 넉넉했으나 슬하에 핏줄 하나 없어 늘 슬퍼하였다. 하루는 부인 양씨와 함께 서글피 탄식하며 말했다. \"우리 나이가 사십인데 아들이든 딸이든 자식이 없으니, 우리가 죽은 뒤에 대를 누구에게 전하며, 저승에 가서 조상을 어떻게 뵙겠소?\"","sp":[[102,104,"P","홍무"],[133,135,"P","천자"],[251,253,"P","양부인"],[254,256,"P","양부인"]]},{"c":1,"sub":"제 일 회: 홍시랑이 만ᄅᆡ에 사속이 업다가 계월을 탄ᄉᆡᆼᄒᆞ고 길에셔 도젹을 만나 권속이 흣터지다","t":"부인이 자리를 비켜 앉으며 대답했다. \"불효 삼천 가지 가운데 자식 없는 것이 가장 크다 하였습니다. 제가 이 댁에 몸을 의탁한 지 이십여 년인데 자식 하나 없으니 무슨 낯으로 상공을 뵙겠습니까? 바라건대 상공께서는 다른 가문의 어진 숙녀를 맞아 후손을 보시면 저도 칠거지악(七去之惡)의 허물을 면할까 합니다.\" 시랑이 위로하며 말했다. \"이는 모두 내 팔자이니 어찌 부인의 죄라 하겠소? 이후로는 그런 말씀 마시오.\" 이때는 가을 구월 보름 무렵이었다. 부인이 시비를 데리고 마월루에 올라 달빛을 구경하다가 갑자기 몸이 나른하여 난간에 기대어 졸았다. 꿈인 듯 생시인 듯한 사이에 하늘 문이 열리며 한 선녀가 내려와 두 번 절하고 말했다. \"소녀는 상제(上帝)의 시녀였는데 상제께 죄를 짓고 인간 세상으로 쫓겨나 갈 곳을 모르던 차에, 세존(世尊)께서 부인 댁을 가리켜 주시기에 왔습니다.\"","sp":[[0,2,"P","양부인"],[175,177,"P","홍무"],[206,208,"P","양부인"],[255,257,"P","양부인"],[338,340,"P","선녀"],[422,424,"P","양부인"]]},{"c":1,"sub":"제 일 회: 홍시랑이 만ᄅᆡ에 사속이 업다가 계월을 탄ᄉᆡᆼᄒᆞ고 길에셔 도젹을 만나 권속이 흣터지다","t":"하고는 품속으로 드는데, 놀라 깨어 보니 평생 처음 꾸는 큰 꿈이었다. 부인이 크게 기뻐하여 시랑을 청해 꿈 이야기를 하고 귀한 아들 보기를 바랐는데, 과연 그달부터 태기가 있어 열 달이 찼다. 하루는 집 안에 향기가 가득하고 부인이 몸이 나른하여 침상에 누웠다가 아이를 낳으니 딸이었다. 선녀가 하늘에서 내려와 옥병의 향수를 기울여 아이를 씻겨 눕히고 말했다. \"부인은 아기를 잘 길러 훗날 복을 받으십시오.\" 하고 나가면서 또 말했다. \"머지않아 다시 뵐 날이 있을 것입니다.\" 하고는 문득 간 곳이 없었다.","sp":[[40,42,"P","양부인"],[52,54,"P","홍무"],[127,129,"P","양부인"],[162,164,"P","선녀"],[204,206,"P","양부인"]]},{"c":1,"sub":"제 일 회: 홍시랑이 만ᄅᆡ에 사속이 업다가 계월을 탄ᄉᆡᆼᄒᆞ고 길에셔 도젹을 만나 권속이 흣터지다","t":"부인이 시랑을 청하여 아이를 보이니 얼굴이 복숭아꽃 같고 향기가 진동하여 참으로 달나라 항아(姮娥) 같았다. 기쁘기 그지없었으나 아들이 아닌 것을 한탄하였다. 이름을 계월(桂月)이라 하고 손바닥 위의 보옥처럼 아꼈다. 계월이 점점 자라니 얼굴이 화려하고 또한 영민하였다. 시랑은 계월이 혹시 단명할까 염려하여, 강호 땅에 사는 곽도사라는 산림의 은사를 청해 계월의 관상을 보였다. 도사가 한참 보다가 말했다. \"이 아이의 상을 보니 다섯 살에 부모와 헤어지고 열여덟 살에 부모를 다시 만나 공후(公侯)의 작위와 녹봉을 누릴 것이요, 명망이 천하에 으뜸이 될 것이니 매우 길합니다.\"","sp":[[0,2,"P","양부인"],[4,6,"P","홍무"],[93,95,"P","홍계월"],[122,124,"P","홍계월"],[152,154,"P","홍무"],[156,158,"P","홍계월"],[183,186,"P","곽도사"],[200,202,"P","홍계월"],[213,215,"P","곽도사"]]},{"c":1,"sub":"제 일 회: 홍시랑이 만ᄅᆡ에 사속이 업다가 계월을 탄ᄉᆡᆼᄒᆞ고 길에셔 도젹을 만나 권속이 흣터지다","t":"시랑이 그 말을 듣고 놀라 말했다. \"분명히 가르쳐 주십시오.\" 도사가 말했다. \"그 밖에는 아는 것이 없고, 하늘의 뜻을 누설할 수 없어 대강 말씀드린 것입니다.\" 하고 작별하고 떠났다. 시랑은 도사의 말을 듣고 차라리 듣지 않은 것만 못하다고 여겨, 부인에게 이 말을 전하고 끝없이 걱정하였다. 그래서 계월에게 남자 옷을 입혀 초당에 두고 글을 가르치니, 하나를 들으면 열을 아는 재주였다. 시랑이 탄식하며 말했다. \"네가 만일 남자로 태어났더라면 우리 가문을 빛낼 것을.\" 하며 애달파하였다.","sp":[[0,2,"P","홍무"],[36,38,"P","곽도사"],[106,108,"P","홍무"],[110,112,"P","곽도사"],[142,144,"P","양부인"],[171,173,"P","홍계월"],[221,223,"P","홍무"]]},{"c":1,"sub":"제 일 회: 홍시랑이 만ᄅᆡ에 사속이 업다가 계월을 탄ᄉᆡᆼᄒᆞ고 길에셔 도젹을 만나 권속이 흣터지다","t":"세월이 물 흐르듯 지나 계월의 나이가 다섯 살이 되었다. 이때 시랑은 친구를 찾아갈 생각으로 정도사를 만나러 길을 나섰다. 원래 정도사는 황성에서 함께 벼슬하던 아주 친한 벗이었는데, 소인의 참소를 만나 벼슬을 내놓고 호계촌에 돌아온 지 수십 년이었다. 시랑이 이날 떠나 양주로 향하여 호계촌을 찾아가니 삼백오십 리 길이었다. 여러 날 만에 이르자 정도사가 시랑을 보고 대청에서 내려와 손을 잡고 뜻밖의 일이라 크게 기뻐하였다. 자리를 정해 앉은 뒤 그동안 쌓인 회포를 풀며 말했다. \"이 몸이 벼슬을 그만두고 이곳에 돌아와 초목에 기대어 세월을 보내는데, 다른 벗이 없어 늘 적막하였습니다. 천만뜻밖에 시랑께서 천 리를 멀다 않고 이렇게 버려진 몸을 찾아 위로해 주시니 감격하기 그지없습니다.\" 하며 즐거워하였다.","sp":[[13,15,"P","홍계월"],[35,37,"P","홍무"],[52,55,"P","정도사"],[72,75,"P","정도사"],[142,144,"P","홍무"],[195,198,"P","정도사"],[200,202,"P","홍무"],[338,340,"P","홍무"]]},{"c":1,"sub":"제 일 회: 홍시랑이 만ᄅᆡ에 사속이 업다가 계월을 탄ᄉᆡᆼᄒᆞ고 길에셔 도젹을 만나 권속이 흣터지다","t":"시랑은 사흘 뒤에 작별하고 떠나니 서운한 마음을 어찌 다 헤아리겠는가. 시랑이 이날 여람 북촌에 와서 자고 이튿날 닭이 울 때 떠나려 하는데, 멀리서 징과 북 소리가 들리고 고각(鼓角) 소리와 함성이 진동하며 땅이 울렸다. 시랑이 놀라 바라보니 여러 백성이 쫓겨 오기에 급히 물었더니 이렇게 대답하였다. \"북방 절도사 장사랑이 양주 목사 주도와 합세하여 군사 십만을 거느리고 구십여 성의 항복을 받고, 기주 자사 장기덕을 베고, 지금 황성을 침범하여 난리가 매우 심합니다. 백성을 무수히 죽이고 재산을 노략하니, 살길을 찾아 피란하는 사람이 이루 헤아릴 수 없습니다.\"","sp":[[0,2,"P","홍무"],[40,42,"P","홍무"],[125,127,"P","홍무"],[171,181,"P","장사랑"],[183,188,"P","주도"],[189,191,"P","주도"]]},{"c":1,"sub":"제 일 회: 홍시랑이 만ᄅᆡ에 사속이 업다가 계월을 탄ᄉᆡᆼᄒᆞ고 길에셔 도젹을 만나 권속이 흣터지다","t":"시랑이 그 말을 듣고 정신이 아득하여 산속으로 들어가며 부인과 계월을 생각하고 슬피 우니 그 처지가 가련하였다. 이때 부인은 시랑이 돌아오기를 기다리고 있었는데, 이날 밤 문득 떠드는 소리가 요란하여 놀라 깨니 시비 양윤이 아뢰었다. \"북방 도적이 천 명의 군사와 만 필의 말을 몰고 들어와 백성을 무수히 죽이고 노략하니 이 일을 어찌합니까?\" 부인이 크게 놀라 계월을 안고 통곡하며 말했다. \"이제는 시랑께서 길에서 도적의 모진 칼에 돌아가셨구나.\"","sp":[[0,2,"P","홍무"],[31,33,"P","양부인"],[35,37,"P","홍계월"],[66,68,"P","양부인"],[70,72,"P","홍무"],[118,123,"P","양윤"],[193,195,"P","양부인"],[203,205,"P","홍계월"],[225,227,"P","홍무"]]},{"c":1,"sub":"제 일 회: 홍시랑이 만ᄅᆡ에 사속이 업다가 계월을 탄ᄉᆡᆼᄒᆞ고 길에셔 도젹을 만나 권속이 흣터지다","t":"하며 자결하려 하자 양윤이 위로하였다. \"아직 시랑의 생사를 모르는데 어찌 이러십니까?\" 부인이 그렇다고 여겨 마음을 진정하고, 울면서 계월을 양윤의 등에 업히고 남쪽으로 향해 갔다. 십 리를 가니 큰 강이 막아섰다. 부인이 망극하여 하늘을 우러러 통곡하며 말했다. \"이제 도적이 급히 쫓아오니 차라리 이 강물에 빠져 죽겠다.\" 하고 계월을 안고 물에 뛰어들려 하였다. 양윤이 붙들고 통곡하는데, 문득 북쪽 바다 위에서 처량한 소리가 들려왔다.","sp":[[11,13,"P","양윤"],[26,28,"P","홍무"],[50,52,"P","양부인"],[76,78,"P","홍계월"],[80,82,"P","양윤"],[122,124,"P","양부인"],[187,189,"P","홍계월"],[207,209,"P","양윤"]]},{"c":1,"sub":"제 일 회: 홍시랑이 만ᄅᆡ에 사속이 업다가 계월을 탄ᄉᆡᆼᄒᆞ고 길에셔 도젹을 만나 권속이 흣터지다","t":"바라보니 한 선녀가 작은 배를 타고 오며 말했다. \"부인은 잠깐만 참으십시오.\" 순식간에 배를 대고 오르기를 청하였다. 부인이 황송하고 감격하여 양윤과 계월을 데리고 급히 오르니, 선녀가 배를 저으며 말했다. \"부인께서는 소녀를 알아보시겠습니까? 소녀는 해산하실 때 돌보아 드리던 선녀입니다.\" 부인이 정신을 수습해 자세히 보고 그제야 깨닫고 말했다. \"우리는 인간 세상의 미물이라 눈이 어두워 몰라보았습니다.\" 하며 사례하였다. \"그때 인간 세상에 오셨다가 총총히 이별한 뒤로 생각이 간절하여 잊은 날이 없었는데, 오늘 이렇게 만나니 다행이고, 또 물에 빠져 죽을 목숨을 구해 주시니 고마움이 그지없어 이 은혜를 어찌 다 갚겠습니까?\"","sp":[[7,9,"P","선녀"],[29,31,"P","양부인"],[67,69,"P","양부인"],[81,83,"P","양윤"],[85,87,"P","홍계월"],[101,103,"P","선녀"],[118,120,"P","양부인"],[157,159,"P","선녀"],[165,167,"P","양부인"]]},{"c":1,"sub":"제 일 회: 홍시랑이 만ᄅᆡ에 사속이 업다가 계월을 탄ᄉᆡᆼᄒᆞ고 길에셔 도젹을 만나 권속이 흣터지다","t":"선녀가 말했다. \"소녀는 도반선생을 모시러 가던 길인데, 만일 조금만 늦었더라면 구하지 못할 뻔했습니다.\" 하고 능파곡(凌波曲)을 부르며 저어 가는데 빠르기가 화살 같았다. 순식간에 언덕에 배를 대고 내리기를 재촉하였다. 부인이 배에서 내려 끝없이 사례하니 선녀가 말했다. \"부인은 삼가 몸을 천만 보중하십시오.\" 하고 배를 저어 가니, 그 가는 배를 알아볼 수 없었다. 부인이 공중을 향해 수없이 절하고 갈대밭 속으로 들어가며 살펴보니, 초(楚)나라 물은 만 굽이요 오(吳)나라 산은 천 봉우리였다.","sp":[[0,2,"P","선녀"],[16,18,"P","곽도사"],[124,126,"P","양부인"],[144,146,"P","선녀"],[154,156,"P","양부인"],[208,210,"P","양부인"]]},{"c":1,"sub":"제 일 회: 홍시랑이 만ᄅᆡ에 사속이 업다가 계월을 탄ᄉᆡᆼᄒᆞ고 길에셔 도젹을 만나 권속이 흣터지다","t":"양윤이 계월을 시냇가에 앉혀 두고 두루 다니며 칡뿌리도 캐어 먹고 버들개지도 훑어 먹어 겨우 기운을 차리고 점점 들어가니, 정자 하나가 있었다. 나아가 보니 현판에 '엄자릉(嚴子陵)의 조대(釣臺)'라고 새겨져 있었다. 엄자릉이 낚시하던 자리라는 뜻이다. 그 정자에 올라 잠시 쉬면서 양윤은 마을에 밥을 얻으러 보내고, 부인은 계월을 안고 홀로 앉아 있었다. 문득 보니 강 위에서 큰 배 한 척이 정자를 향해 오기에, 부인이 놀라 계월을 안고 대숲으로 들어가 숨었다. 배가 점점 가까이 와 정자 앞에 매이더니 한 놈이 말했다. \"아까 강 위에서 바라보니 여인 하나가 앉아 있다가 우리를 보고 저 숲으로 들어갔으니 급히 찾아라.\"","sp":[[0,2,"P","양윤"],[4,6,"P","홍계월"],[158,160,"P","양윤"],[178,180,"P","양부인"],[182,184,"P","홍계월"],[233,235,"P","양부인"],[240,242,"P","홍계월"]]},{"c":1,"sub":"제 일 회: 홍시랑이 만ᄅᆡ에 사속이 업다가 계월을 탄ᄉᆡᆼᄒᆞ고 길에셔 도젹을 만나 권속이 흣터지다","t":"하니 모든 사람이 한꺼번에 내달아 수풀 속으로 달려들어 부인을 잡아갔다. 부인이 정신이 아득하여 양윤을 부르며 통곡한들 밥을 빌러 간 양윤이 어찌 알겠는가. 도적들이 등을 떠밀며 잡아다가 뱃머리에 꿇리고 무수히 희롱하였다. 원래 이 배는 수적(水賊)의 배로, 물 위를 다니며 재물도 빼앗고 부녀자도 겁탈하는데, 마침 이곳을 지나다가 부인을 만난 것이었다. 수적의 우두머리 맹길이라는 놈이 부인의 꽃 같은 얼굴과 달 같은 자태를 보고 마음에 품어 말했다. \"내 평생 천하에 으뜸가는 미인을 얻고자 했더니 하늘이 가르쳐 주신 것이다.\"","sp":[[31,33,"P","양부인"],[41,43,"P","양부인"],[54,56,"P","양윤"],[75,77,"P","양윤"],[186,188,"P","양부인"],[208,210,"P","맹길"],[217,219,"P","양부인"]]},{"c":1,"sub":"제 일 회: 홍시랑이 만ᄅᆡ에 사속이 업다가 계월을 탄ᄉᆡᆼᄒᆞ고 길에셔 도젹을 만나 권속이 흣터지다","t":"하고 기뻐하였다. 부인이 하늘을 우러러 탄식하였다. \"이제 시랑의 생사도 알지 못한 채 목숨을 보전하여 오다가 이곳에서 이런 변을 만날 줄 어찌 알았으랴.\" 하며 통곡하니 초목과 짐승도 다 슬퍼하는 듯하였다. 맹길이 부인이 슬퍼하는 것을 보고 도적들에게 분부하였다. \"저 부인을 손발을 놀리지 못하게 비단으로 묶고, 계월은 자리에 싸서 강물에 던져라.\" 부인이 손을 놀리지 못하자 몸을 기울여 계월의 옷을 입으로 물고 놓지 않았다. 맹길이 달려들어 계월의 옷을 칼로 베고 계월을 물에 던지니, 그 불쌍하고 딱한 광경을 어찌 다 헤아리겠는가.","sp":[[10,12,"P","양부인"],[33,35,"P","홍무"],[117,119,"P","맹길"],[121,123,"P","양부인"],[152,154,"P","양부인"],[177,179,"P","홍계월"],[198,200,"P","양부인"],[220,222,"P","홍계월"],[242,244,"P","맹길"],[251,253,"P","홍계월"],[264,266,"P","홍계월"]]},{"c":1,"sub":"제 일 회: 홍시랑이 만ᄅᆡ에 사속이 업다가 계월을 탄ᄉᆡᆼᄒᆞ고 길에셔 도젹을 만나 권속이 흣터지다","t":"계월이 물에 떠가며 울면서 말했다. \"어머니, 이게 웬일이오? 어머니, 나는 죽소. 어서 살려 주십시오. 물에 떠가는 자식더러 넓은 물결 속 물고기 밥이 되라 하십니까? 어머님, 어머님, 얼굴이나 다시 보옵시다. 죽어도 눈을 감지 못하겠소.\" 하며 울음소리가 점점 멀어져 갔다. 부인은 손바닥 위의 보옥처럼 아끼던 자식이 눈앞에서 물에 빠져 죽는 모습을 보니 어찌 정신이 아득하지 않겠는가. \"계월아, 계월아, 나와 함께 죽자.\" 하며 하늘을 우러러 통곡하다 기절하니, 배 안의 사람들도 비록 도적이지만 눈물을 흘리지 않는 이가 없었다.","sp":[[0,2,"P","홍계월"],[156,158,"P","양부인"],[220,222,"P","홍계월"],[225,227,"P","홍계월"]]},{"c":1,"sub":"제 일 회: 홍시랑이 만ᄅᆡ에 사속이 업다가 계월을 탄ᄉᆡᆼᄒᆞ고 길에셔 도젹을 만나 권속이 흣터지다","t":"슬프다. 양윤이 밥을 빌어 가지고 오다가 바라보니 정자 앞에 사람이 많은데 부인의 울음소리가 들렸다. 급히 가 보니 부인을 묶어 놓고 분주하였다. 양윤이 이 모습을 보고 얻은 밥을 그릇째 던지고 부인을 붙들며 크게 통곡하였다. \"이게 웬일입니까? 차라리 올 때 그 물에 빠져 죽었더라면 이런 일은 당하지 않았을 것을, 이 일을 어찌합니까? 아기는 어디 있습니까?\" \"아기는 물에 빠져 죽었다.\" 하니 양윤이 이 말을 듣고 가슴을 두드리며 물에 뛰어들려 하였다. 맹길이 또 도적들에게 호령하였다. \"저 계집도 마저 묶어라.\"","sp":[[5,7,"P","양윤"],[42,44,"P","양부인"],[65,67,"P","양부인"],[82,84,"P","양윤"],[109,111,"P","양부인"],[224,226,"P","양윤"],[258,260,"P","맹길"]]},{"c":1,"sub":"제 일 회: 홍시랑이 만ᄅᆡ에 사속이 업다가 계월을 탄ᄉᆡᆼᄒᆞ고 길에셔 도젹을 만나 권속이 흣터지다","t":"하니 도적 무리가 달려들어 양윤도 마저 묶었다. 양윤은 죽지도 못하고 하늘을 우러러 통곡할 뿐이었다. 맹길이 도적들을 재촉하여 부인과 양윤을 배에 싣고 급히 저어 제 집으로 돌아왔다. 부인과 양윤을 침방에 가두고 제 계집 춘낭을 불러 말했다. \"내가 부인을 데려왔으니 너는 좋은 말로 달래어 부인의 마음을 누그러뜨려라.\" 춘낭이 부인에게 들어와 물었다. \"부인은 무슨 일로 이곳에 오셨습니까?\" 부인이 대답하였다. \"주인 부인께서는 죽게 된 이 목숨을 살려 주십시오.\"","sp":[[15,17,"P","양윤"],[27,29,"P","양윤"],[57,59,"P","맹길"],[71,73,"P","양부인"],[75,77,"P","양윤"],[103,105,"P","양부인"],[107,109,"P","양윤"],[124,126,"P","춘낭"],[140,142,"P","양부인"],[163,165,"P","양부인"],[180,182,"P","춘낭"],[184,186,"P","양부인"],[199,201,"P","양부인"],[221,223,"P","양부인"],[236,238,"P","양부인"]]},{"c":1,"sub":"제 일 회: 홍시랑이 만ᄅᆡ에 사속이 업다가 계월을 탄ᄉᆡᆼᄒᆞ고 길에셔 도젹을 만나 권속이 흣터지다","t":"하며 앞뒤 사정을 다 이야기하니 춘낭이 말했다. \"부인의 처지를 보니 참혹합니다.\" 하고 이어 말했다. \"주인놈은 본래 수적으로 사람을 많이 죽였고, 또 용맹하여 하루에 천 리를 가니 도망하기도 어렵고 죽으려 해도 죽을 수 없을 것입니다. 아무리 생각해도 불쌍하고 가련합니다. 저도 본래 이 도적놈의 계집이 아니라 대국 번양 땅에 사는 양각로의 딸로, 일찍 남편을 잃고 지내다가 이놈에게 잡혀 와 목숨을 부지하려고 이놈의 계집이 되었습니다. 모진 목숨이 죽지 못하고 고향을 생각하면 정신이 아득합니다. 그러나 잠깐 생각해 보니 좋은 꾀가 하나 있습니다. 하늘이 도와 그 꾀대로 되면 저도 부인과 함께 도망하려 하니 의심하지 마십시오.\" 하고 곧 나가 도적들이 모인 곳에 가 보니,","sp":[[18,20,"P","춘낭"],[28,30,"P","양부인"],[329,331,"P","양부인"]]},{"c":1,"sub":"제 일 회: 홍시랑이 만ᄅᆡ에 사속이 업다가 계월을 탄ᄉᆡᆼᄒᆞ고 길에셔 도젹을 만나 권속이 흣터지다","t":"등불을 밝히고 도적들이 좌우로 갈라 앉아 잔치를 벌이고 술과 고기로 즐기고 있었다. 각각 잔을 들어 맹길에게 축하하였다. \"오늘 장군께서 미인을 얻으셨으니 한 잔 술로 축하드립니다.\" 하고 저마다 한 잔씩 권하니 맹길이 크게 취해 쓰러지고 다른 장수들도 다 잠들었다. 춘낭이 급히 들어와 부인에게 일렀다. \"지금 도적들이 잠이 깊이 들었으니 어서 서문을 열고 도망합시다.\" 하고 곧 수건에 밥을 싸 가지고 부인과 양윤을 데리고 이날 밤 도망하여 서쪽으로 갔다. 그러나 정신이 혼미하여 한 걸음 떼기도 어려웠다.","sp":[[56,58,"P","맹길"],[119,121,"P","맹길"],[150,152,"P","춘낭"],[161,163,"P","양부인"],[227,229,"P","양부인"],[231,233,"P","양윤"]]},{"c":1,"sub":"제 일 회: 홍시랑이 만ᄅᆡ에 사속이 업다가 계월을 탄ᄉᆡᆼᄒᆞ고 길에셔 도젹을 만나 권속이 흣터지다","t":"동쪽 하늘이 벌써 밝았는데 강 위에서 외기러기 우는 소리가 슬픈 마음을 더하였다. 문득 바라보니 한쪽은 큰 산이요 한쪽은 큰 강이었다. 갈대밭 속으로 들어가는데 부인은 기운이 다하여 춘낭을 돌아보며 말했다. \"날은 이미 밝았고 기운이 다해 갈 길이 없으니 어찌하자는 말인가.\" 하고 하늘을 우러러 통곡하였다. 그때 문득 갈대밭 속에서 한 여승이 나와 부인에게 절하고 여쭈었다. \"어떤 부인이시기에 이런 험한 곳에 오셨습니까?\" 부인이 말했다. \"스님은 어디 계신 분인지, 남은 목숨을 구해 주십시오.\" [?]","sp":[[90,92,"P","양부인"],[102,104,"P","춘낭"],[196,198,"P","양부인"],[215,217,"P","양부인"],[239,241,"P","양부인"]]},{"c":1,"sub":"제 일 회: 홍시랑이 만ᄅᆡ에 사속이 업다가 계월을 탄ᄉᆡᆼᄒᆞ고 길에셔 도젹을 만나 권속이 흣터지다","t":"하며 앞뒤 사정을 이야기하고 간청하니 그 여승이 말했다. \"부인의 처지를 보니 딱합니다.\" 하고 아뢰었다. \"소승은 일봉암에 있는데, 한 산사에 가서 양식을 싣고 오는 길에 처량한 울음소리가 들리기에 연유를 물으려고 배를 강변에 매고 찾아왔습니다. 소승을 따라 급한 화를 피하십시오.\" 하고 배에 오르기를 재촉하였다. 부인은 고마움을 이기지 못하여 춘낭과 양윤을 데리고 배에 올랐다. 이때 맹길이 잠을 깨어 침방에 들어가 보니 부인과 춘낭 두 사람이 간 곳이 없었다.","sp":[[33,35,"P","양부인"],[178,180,"P","양부인"],[195,197,"P","춘낭"],[199,201,"P","양윤"],[218,220,"P","맹길"],[239,241,"P","양부인"],[243,245,"P","춘낭"]]},{"c":1,"sub":"제 일 회: 홍시랑이 만ᄅᆡ에 사속이 업다가 계월을 탄ᄉᆡᆼᄒᆞ고 길에셔 도젹을 만나 권속이 흣터지다","t":"맹길은 분을 참지 못하여 도적들을 거느리고 두루 찾다가 강 위를 바라보니, 여승과 세 사람이 배에 앉아 있었다. 맹길이 소리를 크게 지르며 도적들을 재촉해 따라왔으나, 여승이 배를 급히 저어 가니 빠르기가 화살 같았다. 맹길은 바라보다가 어쩔 수 없어 탄식만 하고 돌아갔다. 이때 여승이 배를 승경문 밖에 대고 내리라 하였다. 부인이 배에서 내려 여승을 따라 고소대(姑蘇臺)로 올라가 여러 스님에게 절하고 앉으니, 그중 한 노승이 물었다. \"부인은 어디 사시며 무슨 일로 이 산중에 들어오셨습니까?\" 부인이 대답하였다. \"형주 땅에 살았는데 명산으로 피신하여 정처 없이 가다가 다행히 스님을 만나 이곳에 왔습니다. 스님께 의탁하여 머리를 깎고 중이 되어 다음 생의 길이나 닦고자 합니다.\"","sp":[[0,2,"P","맹길"],[63,65,"P","맹길"],[123,125,"P","맹길"],[183,185,"P","양부인"],[237,239,"P","고소대 노승"],[247,249,"P","양부인"],[280,282,"P","양부인"]]},{"c":1,"sub":"제 일 회: 홍시랑이 만ᄅᆡ에 사속이 업다가 계월을 탄ᄉᆡᆼᄒᆞ고 길에셔 도젹을 만나 권속이 흣터지다","t":"노승이 그 말을 듣고 말했다. \"소승에게는 상좌(上佐)가 없으니 부인의 소원이 그러하시면 원하는 대로 합시다.\" 하고 곧 목욕재계하고 머리를 깎아 중이 되게 하였다. 부인은 노승의 상좌가 되고 춘낭과 양윤은 부인의 상좌가 되어, 이날부터 부처 앞에 '시랑과 계월을 만나게 해 주십시오.' 하고 빌며 세월을 보냈다. 한편 이때 계월은 물에 떠가며 울며 말했다. \"나는 이미 죽거니와 어머님은 아무쪼록 목숨을 보전하시어 다행히 아버님을 만나 이 일을 알리게 하십시오.\"","sp":[[0,2,"P","고소대 노승"],[36,38,"P","양부인"],[93,95,"P","양부인"],[97,99,"P","고소대 노승"],[108,110,"P","춘낭"],[112,114,"P","양윤"],[116,118,"P","양부인"],[140,142,"P","홍무"],[144,146,"P","홍계월"],[182,184,"P","홍계월"]]},{"c":1,"sub":"제 일 회: 홍시랑이 만ᄅᆡ에 사속이 업다가 계월을 탄ᄉᆡᆼᄒᆞ고 길에셔 도젹을 만나 권속이 흣터지다","t":"하며 슬피 울며 떠갔다. 이때 무릉포에 사는 여공이라는 사람이 배를 타고 서촉으로 가다가 강 위를 바라보니, 어떤 아이가 자리에 싸여 떠가며 우는 소리가 들렸다. 그곳에 이르러 배를 멈추고 자리를 건져 보니 어린아이였다. 그 아이 모습을 보니 인물이 빼어나고 아름다운데 정신을 차리지 못하므로, 여공이 약으로 구호하였다. 한참 뒤 깨어나 어머니를 부르는 소리가 차마 듣지 못할 지경이었다.","sp":[[25,27,"P","여공"],[165,167,"P","여공"]]},{"c":2,"sub":"졔 이 회: 여공이 계월을 거두어 양육ᄒᆞ고 양부인이 만리고도에 홍시랑을 만나다","t":"한편 여공이 그 아이를 데리고 집에 돌아와 물었다. \"너는 어떤 아이이기에 넓은 물결 속에서 이런 일을 당하였느냐?\" 계월이 울며 말했다. \"저는 어머님과 함께 가다가 어떤 사람이 어머님을 묶고 저는 자리에 싸서 물에 던져 죽게 되었는데, 다행히 살았습니다.\" 여공이 그 말을 듣고 속으로 생각하기를 '필시 수적을 만났구나.' 하고 다시 물었다. \"네 나이는 몇이며 이름은 무엇이냐?\" \"나이는 다섯 살이고 이름은 계월입니다.\" \"살던 곳은 어디냐?\" 계월이 대답하였다. \"아버님 이름은 모르지만 남들이 홍시랑이라고 부릅니다.\"","sp":[[3,5,"P","여공"],[66,68,"P","홍계월"],[146,148,"P","여공"],[232,234,"P","홍계월"],[253,255,"P","홍계월"],[282,285,"P","홍무"]]},{"c":2,"sub":"졔 이 회: 여공이 계월을 거두어 양육ᄒᆞ고 양부인이 만리고도에 홍시랑을 만나다","t":"하니 여공이 '분명 양반의 자식이로구나.' 하고 말했다. \"이 아이는 내 아들과 동갑이고 얼굴도 비범하니 잘 길러 장래에 영화를 보리라.\" 하고 친자식같이 여겼다. 그 아들의 이름은 보국이었는데, 생김새 또한 비범한 기남자였다. 아들 이름을 지은 뒤로 몹시 아끼며 길렀는데, 계월을 보고는 보국이 친동기처럼 여겼다. 세월이 물 흐르듯 지나 두 아이가 일곱 살에 이르니 모든 일이 비범하여 칭찬하지 않는 이가 없었다.","sp":[[3,5,"P","여공"],[102,104,"P","보국"],[154,156,"P","홍계월"],[162,164,"P","보국"]]},{"c":2,"sub":"졔 이 회: 여공이 계월을 거두어 양육ᄒᆞ고 양부인이 만리고도에 홍시랑을 만나다","t":"여공은 아이들에게 글을 가르치고자 하여, 강호 땅 월호산 명현동에 곽도사가 있다는 말을 듣고 두 아이를 데리고 명현동을 찾아갔다. 도사가 초당에 앉아 있기에 여공이 당 위에 올라 인사를 마치고 자리에 앉은 뒤 여쭈었다. \"저는 무릉포에 사는 여공입니다. 늦게야 자식을 두었는데 영민하기에 도사님의 덕택으로 사람 구실을 할까 하여 왔습니다.\" 도사가 아이를 부르라 하니 여공이 두 아이를 불러 뵈었다. 도사가 한참 보다가 말했다. \"이 아이들의 상을 보니 친동기가 아닌 것이 분명하니 숨기지 말고 바로 말씀하십시오.\"","sp":[[0,2,"P","여공"],[37,40,"P","곽도사"],[73,75,"P","곽도사"],[88,90,"P","여공"],[135,137,"P","여공"],[161,163,"P","곽도사"],[191,193,"P","곽도사"],[206,208,"P","여공"],[224,226,"P","곽도사"]]},{"c":2,"sub":"졔 이 회: 여공이 계월을 거두어 양육ᄒᆞ고 양부인이 만리고도에 홍시랑을 만나다","t":"하니 여공이 그 말을 듣고 말했다. \"선생의 사람 알아보는 눈은 귀신같습니다.\" 도사가 말했다. \"이 아이들을 잘 가르쳐 이름을 역사에 빛나게 하리라.\" 여공이 사례하고 작별하여 돌아왔다. 한편 이때 홍시랑은 산속에 몸을 숨기고 있었는데, 도적이 그 산속에 들어와 백성의 재물을 노략하고 사람을 붙잡아 군사로 삼다가 마침 홍시랑을 붙잡았다. 사람됨이 비범하여 차마 죽이지 못하고 도적들과 의논하였다. \"이 사람을 군중에 두는 것이 어떠한가?\" 도적들이 기꺼이 따르니, 장사랑이 곧 홍시랑을 불러 말했다. \"우리와 함께 마음과 힘을 합하여 황성을 치자.\" 홍시랑이 생각하기를 '만일 듣지 않으면 죽음을 면치 못하겠다.' 하고 마지못해 거짓으로 항복하고 황성으로 향하였다.","sp":[[3,5,"P","여공"],[21,23,"P","곽도사"],[45,47,"P","곽도사"],[86,88,"P","여공"],[112,115,"P","홍무"],[180,183,"P","홍무"],[262,265,"P","장사랑"],[269,272,"P","홍무"],[310,313,"P","홍무"]]},{"c":2,"sub":"졔 이 회: 여공이 계월을 거두어 양육ᄒᆞ고 양부인이 만리고도에 홍시랑을 만나다","t":"이때 천자께서 유성을 대원수로 삼아 군사를 거느리고 임치 땅에서 도적을 쳐부수고, 장사랑을 붙잡아 앞세워 황성으로 가는데 홍시랑도 진중에 있다가 붙잡혔다. 홍시랑이 크게 소리쳐 아뢰었다. \"소신은 피란하여 산속에 있다가 도적에게 붙잡혔습니다.\" 하며 앞뒤 사정을 낱낱이 아뢰었다. 이때 양주 자사를 지낸 정덕기가 이 말을 듣고 엎드려 아뢰었다. \"저 죄인은 시랑 벼슬을 하던 홍무입니다.\" 천자께서 그 말을 들으시고 자세히 보시다가 말씀하셨다. \"너는 일찍이 벼슬을 하였으니 차라리 죽을지언정 도적의 무리에 드는 것이 옳으냐? 죄를 따지면 죽일 것이로되 지난 일을 생각하여 귀양을 보내노라.\" 하시고 형관에게 명하여 곧 홍시랑을 벽파도로 귀양 보내라 하시니, 거리가 일만 팔천 리였다. 시랑은 고향에 돌아가 부인과 계월도 보지 못하고,","sp":[[3,5,"P","천자"],[8,10,"P","유성"],[13,15,"P","홍계월"],[46,49,"P","장사랑"],[68,71,"P","홍무"],[87,90,"P","홍무"],[170,173,"P","정덕기"],[200,202,"P","홍무"],[210,212,"P","홍무"],[218,220,"P","천자"],[347,350,"P","홍무"],[384,386,"P","홍무"],[396,398,"P","양부인"],[400,402,"P","홍계월"]]},{"c":2,"sub":"졔 이 회: 여공이 계월을 거두어 양육ᄒᆞ고 양부인이 만리고도에 홍시랑을 만나다","t":"\"만 리 타국으로 귀양을 가니 이런 팔자가 어디 있으랴.\" 하며 슬피 통곡하니 보는 사람마다 눈물을 흘리지 않는 이가 없었다. 길을 떠난 지 여덟 달 만에 벽파도에 이르니, 그곳은 오나라와 초나라 사이였다. 원래 벽파도는 사람의 발길이 닿지 않는 곳이었다. 이곳에 보내신 것은 홍무를 굶어 죽게 하려는 뜻이었다. 형관이 시랑을 그곳에 두고 돌아가니, 시랑은 하늘과 땅이 아득하여 밤낮으로 울며 굶주림을 견디지 못해 물가를 다니며 죽은 물고기와 바위 위에 붙은 굴만 주워 먹고 세월을 보냈다. 옷이 해어져 몸을 가리지 못하고, 모습이 괴이하며 온몸에 털이 나서 짐승의 모양이었다. 한편 이때 부인은 춘낭과 양윤을 데리고 산중에서 눈물로 세월을 보내는데, 한 스님이 육환장(六環杖)을 짚고 앞에 와서 절하고 말했다. \"부인은 무정한","sp":[[155,157,"P","홍무"],[179,181,"P","홍무"],[196,198,"P","홍무"],[330,332,"P","양부인"],[334,336,"P","춘낭"],[338,340,"P","양윤"],[400,402,"P","양부인"]]},{"c":2,"sub":"졔 이 회: 여공이 계월을 거두어 양육ᄒᆞ고 양부인이 만리고도에 홍시랑을 만나다","t":"산중에서 풍경만 대하고 시랑과 계월을 찾지 않으십니까? 지금 시랑께서 바다 가운데 섬에 계시며 부인과 계월을 생각하다 병이 골수에 들었으니 어서 가십시오. 가다가 벽파도를 물어 그곳에서 시랑을 찾아 고향 소식을 물으면 자연히 시랑을 만날 것입니다.\" 하고는 문득 간 곳이 없었다. 부인이 꿈을 깨어 크게 놀라고 의아하여 양윤과 춘낭을 불러 꿈 이야기를 하고 말했다. \"가다가 길에서 외로운 넋이 될지라도 가겠다.\" 하고 곧 행장을 차려 노승에게 작별하며 말했다. \"제가 만 리 타국에 와서 스님의 은혜를 입어 남은 목숨을 보전하였으니 그 은혜는 백골이 되어도 잊기 어렵습니다. 그런데 간밤 꿈이 이러이러하니 부처님께서 인도하시는 것입니다.","sp":[[13,15,"P","홍무"],[17,19,"P","홍계월"],[34,36,"P","홍무"],[53,55,"P","양부인"],[57,59,"P","홍계월"],[104,106,"P","홍무"],[126,128,"P","홍무"],[157,159,"P","양부인"],[179,181,"P","양윤"],[183,185,"P","춘낭"],[244,246,"P","고소대 노승"]]},{"c":2,"sub":"졔 이 회: 여공이 계월을 거두어 양육ᄒᆞ고 양부인이 만리고도에 홍시랑을 만나다","t":"그래서 작별을 고합니다.\" 하며 눈물을 흘리니 노승도 눈물을 흘리며 말했다. \"나도 부인을 만난 뒤로 모든 일을 다 부인에게 맡겼는데 오늘 이별을 당하니 이 슬픈 마음을 장차 어찌하리오.\" 하고 은 봉지 하나를 주며 말했다. \"이것으로 정을 표하니 궁할 때 쓰십시오.\" 부인이 감사하여 양윤에게 맡기고 작별하여 절 문을 떠나니, 노승과 여러 스님이 나와 서로 눈물을 흘리며 떠나는 정을 못내 애달파하였다. 부인이 춘낭과 양윤을 데리고 동쪽으로 내려가는데, 수많은 골짜기와 봉우리가 눈앞에 어려 있고 초목은 울창한데 무심한 두견새 소리가 사람의 시름을 돋우었다.","sp":[[26,28,"P","고소대 노승"],[47,49,"P","양부인"],[65,67,"P","양부인"],[151,153,"P","양부인"],[160,162,"P","양윤"],[184,186,"P","고소대 노승"],[227,229,"P","양부인"],[231,233,"P","춘낭"],[235,237,"P","양윤"]]},{"c":2,"sub":"졔 이 회: 여공이 계월을 거두어 양육ᄒᆞ고 양부인이 만리고도에 홍시랑을 만나다","t":"눈물을 참지 못하며 어디로 가야 할지 몰라 한 걸음 한 걸음 나아갔다. 한 곳을 바라보니 북쪽에 작은 길이 있어 그 길로 가며 보니, 앞에 큰 강이 있고 그 위에 누각이 있었다. 나아가 보니 현판에 '악양루(岳陽樓)'라고 쓰여 있었다. 사방을 살펴보니 동정호 칠백 리는 눈앞에 둘러 있고 무산(巫山) 열두 봉우리는 구름 속에 솟아 있어 갖가지 풍경을 이루 헤아릴 수 없었다. 부인은 슬픈 회포를 이기지 못하여 한숨 쉬며 서글퍼하다가, 또 한 곳에 이르니 큰 돌다리가 있었다.","sp":[[210,212,"P","양부인"]]},{"c":2,"sub":"졔 이 회: 여공이 계월을 거두어 양육ᄒᆞ고 양부인이 만리고도에 홍시랑을 만나다","t":"그곳 사람에게 물으니 장판교라 하였다. 또 물었다. \"이곳에서 황성이 얼마나 됩니까?\" 대답하였다. \"일만 팔천 리라 하는데, 저 다리를 건너 백 리만 가면 옥문관이 있으니 그곳에 가서 물으면 자세히 알 것입니다.\" 또 물었다. \"벽파도라는 섬이 이 근처에 있습니까?\" 그 사람이 \"자세히 모릅니다.\" 하고 대답하였다. 하는 수 없이 옥문관을 찾아가 한 사람을 만나 물으니 그 사람이 벽파도를 가리켜 주었다. 그 섬을 찾아가며 좌우를 살펴보니 물길은 멀지 않으나 건너갈 방도가 없어 막막하였다.","sp":[]},{"c":2,"sub":"졔 이 회: 여공이 계월을 거두어 양육ᄒᆞ고 양부인이 만리고도에 홍시랑을 만나다","t":"물가에 앉아 보니 바위 위에 한 사람이 앉아 고기를 낚고 있었다. 양윤이 나가 절하고 물었다. \"저 섬은 무슨 섬이라 합니까?\" 늙은 어부가 말했다. \"그 섬은 벽파도라 한다.\" 또 물었다. \"그곳에 사람 사는 마을이 있습니까?\" 어부가 말했다. \"예로부터 사람의 자취가 없었는데, 이삼 년 전에 형주 땅에서 귀양 온 사람이 있어 초목으로 울타리를 삼고 짐승을 벗 삼아 지내는데 그 모습이 참혹하더라.\" 양윤이 돌아와 부인에게 이 사정을 아뢰니 부인이 말했다. \"귀양 왔다는 사람이 형주 사람이라","sp":[[37,39,"P","양윤"],[226,228,"P","양윤"],[234,236,"P","양부인"],[249,251,"P","양부인"]]},{"c":2,"sub":"졔 이 회: 여공이 계월을 거두어 양육ᄒᆞ고 양부인이 만리고도에 홍시랑을 만나다","t":"하니 시랑의 생사를 알 수 있겠구나.\" 하고 그 섬을 바라보며 앉아 있는데, 홀연 작은 배 한 척이 노를 저어 왔다. 양윤이 배를 향해 말했다. \"우리는 고소대 일봉암에 사는 여승인데, 벽파도에 건너가고자 하나 배가 없어 이곳에 앉아 있다가 다행히 뱃사람을 만났습니다. 바라건대 잠깐의 수고를 마다하지 마십시오.\" 하며 애걸하니 뱃사람이 배를 대고 오르라 하였다. 양윤과 춘낭이 부인을 모시고 배에 오르니 순식간에 배를 대고 내리라 하였다.","sp":[[3,5,"P","홍무"],[66,68,"P","양윤"],[204,206,"P","양윤"],[208,210,"P","춘낭"],[212,214,"P","양부인"]]},{"c":2,"sub":"졔 이 회: 여공이 계월을 거두어 양육ᄒᆞ고 양부인이 만리고도에 홍시랑을 만나다","t":"부인이 배에서 내려 두 번 절하여 사례하고 벽파도로 가며 살펴보니, 나무가 하늘을 찌르고 사람의 자취가 없었다. 바닷가를 다니며 두루 살피는데, 문득 한 곳에 옷이 해어지고 온몸에 털이 돋아 보기에 참혹한 사람이 강변을 오가며 고기를 주워 먹다가 한 골짜기로 들어갔다. 양윤이 그 사람을 따라가 보니 한 초막으로 들어갔다. 양윤이 소리를 크게 질러 말했다. \"상공께서는 조금도 놀라지 마십시오.\" 시랑이 그 말을 듣고 초막 밖으로 나서며 말했다. \"이 섬 안에 나를 찾아올 사람이 없는데","sp":[[0,2,"P","양부인"],[151,153,"P","양윤"],[181,183,"P","양윤"],[222,224,"P","홍무"]]},{"c":2,"sub":"졔 이 회: 여공이 계월을 거두어 양육ᄒᆞ고 양부인이 만리고도에 홍시랑을 만나다","t":"스님은 무슨 말을 물으려고 부르시오?\" 양윤이 말했다. \"소승은 고소대 일봉암에 있는데, 이곳에 온 것은 간절히 여쭐 말씀이 있어 상공을 찾아온 것입니다.\" 상공이 말했다. \"무슨 말씀을 물으려 하오?\" 양윤이 엎드려 대답하였다. \"소승의 고향은 형주 구계촌인데, 장사랑의 난을 만나 피란하였습니다. 소문을 들으니 상공께서 형주 땅에서 이 섬으로 귀양 오셨다 하기에 고향 소식을 알아보려고 왔습니다.\" 시랑이 이 말을 듣고 눈물을 흘리며 물었다. \"형주 구계촌에 살았다니 누구 집에 있었소?\" 양윤이 대답하였다. \"소승은 홍시랑 댁에 있던 양윤으로,","sp":[[22,24,"P","양윤"],[114,116,"P","양윤"],[148,151,"P","장사랑"],[225,227,"P","홍무"],[276,278,"P","양윤"],[292,295,"P","홍무"],[302,304,"P","양윤"]]},{"c":2,"sub":"졔 이 회: 여공이 계월을 거두어 양육ᄒᆞ고 양부인이 만리고도에 홍시랑을 만나다","t":"부인을 모시고 갖은 고초를 겪다가 이곳에 왔습니다.\" 시랑이 이 말을 듣고 취한 듯 미친 듯하여 급히 양윤의 손을 잡고 크게 통곡하며 말했다. \"양윤아, 너는 나를 모르느냐? 내가 홍시랑이다.\" 양윤이 홍시랑이라는 말을 듣고 한참 기절하였다가 겨우 정신을 진정하고 울며 말했다. \"부인께서 지금 강변에 앉아 계십니다.\" 시랑이 그 말을 듣고 한편 기쁘고 한편 슬퍼하며 나아갔다. 이때 부인이 울음소리를 듣고 눈을 들어 보니, 털이 무성하여 곰 같은 사람이 가슴을 두드리며 부인을 향해 오고 있었다.","sp":[[0,2,"P","양부인"],[30,32,"P","홍무"],[57,59,"P","양윤"],[81,83,"P","양윤"],[101,104,"P","홍무"],[109,111,"P","양윤"],[113,116,"P","홍무"],[157,159,"P","양부인"],[179,181,"P","홍무"],[215,217,"P","양부인"],[264,266,"P","양부인"]]},{"c":2,"sub":"졔 이 회: 여공이 계월을 거두어 양육ᄒᆞ고 양부인이 만리고도에 홍시랑을 만나다","t":"부인이 보고 미친 사람인가 하여 도망치려 하자 시랑이 말했다. \"부인은 놀라지 마십시오. 나는 홍시랑입니다.\" 부인은 어찌 된 일인지 모르고 겁에 질려 고깔을 벗어 들고 달아났다. 양윤이 외쳤다. \"부인, 달아나지 마십시오. 홍시랑께서 오십니다.\" 부인이 양윤의 소리를 듣고 황망히 앉으니, 시랑이 울며 따라와 말했다. \"부인은 어찌 그리 의심하십니까? 나는 계월의 아비 홍시랑입니다.\" 부인이 듣고 정신을 차리지 못하며 서로 붙들고 통곡하다가 기절하였다.","sp":[[0,2,"P","양부인"],[26,28,"P","홍무"],[36,38,"P","양부인"],[53,56,"P","홍무"],[62,64,"P","양부인"],[101,103,"P","양윤"],[111,113,"P","양부인"],[126,129,"P","홍무"],[139,141,"P","양부인"],[143,145,"P","양윤"],[163,165,"P","홍무"],[180,182,"P","양부인"],[201,203,"P","홍계월"],[208,211,"P","홍무"],[217,219,"P","양부인"]]},{"c":2,"sub":"졔 이 회: 여공이 계월을 거두어 양육ᄒᆞ고 양부인이 만리고도에 홍시랑을 만나다","t":"양윤도 통곡하며 위로하니 그 광경은 차마 볼 수 없었다. 춘낭은 외로운 사람이라 혼자 돌아앉아 슬피 우니 그 모습 또한 참혹하였다. 시랑이 부인을 붙들고 초막으로 돌아와 정신을 가다듬고 물었다. \"저 부인은 어떤 분이십니까?\" 부인이 탄식하며, 피란하여 가다가 수적 맹길을 만나 계월은 물에 던져지고 자기는 도적에게 잡혀갔는데 저 춘낭의 도움을 입어 그날 밤 도망한 일, 고소대에 가서 중이 된 일, 부처님이 꿈에 나타나 벽파도로 가라 한 일 등 앞뒤 사정을 다 이야기하고 슬픔을 참지 못하였다. 시랑은 계월이 죽었다는 말을 듣고 기절했다가 겨우 정신을 차려 말했다. \"나도 그때 정도사 집에서 떠나오다가 도적 장사랑에게 잡혀 진중에 있었는데, 천자께서 도적을 잡으실 때 나도 도적과 함께","sp":[[0,2,"P","양윤"],[32,34,"P","춘낭"],[74,76,"P","홍무"],[78,80,"P","양부인"],[112,114,"P","양부인"],[127,129,"P","양부인"],[146,151,"P","맹길"],[156,158,"P","홍계월"],[185,187,"P","춘낭"],[278,280,"P","홍무"],[282,284,"P","홍계월"],[325,328,"P","정도사"],[342,345,"P","장사랑"],[361,363,"P","천자"]]},{"c":2,"sub":"졔 이 회: 여공이 계월을 거두어 양육ᄒᆞ고 양부인이 만리고도에 홍시랑을 만나다","t":"잡혀서 도적과 한마음으로 힘을 합했다 하시어 이곳으로 귀양 왔소.\" 하며 그간의 일을 다 이야기하였다. 그러고는 춘낭 앞에 나아가 절하고 사례하였다. \"부인께서 구해 주신 은혜는 죽어도 갚을 길이 없습니다.\" 하며 거듭 감사하였다. 이때 부인이 노승이 준 은자를 뱃사람에게 팔아 양식을 이으며 계월을 생각하고 울지 않는 사람이 없었다. 한편 이때 계월은 보국과 함께 글을 배우는데, 한 자를 가르치면 열 자를 깨치고 행동이 비상하였다. 도사가 칭찬해 마지않으며 말했다. \"하늘이 너를 내신 것은 밝은 임금을 위함이니,","sp":[[63,65,"P","춘낭"],[85,87,"P","양부인"],[133,135,"P","양부인"],[137,139,"P","고소대 노승"],[164,166,"P","홍계월"],[194,196,"P","홍계월"],[198,200,"P","보국"],[244,246,"P","곽도사"]]},{"c":2,"sub":"졔 이 회: 여공이 계월을 거두어 양육ᄒᆞ고 양부인이 만리고도에 홍시랑을 만나다","t":"어찌 천하를 근심하랴.\" 하고 군사 부리는 법과 온갖 술법을 가르치니, 검술과 지략이 당대에 대적할 사람이 없었다. 세월이 물 흐르듯 지나 두 아이의 나이가 열세 살이 되었다. 도사가 두 아이를 불러 말했다. \"군사 부리는 일은 다 배웠으나 바람과 구름을 부리는 변화의 술법을 배우라.\" 하며 책 한 권을 주었다. 받아 보니 이는 천고에 없던 술법이었다. 평국과 보국이 밤낮을 쉬지 않고 배웠는데, 평국은 석 달 만에 모르는 것이 없게 되었고 보국은 일 년을 배워도 통달하지 못하였다. 도사가 말했다. \"평국의 재주는 이 시대의 으뜸이로다.\"","sp":[[99,101,"P","곽도사"],[199,201,"P","홍계월"],[203,205,"P","보국"],[223,225,"P","홍계월"],[248,250,"P","보국"],[272,274,"P","곽도사"],[282,284,"P","홍계월"]]},{"c":2,"sub":"졔 이 회: 여공이 계월을 거두어 양육ᄒᆞ고 양부인이 만리고도에 홍시랑을 만나다","t":"이때 나라가 태평하여 백성들이 격양가(擊壤歌)를 부르며 지냈다. 천자께서 어진 신하를 얻고자 하시어 천하에 공문을 내려 태평 만과(萬科)를 보이시니, 도사가 이 말을 듣고 곧 평국과 보국을 불러 말했다. \"지금 황상께서 과거를 보이신다 하니 부디 이름을 빛내라.\" 하고 여공을 청하여 말했다. \"이번 과거에 두 아이가 갈 행장을 차려 주십시오.\" 여공이 곧 과거 행장을 차려 주는데 천리마 두 필과 하인을 정해 주었다. 두 아이가 작별을 고하고 길을 떠나 황성에 이르니, 천하의 선비가 구름같이 모여 있었다.","sp":[[36,38,"P","천자"],[84,86,"P","곽도사"],[98,100,"P","홍계월"],[102,104,"P","보국"],[118,120,"P","천자"],[151,153,"P","여공"],[194,196,"P","여공"]]},{"c":2,"sub":"졔 이 회: 여공이 계월을 거두어 양육ᄒᆞ고 양부인이 만리고도에 홍시랑을 만나다","t":"과거 날이 되자 평국과 보국이 대명전에 들어가니 천자께서 자리에 앉아 계셨다. 글제를 보고 단숨에 써 내려가니 용과 뱀이 날아오르는 듯한 필치였다. 평국은 첫 번째로 바치고 보국은 두 번째로 바친 뒤 주인집에 돌아와 쉬었다. 이때 천자께서 글을 보시고 \"그 재주를 가히 알겠구나.\" 하시며 봉해 둔 이름을 뜯어 보시니 평국과 보국이 모두 장원에 뽑혔다. 평국을 장원으로, 보국을 부장원으로 삼고 황경문에 방을 붙여 이름을 불렀다. 노복들이 문 밖에서 방을 기다리다가 급히 돌아와 아뢰었다. \"도련님 두 분께서 지금 급제하여 급히 부르시니 어서 가십시다.\" 평국과 보국이 크게 기뻐하여 급히 황경문으로 들어가 옥계(玉階) 아래 엎드렸다. 천자께서 두 새 급제자를 불러 보시고 두 사람의 손을 잡으며 칭찬하셨다. \"너희를 보니 충심이 있고 미간에 천지의 조화를 품었도다.\"","sp":[[9,11,"P","홍계월"],[13,15,"P","보국"],[27,29,"P","천자"],[83,85,"P","홍계월"],[97,99,"P","보국"],[129,131,"P","천자"],[178,180,"P","홍계월"],[182,184,"P","보국"],[198,200,"P","홍계월"],[208,210,"P","보국"],[311,313,"P","홍계월"],[315,317,"P","보국"],[356,358,"P","천자"]]},{"c":2,"sub":"졔 이 회: 여공이 계월을 거두어 양육ᄒᆞ고 양부인이 만리고도에 홍시랑을 만나다","t":"말소리가 옥을 깨는 듯하니 천자께서 말씀하셨다. \"천하의 영웅이로다. 짐이 이제는 천하를 근심하지 않겠도다. 마음과 힘을 다해 짐을 도우라.\" 하시고 평국을 한림학사로, 보국을 부제후로 삼으시고 어사화를 내리시며 천리마를 한 필씩 하사하셨다. 한림과 부제후가 은혜에 감사하여 엎드려 절하고 나오니, 하인들이 문 밖에 기다리다가 호위하여 나왔다. 붉은 관복에 옥대를 두르고 푸르고 붉은 일산 한 쌍을 받쳐 햇빛을 가리며, 앞에서는 여전(女前) 풍류에 옥피리 한 쌍을 불고 뒤에서는 태학원 풍류와 비단옷 입은 화동이 꽃밭을 이루어 장안 큰길로 두렷이 나오니, 보는 사람들이 칭찬하여 \"하늘의 신선이 내려왔다.\" 하였다.","sp":[[15,17,"P","천자"],[84,86,"P","홍계월"],[95,97,"P","보국"],[99,102,"P","보국"],[140,143,"P","보국"]]},{"c":2,"sub":"졔 이 회: 여공이 계월을 거두어 양육ᄒᆞ고 양부인이 만리고도에 홍시랑을 만나다","t":"사흘 동안 유가(遊街)한 뒤 한림원에 들어가 명현동 선생과 무릉포 여공 댁에 소식을 전하였다. 한림이 말했다. \"그대는 양친이 계시니 영화를 보여 드리겠지만, 나는 부모 없는 사람이라 영화를 누구에게 보이겠는가.\" 하며 슬피 우니 보는 사람 누가 눈물을 흘리지 않았겠는가. 이때 한림과 부제후가 탑전(榻前)에 들어가 부모에게 영화를 보이러 가겠다고 아뢰니, 천자께서 말씀하셨다. \"경들은 짐의 손발이라 잠시라도 조정을 떠나는 것은 옳지 않으나 말리지는 못하겠으니, 곧 돌아와 짐을 도우라.\" 한림과 부제후가 섬돌 아래에서 엎드려 작별하고 집으로 돌아가니, 지나는 고을마다 맞이하고 배웅하였다.","sp":[[25,31,"P","곽도사"],[37,39,"P","여공"],[160,163,"P","보국"],[200,202,"P","천자"],[279,282,"P","보국"]]},{"c":3,"sub":"졔 ᄉᆞᆷ 회: 두 원슈 군ᄉᆞ를 거ᄂᆞ려 츌젼ᄒᆞ고 오랑ᄏᆡ 크게 패ᄒᆞ야 벽ᄑᆞ도로 다라ᄂᆞ다","t":"한편 한림과 부제후가 여러 날 만에 무릉포에 도착하여 여공 내외에게 뵈니, 그 즐거움을 헤아릴 수 없었고 보는 사람마다 누가 칭찬하지 않았겠는가. 보국은 기쁜 빛이 얼굴에 가득하였으나 평국은 기쁜 빛이 없고 눈물 자국이 마르지 않았다. 여공이 위로하였다. \"모두 하늘의 운수이니 지난 일은 너무 슬퍼하지 마라. 하늘이 도우시면 훗날 다시 부모를 만나 영화를 보여 드릴 것이니 어찌 서러워하겠느냐.\" 평국이 엎드려 울며 말했다. \"바다 위의 외로운 넋을 거두어 이처럼 귀하게 되었으니, 길러 주신 은혜는 뼈에 새겨 잊을 수 없습니다.","sp":[[7,10,"P","보국"],[30,32,"P","여공"],[82,84,"P","보국"],[103,105,"P","홍계월"],[132,134,"P","여공"],[223,225,"P","홍계월"]]},{"c":3,"sub":"졔 ᄉᆞᆷ 회: 두 원슈 군ᄉᆞ를 거ᄂᆞ려 츌젼ᄒᆞ고 오랑ᄏᆡ 크게 패ᄒᆞ야 벽ᄑᆞ도로 다라ᄂᆞ다","t":"어떻게 갚아야 할지 모르겠습니다.\" 여공과 모든 사람이 칭찬해 마지않았다. 이튿날 명현동에 가서 도사에게 뵈니, 도사가 뜻밖에 크게 기뻐하며 평국과 보국을 앞에 앉히고 먼 길에 영화롭게 돌아온 것을 칭찬하고, 고금 역대의 일과 나라 섬기는 도리를 들어 경계하였다. 하루는 도사가 천문을 살펴보니 북방의 도적이 강성하여 여러 별이 자미성(紫微星)을 에워싸고 있었다. 크게 놀라 곧 평국과 보국을 불러 천문의 형세를 이르고, 급히 황성으로 올라가 천자의 위태로움을 구하라 하였다. 그리고 봉한 편지 한 장을 평국에게 주며 말했다. \"싸움터에 나가 만일 죽을 지경을 당하거든 이 편지를 뜯어 보라.\" 하며 어서 가기를 재촉하였다. 평국이 울며 말했다. \"선생께서 아끼고 가르쳐 주신 은혜는 뼈에 새겨 잊을 수 없거니와, 잃은 부모를 어느 곳에 가서 찾아야 합니까? 바라건대 선생께서는 분명히 가르쳐 주십시오.\"","sp":[[20,22,"P","여공"],[54,56,"P","곽도사"],[63,65,"P","곽도사"],[79,81,"P","홍계월"],[83,85,"P","보국"],[152,154,"P","곽도사"],[212,214,"P","홍계월"],[216,218,"P","보국"],[248,250,"P","천자"],[282,284,"P","홍계월"],[350,352,"P","홍계월"],[363,365,"P","곽도사"],[430,432,"P","곽도사"]]},{"c":3,"sub":"졔 ᄉᆞᆷ 회: 두 원슈 군ᄉᆞ를 거ᄂᆞ려 츌젼ᄒᆞ고 오랑ᄏᆡ 크게 패ᄒᆞ야 벽ᄑᆞ도로 다라ᄂᆞ다","t":"도사가 말했다. \"하늘의 뜻을 누설할 수 없으니 다시는 묻지 마라.\" 평국이 다시 묻지 못하고 두 사람이 도사에게 작별한 뒤 말 한 필씩 타고 밤낮으로 달려 황성으로 올라갔다. 이때 옥문관을 지키는 김성담이 장계를 올렸다. 천자께서 뜯어 보시니 이렇게 쓰여 있었다. \"서관과 서달이 비사장군 악대와 비룡장군 철통골 두 장수를 선봉으로 삼고 군사 십만과 장수 천여 명을 거느려 북주 칠십여 성의 항복을 받고, 자사 양기덕을 베고, 황성을 침범하려 하여 난리가 매우 심합니다. 소장의 힘으로는 당해 낼 수 없으니 바라건대 황상께서는 어진 명장을 보내시어 도적을 막으십시오.\"","sp":[[0,2,"P","곽도사"],[39,41,"P","홍계월"],[59,61,"P","곽도사"],[111,114,"P","김성담"],[125,127,"P","천자"],[150,152,"P","서관"],[154,156,"P","서달"],[158,162,"P","악대"],[163,165,"P","악대"],[167,171,"P","철통골"],[172,175,"P","철통골"],[290,292,"P","천자"]]},{"c":3,"sub":"졔 ᄉᆞᆷ 회: 두 원슈 군ᄉᆞ를 거ᄂᆞ려 츌젼ᄒᆞ고 오랑ᄏᆡ 크게 패ᄒᆞ야 벽ᄑᆞ도로 다라ᄂᆞ다","t":"천자께서 보시고 크게 놀라 여러 신하를 돌아보며 말씀하셨다. \"경들은 서둘러 대원수를 골라 도적 막을 묘책을 의논하라.\" 하시며 눈물을 흘리셨다. 여러 신하가 아뢰었다. \"평국이 비록 나이는 어리나 천지의 조화를 가슴에 품은 듯하니, 이 사람을 도원수로 정하여 도적을 막을까 합니다.\" 천자께서 크게 기뻐하시어 곧 사신을 보내려 하실 즈음에 황성문의 수문장이 급히 아뢰었다. \"한림과 부제후가 문 밖에 와서 기다립니다.\" 천자께서 들으시고 급히 들라 하교하시니 평국과 보국이 빨리 옥계 아래 엎드렸다. 천자께서 불러 보시고 말씀하셨다. \"짐이 밝지 못하여 도적이 강성해져 북주 칠십여 성의 항복을 받고 황성을 침범하려 하니 매우 놀라운 일이다.","sp":[[0,2,"P","천자"],[44,46,"P","홍계월"],[96,98,"P","홍계월"],[138,140,"P","홍계월"],[160,162,"P","천자"],[215,218,"P","보국"],[236,238,"P","천자"],[258,260,"P","홍계월"],[262,264,"P","보국"],[281,283,"P","천자"]]},{"c":3,"sub":"졔 ᄉᆞᆷ 회: 두 원슈 군ᄉᆞ를 거ᄂᆞ려 츌젼ᄒᆞ고 오랑ᄏᆡ 크게 패ᄒᆞ야 벽ᄑᆞ도로 다라ᄂᆞ다","t":"신하들과 의논하였더니 경들을 천거하기에 사신을 보내려 하였는데, 밝은 하늘이 도우시어 경들이 뜻밖에 이르렀으니 사직을 보전할 수 있겠다. 마음과 힘을 다해 짐의 근심을 덜고 도탄에 빠진 백성을 건지라.\" 평국과 보국이 엎드려 아뢰었다. \"소신들이 재주는 얕으나 한 번 북을 쳐 도적을 깨뜨려 폐하의 성은을 만분의 일이라도 갚고자 하니, 바라건대 황상께서는 근심하지 마십시오.\" 천자께서 크게 기뻐하시어 평국을 대원수로 봉하시고 보국을 대사마 중군장으로 봉하시며, 장수 천여 명과 군사 팔십만을 주시고 물으셨다. \"여러 장수와 군졸을 어찌 다 지휘하려 하느냐?\" 도원수 평국이 아뢰었다. \"마음속에 다 정해 두었으니 행군할 때 소임을 정하겠습니다.\" 하고 곧 장수 천여 명과 군사 팔십만을 모아 계축 갑자일에","sp":[[114,116,"P","홍계월"],[118,120,"P","보국"],[163,165,"P","천자"],[193,195,"P","천자"],[211,213,"P","천자"],[225,227,"P","홍계월"],[230,232,"P","홍계월"],[239,241,"P","보국"],[247,250,"P","보국"],[315,317,"P","홍계월"],[318,320,"P","홍계월"]]},{"c":3,"sub":"졔 ᄉᆞᆷ 회: 두 원슈 군ᄉᆞ를 거ᄂᆞ려 츌젼ᄒᆞ고 오랑ᄏᆡ 크게 패ᄒᆞ야 벽ᄑᆞ도로 다라ᄂᆞ다","t":"행군하였다. 원수는 순금 투구에 백운전포(白雲戰袍)를 입고 허리에 보궁과 비룡살을 차고, 왼손에 산호 채찍과 오른손에 수기(帥旗)를 들고 군중에 호령하여 여러 장수와 군졸을 지휘하니 위풍이 엄숙하였다. 천자께서 크게 기뻐하시며 \"원수의 군사 부리는 재주가 이러하니 어찌 도적을 근심하겠는가.\" 하시고, 대장기에 친히 '한림학사 겸 대원수 홍평국'이라 쓰시고 칭찬해 마지않으셨다. 원수가 행군하니 깃발과 창검이 천지를 진동하고 그 위엄이 백 리 밖까지 뻗쳤다.","sp":[[7,9,"P","홍계월"],[113,115,"P","천자"],[128,130,"P","홍계월"],[186,188,"P","홍계월"],[189,192,"P","홍계월"],[212,214,"P","홍계월"]]},{"c":3,"sub":"졔 ᄉᆞᆷ 회: 두 원슈 군ᄉᆞ를 거ᄂᆞ려 츌젼ᄒᆞ고 오랑ᄏᆡ 크게 패ᄒᆞ야 벽ᄑᆞ도로 다라ᄂᆞ다","t":"장졸을 재촉하여 옥문관으로 향하는데, 천자께서 원수의 행군을 구경하고자 신하들을 거느리고 거둥하시어 진문 밖에 이르셨다. 수문장이 진문을 굳게 닫고 있으므로 앞에서 인도하는 관원이 외쳤다. \"천자께서 이곳에 납시었으니 어서 문을 열라.\" 수문장이 말했다. \"군중에서는 장군의 명령을 듣고 천자의 조서는 듣지 않는다 하였으니, 장군의 명령 없이 어찌 문을 열겠습니까?\" 천자께서 그제야 조서를 내리시니, 원수가 천자께서 오신 줄 알고 진중에 명을 내려 문을 크게 열고 천자를 맞았다. 수문장이 말했다. \"진중에서는 말을 달리지 못합니다.\" 천자께서 말 한 필로 장대(將臺)에 오르시니, 원수가 급히 장대에서 내려 읍하고 \"갑옷 입은 장수는 절을 하지 못합니다.\" 하고 엎드렸다. 천자께서 칭찬하시고 좌우를 돌아보시며","sp":[[21,23,"P","천자"],[26,28,"P","홍계월"],[107,109,"P","천자"],[161,163,"P","천자"],[206,208,"P","천자"],[225,227,"P","홍계월"],[229,231,"P","천자"],[261,263,"P","천자"],[301,303,"P","천자"],[327,329,"P","홍계월"],[379,381,"P","천자"]]},{"c":3,"sub":"졔 ᄉᆞᆷ 회: 두 원슈 군ᄉᆞ를 거ᄂᆞ려 츌젼ᄒᆞ고 오랑ᄏᆡ 크게 패ᄒᆞ야 벽ᄑᆞ도로 다라ᄂᆞ다","t":"말씀하셨다. \"원수의 진법을 보니 옛날 주아부(周亞夫)를 본받았으니 무슨 근심이 있으랴.\" 하시고 백모(白旄)와 황월(黃鉞), 인검(印劍)을 주시니 군중이 더욱 엄숙해졌다. 천자께서 먼 길에 공을 이루고 돌아오라 당부하시고 환궁하셨다. 이때 원수가 행군한 지 석 달 만에 옥문관에 이르니, 관수(關守) 석탐이 황성의 대군이 온 줄 알고 크게 기뻐하여 성문을 열고 원수를 맞아 장대에 모셨다. 원수가 여러 장수의 군례를 받는데 군중이 엄숙하였다. 원수가 관수를 불러 도적의 형세를 물으니 석탐이 대답하였다. \"도적의 형세가 철통같습니다.\" 원수가 이튿날 행군하여 벽원에 이르러 진을 치고 적진을 바라보니, 넓은 들판에 살기가 하늘을 찌르고 깃발과 창이 햇빛에 번득였다.","sp":[[8,10,"P","홍계월"],[97,99,"P","천자"],[135,137,"P","홍계월"],[169,171,"P","김성담"],[203,205,"P","홍계월"],[219,221,"P","홍계월"],[249,251,"P","홍계월"],[272,274,"P","김성담"],[301,303,"P","홍계월"]]},{"c":3,"sub":"졔 ᄉᆞᆷ 회: 두 원슈 군ᄉᆞ를 거ᄂᆞ려 츌젼ᄒᆞ고 오랑ᄏᆡ 크게 패ᄒᆞ야 벽ᄑᆞ도로 다라ᄂᆞ다","t":"원수가 적진을 피해 장대에 높이 앉아 군중에 호령하였다. \"장수의 명령을 어기는 자는 군법으로 다스리겠다.\" 하니 온 진의 장졸이 겁내지 않는 이가 없었다. 이튿날 해 뜰 무렵 원수가 순금 투구에 백운갑을 입고 석 자 장검을 들고 준총마 위에 두렷이 앉아 진문을 크게 열고 나서며 크게 외쳤다. \"적장은 들어라. 천자의 성덕이 어지시어 천하 백성이 격양가를 부르며 만세를 부르는데, 너희 놈들이 반역의 마음을 품어 황성을 침범하려 하니, 천자께서 백성을 건지려고 나에게 명하여 보내셨다. 너희는 목을 늘여 내 칼을 받아라. 두렵거든 빨리 나와 항복하라.\" 그 소리가 태산이 움직이는 듯하였다. 비사장군 악대가 이 말을 듣고 크게 노하여 말 한 필에 창 하나로 진문 밖에 나서며 외쳤다. \"너는 입에서 젖내 나는 아이라, 어린 강아지가","sp":[[0,2,"P","홍계월"],[99,101,"P","홍계월"],[175,177,"P","천자"],[245,247,"P","천자"],[332,336,"P","악대"],[337,339,"P","악대"]]},{"c":3,"sub":"졔 ᄉᆞᆷ 회: 두 원슈 군ᄉᆞ를 거ᄂᆞ려 츌젼ᄒᆞ고 오랑ᄏᆡ 크게 패ᄒᆞ야 벽ᄑᆞ도로 다라ᄂᆞ다","t":"사나운 범을 모르는 격이다. 네가 어찌 나를 당하겠느냐. 내 칼을 받아라.\" 하고 달려들었다. 원수가 웃고 장검을 높이 들고 말을 채찍질하여 달려들어 싸웠으나 십여 합에 승부를 가리지 못하였다. 서달이 장대에서 바라보니 악대의 칼빛은 점점 약해지고 평국의 칼빛은 구름 속의 번개같이 씩씩하였다. 급히 징을 쳐 군사를 거두어 가니, 원수는 분함을 머금고 본진으로 돌아왔다. 여러 장수와 군졸이 모두 원수를 칭찬하였다. \"원수의 변화하는 술법과 이리저리 치고 드는 솜씨는 봄 삼월 버들가지가 바람 앞에 노니는 듯, 가을 구월 초승달이 검은 구름을 헤치는 듯하였습니다.\"","sp":[[53,55,"P","홍계월"],[109,111,"P","서달"],[123,125,"P","악대"],[139,141,"P","홍계월"],[185,187,"P","홍계월"],[222,224,"P","홍계월"],[234,236,"P","홍계월"]]},{"c":3,"sub":"졔 ᄉᆞᆷ 회: 두 원슈 군ᄉᆞ를 거ᄂᆞ려 츌젼ᄒᆞ고 오랑ᄏᆡ 크게 패ᄒᆞ야 벽ᄑᆞ도로 다라ᄂᆞ다","t":"이때 중군장 보국이 아뢰었다. \"내일은 소장이 나가 악대의 머리를 베어 휘하에 바치겠습니다.\" 원수가 말리며 말했다. \"악대는 범상치 않은 장수이니 중군은 물러 있으라.\" 그러나 끝내 듣지 않고 간청하므로 원수가 말했다. \"중군이 공을 세우고자 하나 만일 뜻대로 되지 않으면 군법으로 다스리겠다.\" 중군이 \"그리하십시오.\" 하였다. 원수가 말했다. \"군중에는 사사로운 정이 없으니 군율에 따라 다짐을 써서 올려라.\" 이튿날 보국이 갑옷과 투구를 갖추고 용총마에 올라 진 앞으로 나아갔다. 원수는 친히 북채를 들고 만일 위태로우면 징을 쳐 물리겠다 하였다. 보국이 크게 외쳤다. \"어제 우리 원수께서 너를 베지 않은 것은 불쌍히 여겨 그냥 돌아오신 것이다. 오늘은 나로 하여금 너를 베라 하시니 빨리 나와 내 칼을 받아라.\" 적장이","sp":[[3,6,"P","보국"],[7,9,"P","보국"],[29,31,"P","악대"],[53,55,"P","홍계월"],[67,69,"P","악대"],[83,85,"P","보국"],[115,117,"P","홍계월"],[125,127,"P","보국"],[167,169,"P","보국"],[186,188,"P","홍계월"],[237,239,"P","보국"],[273,275,"P","홍계월"],[311,313,"P","보국"],[330,332,"P","홍계월"]]},{"c":3,"sub":"졔 ᄉᆞᆷ 회: 두 원슈 군ᄉᆞ를 거ᄂᆞ려 츌젼ᄒᆞ고 오랑ᄏᆡ 크게 패ᄒᆞ야 벽ᄑᆞ도로 다라ᄂᆞ다","t":"크게 노하여 정서장군 무길에게 맞서 싸우라 명하니, 무길이 명을 듣고 창을 잡고 말을 몰아 나가 싸웠다. 몇 합이 못 되어 보국의 칼이 번쩍이며 무길의 머리가 말 아래로 떨어졌다. 보국이 칼끝에 머리를 꿰어 들고 크게 외쳤다. \"적장은 애매한 장수만 죽이지 말고 빨리 나와 항복하라.\" 총서장군 충관이 무길의 죽음을 보고 급히 내달아 싸웠는데, 삼십여 합에 이르러 충관이 거짓으로 패한 척 본진으로 달아났다. 보국이 기세를 타고 쫓아가자 적진이 한꺼번에 함성을 지르며 에워싸니, 보국이 천여 겹 속에 갇히고 말았다.","sp":[[7,11,"P","무길"],[12,14,"P","무길"],[29,31,"P","무길"],[69,71,"P","보국"],[81,83,"P","무길"],[101,103,"P","보국"],[160,164,"P","충관"],[165,167,"P","충관"],[169,171,"P","무길"],[204,206,"P","충관"],[229,231,"P","보국"],[268,270,"P","보국"]]},{"c":3,"sub":"졔 ᄉᆞᆷ 회: 두 원슈 군ᄉᆞ를 거ᄂᆞ려 츌젼ᄒᆞ고 오랑ᄏᆡ 크게 패ᄒᆞ야 벽ᄑᆞ도로 다라ᄂᆞ다","t":"어쩔 수 없이 죽게 되자 수기를 높이 들고 원수를 향해 탄식하였다. 이때 원수가 중군이 급한 것을 보고 북채를 던지고 준총마를 급히 몰아 크게 외쳤다. \"적장은 나의 중군을 해치지 마라.\" 하고 수많은 군사 가운데로 이리저리 치고 들며 함성을 지르고 헤쳐 들어가니, 적진의 장졸이 물결 갈라지듯 하였다. 원수가 보국을 옆에 끼고 적장 오십여 명을 단칼에 베며 적군 속을 거침없이 누비니, 서달이 악대를 돌아보며 말했다. \"평국이 하나인 줄 알았더니 오늘 보니 수십 명도 넘는구나.","sp":[[24,26,"P","홍계월"],[41,43,"P","홍계월"],[45,47,"P","보국"],[93,95,"P","보국"],[170,172,"P","홍계월"],[174,176,"P","보국"],[217,219,"P","서달"],[221,223,"P","악대"],[236,238,"P","홍계월"]]},{"c":3,"sub":"졔 ᄉᆞᆷ 회: 두 원슈 군ᄉᆞ를 거ᄂᆞ려 츌젼ᄒᆞ고 오랑ᄏᆡ 크게 패ᄒᆞ야 벽ᄑᆞ도로 다라ᄂᆞ다","t":"어찌 당하겠는가.\" 악대가 말했다. \"대왕은 근심하지 마십시오.\" 서달이 말했다. \"누가 능히 당하겠느냐. 죽는 군사의 수를 이루 헤아릴 수 없겠구나.\" 이때 원수가 본진에 돌아와 장대에 높이 앉아 보국을 잡아들이라 하니 호령이 가을 서리 같았다. 군사들이 넋을 잃고 중군을 잡아 장대 아래 꿇리니 원수가 크게 꾸짖었다. \"중군은 들어라. 내가 말렸으나 자원하여 다짐을 두고 출전하더니, 적장의 꾀에 빠져 대국의 수치를 보였다. 내가 구하지 않으려다가, 더러운 도적의 손에 죽이지 않고 내 군법으로 죽여 여러 장수를 경계하려고 구한 것이니 죽는 것을 슬퍼하지 마라.\" 하고 무사에게 호령하여 원문 밖에 내어 베라 하였다. 여러 장수가 한꺼번에 엎드려 아뢰었다. \"중군의 죄는 군법으로 다스림이 마땅하나, 용력을 다하여 적장 삼십여 명을 베고 의기양양하여 적진을 가볍게 여기다가 패하였으니,","sp":[[11,13,"P","악대"],[21,23,"P","서달"],[37,39,"P","서달"],[89,91,"P","홍계월"],[111,113,"P","보국"],[150,152,"P","보국"],[167,169,"P","홍계월"],[181,183,"P","보국"],[371,373,"P","보국"]]},{"c":3,"sub":"졔 ᄉᆞᆷ 회: 두 원슈 군ᄉᆞ를 거ᄂᆞ려 츌젼ᄒᆞ고 오랑ᄏᆡ 크게 패ᄒᆞ야 벽ᄑᆞ도로 다라ᄂᆞ다","t":"한 번 이기고 지는 것은 병가에 늘 있는 일입니다. 바라건대 대원수께서는 용서해 주십시오.\" 하며 한꺼번에 머리를 조아려 사죄하였다. 원수가 생각하다가 속으로 웃으며 말했다. \"그대를 베어 여러 장수를 경계하려 하였으나 여러 사람의 낯을 보아 용서하거니와 이후로는 그러지 마라.\" 하며 웃으니 보국이 백 번 절하여 사례하고 물러갔다. 이튿날 해 뜰 무렵 원수가 갑옷과 투구를 갖추고 말에 올라 칼을 들고 나서며 크게 외쳤다. \"어제는 우리 부원수 중군이 패하였으나 오늘은 내가 친히 싸워 너희를 쓸어버리겠다.\" 하며 점점 나아가니 적진이 겁에 질려 어찌할 바를 몰랐다. 이때 악대가 분을 이기지 못하여 내달아 싸우는데 십여 합에 이르러 원수의 칼빛이 번쩍이며 악대의 머리가 말 아래로 떨어졌다.","sp":[[35,37,"P","홍계월"],[75,77,"P","홍계월"],[164,166,"P","보국"],[198,200,"P","홍계월"],[247,249,"P","홍계월"],[250,252,"P","보국"],[322,324,"P","악대"],[356,358,"P","홍계월"],[369,371,"P","악대"]]},{"c":3,"sub":"졔 ᄉᆞᆷ 회: 두 원슈 군ᄉᆞ를 거ᄂᆞ려 츌젼ᄒᆞ고 오랑ᄏᆡ 크게 패ᄒᆞ야 벽ᄑᆞ도로 다라ᄂᆞ다","t":"원수는 머리를 칼끝에 꿰어 들고 또 중군장 마하명을 베고, 칼춤을 추며 본진으로 돌아와 악대의 머리를 함에 봉하여 황상께 올렸다. 이때 서달이 악대가 죽은 것을 보고 하늘을 우러러 탄식하였다. \"이제 명장을 잃었으니 평국을 누가 잡겠는가.\" 하니 철통골이 여쭈었다. \"평국을 잡을 계교가 있으니 근심하지 마십시오. 제가 아무리 용맹하여도 이 계교에는 빠질 것이니 두고 보십시오.\" 하고 이날 밤 장졸에게 명하여 군사 삼천씩 거느리고 천문동 어귀에 매복하였다가, 평국을 꾀어 골짜기 어귀에 들어오거든 사방에서 불을 지르라 하고 보냈다. [?]","sp":[[0,2,"P","홍계월"],[20,23,"P","보국"],[24,27,"P","마하명"],[49,51,"P","악대"],[64,66,"P","천자"],[76,78,"P","서달"],[80,82,"P","악대"],[121,123,"P","홍계월"],[138,141,"P","철통골"],[150,152,"P","홍계월"],[258,260,"P","홍계월"]]},{"c":3,"sub":"졔 ᄉᆞᆷ 회: 두 원슈 군ᄉᆞ를 거ᄂᆞ려 츌젼ᄒᆞ고 오랑ᄏᆡ 크게 패ᄒᆞ야 벽ᄑᆞ도로 다라ᄂᆞ다","t":"이튿날 해 뜰 무렵 철통골이 갑옷과 투구를 갖추고 진문 밖에 나서서 싸움을 걸며 크게 외쳤다. \"명나라 진의 평국은 빨리 나와 내 칼을 받아라.\" 원수가 크게 노하여 말 한 필에 칼 한 자루로 달려들어 수십여 합을 싸웠으나 승부가 나지 않았다. 철통골이 거짓으로 패한 척 투구를 벗어 들고 창을 끌며 말머리를 돌려 천문동으로 들어가므로 원수가 쫓아갔는데, 날이 이미 저물었다. 원수가 적장의 꾀에 빠진 줄 알고 말을 돌려 달아나려 할 즈음에, 사방에서 어디서 났는지 모를 불이 일어나며 불빛이 하늘을 찔렀다.","sp":[[11,14,"P","철통골"],[61,63,"P","홍계월"],[82,84,"P","홍계월"],[137,140,"P","철통골"],[188,190,"P","홍계월"],[211,213,"P","홍계월"]]},{"c":3,"sub":"졔 ᄉᆞᆷ 회: 두 원슈 군ᄉᆞ를 거ᄂᆞ려 츌젼ᄒᆞ고 오랑ᄏᆡ 크게 패ᄒᆞ야 벽ᄑᆞ도로 다라ᄂᆞ다","t":"원수는 아무리 생각해도 피할 길이 없어 하늘을 우러러 탄식하였다. \"나 하나 죽으면 천하 강산이 다 오랑캐의 세상이 되겠구나. 또 잃은 부모도 보지 못할 것이니 어찌할까.\" 하다가 문득 생각이 나서 선생이 주신 봉서를 꺼내 뜯어 보니 이렇게 쓰여 있었다. \"봉서 속에 부적을 넣었으니 천문동에서 화재를 만나거든 부적을 사방에 날리고 용(龍) 자를 세 번 부르라.\" 원수가 크게 기뻐하여 하늘에 빌고 부적을 사방에 날리며 용 자를 세 번 부르니, 이윽고 서풍이 크게 일더니 북쪽에서 검은 구름이 일어나며 천둥과 벼락이 진동하고 소나기가 쏟아졌다. 이윽고 불빛이 한꺼번에 사그라졌다.","sp":[[0,2,"P","홍계월"],[111,113,"P","곽도사"],[204,206,"P","홍계월"]]},{"c":3,"sub":"졔 ᄉᆞᆷ 회: 두 원슈 군ᄉᆞ를 거ᄂᆞ려 츌젼ᄒᆞ고 오랑ᄏᆡ 크게 패ᄒᆞ야 벽ᄑᆞ도로 다라ᄂᆞ다","t":"원수가 정신을 차려 보니 비가 그치고 달빛이 동쪽 고개에 비치고 있었다. 본진으로 돌아오며 살펴보니 서달의 십만 대군도 간 데 없고 명나라 대군도 간 데 없었다. 원수가 생각하기를 '서달이 내가 죽은 줄 알고 진을 깨뜨리고 황성으로 갔구나.' 하며 넓은 백사장에 홀로 서서 갈 곳을 몰라 탄식하였다. 이윽고 옥문관 쪽에서 함성이 들리므로 원수가 말을 채찍질하여 함성을 따라가니 징과 북소리가 진동하는데 철통골이 외치고 있었다. \"명나라 중군 보국은 달아나지 말고 내 칼을 받아라. 너희 대원수 평국은 천문동 화재에 죽었으니 어찌 나를 대적하겠느냐.\"","sp":[[0,2,"P","홍계월"],[56,58,"P","서달"],[91,93,"P","홍계월"],[102,104,"P","서달"],[189,191,"P","홍계월"],[225,228,"P","철통골"],[244,246,"P","보국"],[247,249,"P","보국"],[273,275,"P","홍계월"],[276,278,"P","홍계월"]]},{"c":3,"sub":"졔 ᄉᆞᆷ 회: 두 원슈 군ᄉᆞ를 거ᄂᆞ려 츌젼ᄒᆞ고 오랑ᄏᆡ 크게 패ᄒᆞ야 벽ᄑᆞ도로 다라ᄂᆞ다","t":"하며 마구 날뛰었다. 원수가 듣고 크게 노하여 외쳤다. \"적장은 나의 중군을 해치지 마라. 천문동 화재에 죽은 평국이 여기 왔노라.\" 하며 번개같이 달려들어 치려 하니, 서달이 철통골을 돌아보며 말했다. \"평국이 죽은 줄 알았더니 이 일을 어찌하겠는가.\" 철통골이 여쭈었다. \"이제 서둘러 도망하여 본국으로 돌아갔다가 다시 군사를 일으켜 치는 것만 못합니다. 지금은 아무리 싸우려 해도 형세가 궁하고 힘이 다하여 패할 것이니, 어서 군졸을 거느리고 벽파도로 가십시다.\" 하고 장수 삼십여 명을 거느리고 강변에 나가 어부의 배를 빼앗아 타고 벽파도로 갔다.","sp":[[12,14,"P","홍계월"],[39,41,"P","보국"],[62,64,"P","홍계월"],[95,97,"P","서달"],[99,102,"P","철통골"],[115,117,"P","홍계월"],[143,146,"P","철통골"]]},{"c":4,"sub":"제 ᄉᆞ 회: 홍시랑이 의외에 계월을 만나고 영화로이 황셩으로 도라오다","t":"이때 원수가 말 한 필에 창 하나로 짓쳐 들어가니, 칼빛은 번개 같고 주검은 언덕처럼 쌓였다. 원수가 한 칼로 십여만 대군을 깨뜨리고 서달 등을 찾으려고 살펴보니, 조금 남은 군사들이 다 달아나며 울면서 말했다. \"서달아, 너는 도망하여 살려 하고 우리는 외로운 넋이 되라 하고 도망하느냐.\" 하며 슬피 우니 원수가 듣기에 도리어 처량하였다. 이때 원수가 서달 등을 찾으려 할 즈음에 문득 옥문관 쪽에서 요란한 소리가 들려왔다.","sp":[[3,5,"P","홍계월"],[53,55,"P","홍계월"],[75,77,"P","서달"],[120,122,"P","서달"],[173,175,"P","홍계월"],[195,197,"P","홍계월"],[199,201,"P","서달"]]},{"c":4,"sub":"제 ᄉᆞ 회: 홍시랑이 의외에 계월을 만나고 영화로이 황셩으로 도라오다","t":"원수는 '적장이 그리로 갔구나.' 하고 급히 말을 채찍질하여 갔다. 이때 보국은 이런 줄도 모르고 가슴을 두드리다가, 희미한 달빛에 누군가 오는 것을 보고 적장이 오는가 하여 달아났다. 후군이 여쭈었다. \"뒤에 오는 장수가 천문동 화재에 돌아가신 우리 원수의 혼백인가 봅니다.\" 중군이 크게 놀라 \"어찌 아느냐?\" 하니 후군이 여쭈었다. \"희미한 달빛에 보니 타신 말이 준총마요, 투구와 갑옷이며 거동이 원수가 분명합니다.\" 보국이 그 말을 듣고 반가워 군사를 멈추고 서서 기다리는데, 원수의 목소리가 들리므로 보국이 크게 기뻐하여 외쳤다. \"소장은 중군 보국이니 기운을 허비하지 마십시오.\"","sp":[[0,2,"P","홍계월"],[41,43,"P","보국"],[141,143,"P","홍계월"],[156,158,"P","보국"],[226,228,"P","홍계월"],[238,240,"P","보국"],[272,274,"P","홍계월"],[286,288,"P","보국"],[308,310,"P","보국"],[311,313,"P","보국"]]},{"c":4,"sub":"제 ᄉᆞ 회: 홍시랑이 의외에 계월을 만나고 영화로이 황셩으로 도라오다","t":"원수가 듣고 의심하여 크게 외쳤다. \"네가 분명 보국이면 군사를 시켜 칼을 보내라.\" 보국이 크게 기뻐하여 칼과 수기를 보내니, 원수가 보고 달려와 말에서 내려 보국의 손을 잡고 장막 안으로 들어가 기뻐하며, 천문동 화재에 죽게 되었다가 선생의 봉서를 보고 이러이러하여 벗어난 일과, 본진으로 오다가 적진을 깨뜨렸고 서달 등은 도망하여 벽파도로 갔다는 일을 이야기하며 서로 묻고 답하기를 물 흐르듯 하였다. 원수가 곧 군사를 거느리고 강변에 이르러 고깃배를 잡아 건너가는데, 배마다 깃발과 창검을 세우고 원수는 배 안에 높이 자리 잡고 앉아 갑옷과 투구를 갖추고 석 자 장검을 높이 들고 중군에 호령하여 배를 급히 저어 벽파도로 향하였다. 씩씩한 위풍과 늠름한 거동이 당대의 영웅이었다. 이때 홍시랑은 부인과 함께","sp":[[0,2,"P","홍계월"],[27,29,"P","보국"],[48,50,"P","보국"],[72,74,"P","홍계월"],[90,92,"P","보국"],[133,135,"P","곽도사"],[177,179,"P","서달"],[228,230,"P","홍계월"],[282,284,"P","홍계월"],[329,331,"P","보국"],[388,391,"P","홍무"],[393,395,"P","양부인"]]},{"c":4,"sub":"제 ᄉᆞ 회: 홍시랑이 의외에 계월을 만나고 영화로이 황셩으로 도라오다","t":"계월을 밤낮으로 생각하며 날마다 슬퍼하고 있었는데, 뜻밖에 떠들썩한 소리가 나므로 놀라 급히 초막 밖에 나가 보니 수많은 도적이 둘러싸고 있었다. 시랑이 부인을 데리고 허둥지둥 도망하여 산골짜기로 들어가 바위틈에 몸을 숨기고 통곡하였다. 이튿날 해 뜰 무렵 또 강 위를 바라보니 배에 군사를 싣고 깃발과 창검이 서리 같고 함성이 진동하며 벽파도로 향해 오고 있었다. 시랑은 더욱 놀라 몸을 숨기고 있었다. 원수가 벽파도에 이르러 배를 강변에 매고 진을 치며 호령하였다. \"서달 등을 어서 잡아라.\" 여러 장수가 한꺼번에 함성을 지르며 벽파도를 에워싸니, 서달이 어쩔 수 없어 자결하려 하다가 원수의 장졸에게 붙잡혔다.","sp":[[0,2,"P","홍계월"],[82,84,"P","홍무"],[86,88,"P","양부인"],[205,207,"P","홍무"],[227,229,"P","홍계월"],[264,266,"P","서달"],[310,312,"P","서달"],[331,333,"P","홍계월"]]},{"c":4,"sub":"제 ᄉᆞ 회: 홍시랑이 의외에 계월을 만나고 영화로이 황셩으로 도라오다","t":"원수가 장대에 높이 앉아 서달 등을 장대 아래 꿇리고 호령하였다. \"이 도적들을 차례로 원문 밖에 내어 베라.\" 무사들이 한꺼번에 달려들어 철통골을 먼저 끌어내어 베고 나머지 장수도 차례로 베었다. 이때 군졸이 원수에게 여쭈었다. \"어떤 사람이 여인 세 사람을 데리고 산속에 숨어 있기에 잡아 대령하였습니다.\" 원수가 잠시 멈추고 그 네 사람을 잡아들이라 하니, 무사들이 내달아 결박하여 장대 아래 꿇리고 죄목을 물었다. 네 사람은 넋을 잃었다.","sp":[[0,2,"P","홍계월"],[14,16,"P","서달"],[78,81,"P","철통골"],[118,120,"P","홍계월"],[174,176,"P","홍계월"]]},{"c":4,"sub":"제 ᄉᆞ 회: 홍시랑이 의외에 계월을 만나고 영화로이 황셩으로 도라오다","t":"원수가 책상을 치며 말했다. \"너희를 보니 대국의 옷차림이다. 적병에게 응하여 한마음으로 힘을 합했던 것을 바로 아뢰어라.\" 시랑이 겁에 질렸다가 정신을 가다듬고 말했다. \"소인은 전에 대국에서 시랑 벼슬을 하다가 소인배의 참소를 만나 고향에 돌아가 농사를 짓고 있었는데, 장사랑의 난에 이렇게 잡혀 와 이 꼴이 되어 이곳으로 귀양 온 죄인이니 죽어 마땅합니다.\" 원수가 이 말을 듣고 크게 꾸짖었다. \"네가 천자의 성은을 저버리고 역적 장사랑에게 붙었는데, 성상께서 어지시어 죽이지 않고 이곳으로 귀양 보내셨으니 그 은혜를 생각하면 뼈에 새겨 잊지 못할 일이다. 그런데 이제 또 적장의 내응이 되었다가 이렇게 잡혔으니 무슨 변명을 하겠느냐.\"","sp":[[0,2,"P","홍계월"],[70,72,"P","홍무"],[109,111,"P","홍무"],[153,156,"P","장사랑"],[204,206,"P","홍계월"],[229,231,"P","천자"],[245,248,"P","장사랑"],[257,259,"P","천자"]]},{"c":4,"sub":"제 ᄉᆞ 회: 홍시랑이 의외에 계월을 만나고 영화로이 황셩으로 도라오다","t":"하고 끌어내어 베라 하니 양부인이 하늘을 우러러 통곡하였다. \"아이고, 이게 웬일인가. 계월아, 계월아, 너와 함께 강물에 빠져 죽었더라면 이런 일은 보지 않았을 것을, 하늘이 미워하시어 모진 목숨이 살았다가 이런 화를 보는구나.\" 하며 기절하였다. 이때 원수가 그 말을 듣고 문득 선생이 하시던 말씀을 생각하고 크게 놀라, 좌우를 다 물리고 앞에 가까이 앉혀 조용히 물었다. \"아까 들으니 계월과 함께 죽지 못한 것을 한탄하던데, 계월은 누구이며 그대의 성명은 무엇이오?\" 부인이 말했다. \"소녀는 대국 형주 구계촌에 사는 양처사의 딸이며, 남편은 홍시랑이고, 저 계집은 시비 양윤이며, 계월은 소녀의 딸입니다.\" 하며 앞뒤 사정을 낱낱이 아뢰니, 원수가 이 말을 듣고 정신이 아득하여 세상일이 다 꿈속 같았다.","sp":[[14,17,"P","양부인"],[49,51,"P","홍계월"],[54,56,"P","홍계월"],[143,145,"P","홍계월"],[158,160,"P","곽도사"],[219,221,"P","홍계월"],[242,244,"P","홍계월"],[266,268,"P","양부인"],[308,311,"P","홍무"],[321,326,"P","양윤"],[330,332,"P","홍계월"],[364,366,"P","홍계월"]]},{"c":4,"sub":"제 ᄉᆞ 회: 홍시랑이 의외에 계월을 만나고 영화로이 황셩으로 도라오다","t":"원수가 급히 뛰어 내려 부인을 붙들고 통곡하였다. \"어머님, 제가 물에 떠가던 계월입니다.\" 하며 기절하니, 부인과 시랑이 서로 붙들고 통곡하다 기절하였다. 천여 명의 장수와 팔십만 대군이 이 광경을 보고 어찌 된 일인지 몰라 서로 돌아보며 수군거리고, 어떤 이는 눈물을 흘리며 천고에 없는 일이라 하면서 명령이 내리기를 기다렸다. 보국은 이미 평국이 부모를 잃은 줄 알고 있었다. 원수가 정신을 가다듬고 부모를 장대에 모시고 아뢰었다. \"그때 물에 떠가다가 무릉포 여공을 만나, 여공이 건져서 집으로 데려가 친자식같이 길렀습니다. 그 아들 보국과 함께 어진 선생을 만나 한 스승 밑에서 배우고, 선생의 어진 덕택으로 황성에 올라가 둘이 함께 급제하여 한림학사로 있었습니다. 서달이 반란을 일으키자 소자는 대원수가 되고","sp":[[0,2,"P","홍계월"],[13,15,"P","양부인"],[44,46,"P","홍계월"],[61,63,"P","양부인"],[65,67,"P","홍무"],[186,188,"P","보국"],[193,195,"P","홍계월"],[214,216,"P","홍계월"],[261,263,"P","여공"],[269,271,"P","여공"],[303,305,"P","보국"],[313,315,"P","곽도사"],[334,336,"P","곽도사"],[378,380,"P","서달"],[396,398,"P","홍계월"]]},{"c":4,"sub":"제 ᄉᆞ 회: 홍시랑이 의외에 계월을 만나고 영화로이 황셩으로 도라오다","t":"보국은 중군이 되어 이번 싸움에서 적진을 깨뜨렸는데, 서달 등이 도망하여 이곳으로 오기에 잡으러 왔다가 다행히 부모님을 만났습니다.\" 하며 앞뒤 사정을 낱낱이 아뢰었다. 시랑과 부인이 듣고 고생하던 이야기를 하며 슬피 통곡하니 산천초목이 다 눈물을 머금는 듯하였다. 원수가 정신을 가다듬고 부인의 젖가슴을 만지며 새로이 통곡하다가 양윤 등을 어루만지며 말했다. \"내가 네 등에서 떠나지 않던 정과, 내가 물에 떠갈 때 네가 애통해하던 일을 생각하면 칼로 살을 베는 듯하구나.","sp":[[0,2,"P","보국"],[4,6,"P","보국"],[30,32,"P","서달"],[95,97,"P","홍무"],[99,101,"P","양부인"],[149,151,"P","홍계월"],[162,164,"P","양부인"],[185,187,"P","양윤"]]},{"c":4,"sub":"제 ᄉᆞ 회: 홍시랑이 의외에 계월을 만나고 영화로이 황셩으로 도라오다","t":"너는 부인을 모시고 죽을 고비를 여러 번 넘기다가 이렇게 만나니 어찌 즐겁지 않겠느냐.\" 하고 춘낭 앞에 나아가 절하고 공경하여 사례하였다. \"저승에 가서나 만날 어머님을 이승에서 만나 뵙게 된 것은 다 부인의 덕택이니 이 은혜를 어찌 다 갚겠습니까?\" 춘낭이 답례하며 말했다. \"미천한 사람을 이토록 후하게 대해 주시니 황공하여 드릴 말씀이 없습니다.\" 원수가 붙들어 대 위에 앉히고 더욱 공경하였다. 이때 중군장 보국이 장대 앞에 들어와 문안하고 원수에게 부모를 상봉한 것을 축하하였다. 원수가 대 아래로 내려가 보국의 손을 잡고 대 위로 올라가 시랑에게 뵙게 하며 말했다. \"이 사람이 소자와 함께 배운 여공의 아들 보국입니다.\" 시랑이 듣고 급히 일어나 보국의 손을 잡고 눈물을 흘리며 말했다. \"그대 부친의 덕택으로 죽었던 자식을","sp":[[3,5,"P","양부인"],[53,55,"P","춘낭"],[114,116,"P","양부인"],[142,144,"P","춘낭"],[199,201,"P","홍계월"],[229,232,"P","보국"],[233,235,"P","보국"],[252,254,"P","홍계월"],[275,277,"P","홍계월"],[289,291,"P","보국"],[308,310,"P","홍무"],[341,343,"P","여공"],[348,350,"P","보국"],[356,358,"P","홍무"],[370,372,"P","보국"]]},{"c":4,"sub":"제 ᄉᆞ 회: 홍시랑이 의외에 계월을 만나고 영화로이 황셩으로 도라오다","t":"다시 보게 되었으니 이는 결초보은(結草報恩)하여도 다 갚지 못할 것인데 무엇으로 갚겠는가.\" 보국이 사례하고 물러나니 온 진의 장졸도 원수가 부모를 상봉한 것을 앞다투어 축하하였다. 이튿날 해 뜰 무렵 원수가 군중에 자리를 잡고 앉아 군사에게 호령하여 서달 등을 꿇리고 항서를 받은 뒤, 장대에 올려 앉히고 도리어 사례하며 말했다. \"그대가 만일 이곳으로 오지 않았더라면 내가 어찌 부모를 만났겠는가. 이후로는 도리어 은인이 되었구나.\"","sp":[[52,54,"P","보국"],[75,77,"P","홍계월"],[113,115,"P","홍계월"],[141,143,"P","서달"]]},{"c":4,"sub":"제 ᄉᆞ 회: 홍시랑이 의외에 계월을 만나고 영화로이 황셩으로 도라오다","t":"서달 등이 그 말을 듣고 감사하여 엎드려 은혜에 감사하였다. \"무도한 도적이 원수의 손에 죽을까 하였는데 도리어 감사하다는 말씀을 들으니, 이제 죽더라도 원수의 덕택은 갚을 길이 없습니다.\" 원수가 서달 등을 본국으로 돌려보내고, 곧 그 고을 수령에게 명하여 안장 얹은 말과 가마를 대령하라 하였다. 그리고 부친과 모부인을 모시고 일천 장수와 팔십만 군사를 거느려 호위하며 옥문관으로 향하니, 수레와 깃발과 짐바리가 천자의 행차에 견줄 만하였다. 옥문관에 이르러 이 사연을 천자께 아뢰었다.","sp":[[0,2,"P","서달"],[43,45,"P","홍계월"],[86,88,"P","홍계월"],[107,109,"P","홍계월"],[111,113,"P","서달"],[177,179,"P","양부인"],[233,235,"P","천자"],[265,267,"P","천자"]]},{"c":4,"sub":"제 ᄉᆞ 회: 홍시랑이 의외에 계월을 만나고 영화로이 황셩으로 도라오다","t":"이때 천자께서 악대의 머리를 받아 보신 뒤로 원수의 소식을 몰라 밤낮으로 염려하시는데, 황경문의 장졸이 장계를 올렸다. 천자께서 뜯어 보시니 이렇게 쓰여 있었다. \"한림학사 겸 대원수 평국은 머리를 조아려 백 번 절하옵고 글 한 장을 탑하에 올립니다. 서달 등을 쳐서 깨뜨릴 때 도적이 도망하여 벽파도로 가기에 쫓아 들어가 적졸을 다 잡은 뒤에 잃었던 부모를 만났습니다. 이는 성상의 덕택이니 살펴 주십시오. 아비는 장사랑의 도적 무리와 함께 잡혀 벽파도로 귀양 보내신 홍무입니다. 바라건대 폐하께서는 신의 벼슬을 거두시어 아비의 죄를 속하고 뒷사람이 본받게 하시면, 신은 아비를 데리고 고향에 돌아가 남은 생을 마치고자 합니다.\"","sp":[[3,5,"P","천자"],[8,10,"P","악대"],[25,27,"P","홍계월"],[67,69,"P","천자"],[100,102,"P","홍계월"],[103,105,"P","홍계월"],[141,143,"P","서달"],[211,213,"P","천자"],[233,236,"P","장사랑"],[263,265,"P","홍무"],[275,277,"P","천자"]]},{"c":4,"sub":"제 ᄉᆞ 회: 홍시랑이 의외에 계월을 만나고 영화로이 황셩으로 도라오다","t":"천자께서 보시고 크게 놀라고 크게 기뻐하시며 말씀하셨다. \"평국이 한 번 가서 적병을 평정하니 상쾌하고, 또 잃었던 부모를 만났다 하니 이는 하늘이 감동하신 것이다.\" 하시고 또 말씀하셨다. \"대원수를 갈면 승상이 될 것이니 어찌 그 아비에게 벼슬이 없겠는가.\" 하시고 홍무에게 벼슬을 내려 위국공으로 봉하시고, 그 부인에게 봉작 직첩을 내리시어 위국공의 봉작과 함께 사관을 시켜 내려 보내셨다. \"짐이 밝지 못한 탓으로 원수의 아비를 귀양 보내 여러 해 고생하게 하였는데, 다행히 원수를 만나 영화롭게 돌아오니 어찌 그 영화를 빛내지 않겠는가.\" [?]","sp":[[0,2,"P","천자"],[33,35,"P","홍계월"],[109,111,"P","홍계월"],[151,153,"P","홍무"],[163,166,"P","홍무"],[177,179,"P","양부인"],[194,197,"P","홍무"],[236,238,"P","홍계월"],[270,272,"P","홍계월"]]},{"c":4,"sub":"제 ᄉᆞ 회: 홍시랑이 의외에 계월을 만나고 영화로이 황셩으로 도라오다","t":"하시고 궁녀 삼백 명을 가려 뽑아 초록 저고리에 붉은 치마를 입히고, 부인을 모실 금덩(金轎)과 쌍가마를 보내시어 시녀들이 호위하여 황성까지 오게 하셨다. 어전 풍류와 비단옷 입은 화동 천여 명을 거느리고 옥문관으로 향하였다. 이때 사관이 봉작 직첩과 위국공 봉작을 원수에게 드리니, 시랑과 부인이 받아 보고 기쁨을 이기지 못하여 북쪽을 향해 네 번 절하고 뜯어 보았다. 시랑을 위국공으로, 부인을 정렬부인으로 봉하신 직첩이었다. 또 비답이 있어 보니 이렇게 쓰여 있었다. \"원수가 한 번 가서 북방을 평정하고 사직을 보전하니 그 공이 적지 않으며, 또 잃었던 부모를 만났으니 이런 일은 옛날에도 드문 일이다.","sp":[[39,41,"P","양부인"],[141,144,"P","홍무"],[149,151,"P","홍계월"],[159,161,"P","홍무"],[163,165,"P","양부인"],[208,210,"P","홍무"],[212,215,"P","홍무"],[219,221,"P","양부인"],[223,227,"P","양부인"],[266,268,"P","홍계월"]]},{"c":4,"sub":"제 ᄉᆞ 회: 홍시랑이 의외에 계월을 만나고 영화로이 황셩으로 도라오다","t":"또 짐이 어질지 못하여 경의 부친을 먼 땅에 귀양 보내 여러 해 고생하게 하였으니 짐이 도리어 경을 볼 면목이 없도다. 그러나 어서 올라와 짐이 기다리지 않게 하라.\" 위국공 부녀가 황은에 감사하고 이날 길을 떠나려 하는데, 또 부인을 모실 금덩과 갖가지 의장을 내려 보내셨다. 원수가 곧 위의를 갖추어 부인을 금덩에 모시고 삼백 시녀가 호위하며, 비단옷 입은 화동을 좌우로 갈라 세우고 어전 풍류를 울리며 꽃밭을 이루어 오는데, 춘낭과 양윤은 쇄금 가마를 타고 원수는 위국공을 모시고 왔다. 팔십만 대군과 장수 천여 명을 중군장이 거느리고 선봉이 되어 승전고를 울리며 사십 리 넓은 들에 늘어서 왔다.","sp":[[94,97,"P","홍무"],[128,130,"P","양부인"],[156,158,"P","홍계월"],[170,172,"P","양부인"],[241,243,"P","춘낭"],[245,247,"P","양윤"],[259,261,"P","홍계월"],[263,266,"P","홍무"],[293,296,"P","보국"]]},{"c":4,"sub":"제 ᄉᆞ 회: 홍시랑이 의외에 계월을 만나고 영화로이 황셩으로 도라오다","t":"이때 천자께서 백관을 거느리시고 원수를 맞으시니, 위국공과 원수가 말에서 내려 엎드렸다. 천자께서 반기시며 말씀하셨다. \"짐이 밝지 못한 탓으로 위국공이 여러 해 고생하였으니 짐이 도리어 부끄럽도다.\" 하시며 한 손으로 위국공의 손을 잡고 또 한 손으로 원수의 손을 잡으시고, 보국을 돌아보며 말씀하셨다. \"짐이 어찌 수레를 타고 경들을 맞겠는가.\" 하시고 천자께서 삼십 리를 걸어가시니 백관도 걸어왔다. 모든 백성이 둘러싸고 대명전까지 들어오니 보는 사람 누가 칭찬하지 않았겠는가.","sp":[[3,5,"P","천자"],[18,20,"P","홍계월"],[28,31,"P","홍무"],[33,35,"P","홍계월"],[50,52,"P","천자"],[81,84,"P","홍무"],[123,126,"P","홍무"],[142,144,"P","홍계월"],[155,157,"P","보국"],[200,202,"P","천자"]]},{"c":4,"sub":"제 ᄉᆞ 회: 홍시랑이 의외에 계월을 만나고 영화로이 황셩으로 도라오다","t":"천자께서 전에 오르시어 원수를 좌승상 청주후로 봉하시고 보국을 대사마 대장군 이부시랑으로 삼으시고, 나머지 장수들은 차례로 공을 적으셨다. 그리고 원수에게 분부하셨다. \"경이 다섯 살에 부모를 잃었다 하니 누구 집에 의탁하여 자랐으며, 병서는 누구에게 배웠으며, 경의 모친은 누구에게 가서 십삼 년을 고생으로 지내다가 벽파도에서 위국공을 만났느냐? 사실을 듣고자 한다.\" 원수가 앞뒤 사정을 자세히 아뢰니 천자께서 칭찬하시며 말씀하셨다. \"이는 고금에 없는 일이로다.\" 또 말씀하셨다. \"경이 물속의 외로운 넋이 될 것을 여공의 덕택으로 살아나 공을 이루어 짐을 돕게 되었으니 여공의 공이 어찌 없다 하겠는가.\"","sp":[[0,2,"P","천자"],[13,15,"P","홍계월"],[17,20,"P","보국"],[31,33,"P","보국"],[35,42,"P","보국"],[45,47,"P","홍무"],[82,84,"P","홍계월"],[184,187,"P","홍무"],[208,210,"P","홍계월"],[227,229,"P","천자"],[292,294,"P","여공"],[323,325,"P","여공"]]},{"c":4,"sub":"제 ᄉᆞ 회: 홍시랑이 의외에 계월을 만나고 영화로이 황셩으로 도라오다","t":"하시고 여공을 우복야 기주후로 봉하시고 그 부인을 공렬부인으로 봉하시어, 봉작 직첩을 사관 편에 무릉포로 보내셨다. 이때 여공 부부가 직첩을 받고 북쪽을 향해 네 번 절한 뒤 곧 행장을 차려 부인과 함께 황성에 올라왔다. 여공이 탑전에 들어가 은혜에 감사하여 엎드려 절하니 천자께서 반기시며 칭찬하셨다. \"경이 평국을 길러 내어 사직을 보전하게 하였으니 그 공이 적지 않도다.\" 여공이 물러나오자 위국공과 정렬부인이 자리에서 일어나 사례하였다. \"어지신 덕택으로 계월을 구하시어 친자식같이 길러 입신양명하게 하셨으니 그 은혜는 백골이 되어도 잊지 못하겠습니다.\" 하며 슬픈 감회를 금치 못하였다.","sp":[[4,6,"P","여공"],[8,15,"P","여공"],[24,26,"P","양부인"],[28,32,"P","공렬부인"],[68,70,"P","여공"],[107,109,"P","양부인"],[124,126,"P","여공"],[153,155,"P","천자"],[174,176,"P","홍계월"],[212,214,"P","여공"],[222,225,"P","홍무"],[227,231,"P","양부인"],[259,261,"P","홍계월"]]},{"c":4,"sub":"제 ᄉᆞ 회: 홍시랑이 의외에 계월을 만나고 영화로이 황셩으로 도라오다","t":"여공은 더욱 감사하여 공손히 응답하였다. 평국과 보국도 엎드려 먼 길에 평안히 오신 것을 축하하였다. 위국공과 정렬부인이며 기주후와 공렬부인, 그리고 춘낭도 자리에 참여하였고, 양윤도 마음속 기쁨을 헤아릴 수 없었다. 이날 큰 잔치를 벌여 사흘 동안 즐겼다. 이때 천자께서 신하들을 돌아보며 \"평국과 보국은 한 궁궐 안에 살게 하리라.\" 하시고 종남산 아래에 터를 닦아 집을 지으니, 천여 칸을 며칠 안 되어 지어 내어 그 웅장함을 헤아릴 수 없었다. 집을 다 지은 뒤 노비 천 명과 수설군 백 명씩을 내리시고, 또 채색 비단과 보화를 수천 바리 상으로 내리셨다. 평국과 보국이 황은에 감사하고 한 궁궐 안에 침소를 정해 지내니, 궁궐 안이 길이와 너비가 이십 리가 넘었다.","sp":[[0,2,"P","여공"],[23,25,"P","홍계월"],[27,29,"P","보국"],[57,60,"P","홍무"],[62,66,"P","양부인"],[69,72,"P","여공"],[74,78,"P","공렬부인"],[84,86,"P","춘낭"],[99,101,"P","양윤"],[148,150,"P","천자"],[164,166,"P","홍계월"],[168,170,"P","보국"],[316,318,"P","홍계월"],[320,322,"P","보국"]]},{"c":4,"sub":"제 ᄉᆞ 회: 홍시랑이 의외에 계월을 만나고 영화로이 황셩으로 도라오다","t":"위의와 거동이 천자와 다름이 없었다. 이때 평국이 싸움터에 다녀온 뒤로 저절로 몸이 고단하여 병이 깊어지니, 집안이 놀라 밤낮으로 약을 써 치료하였다. 천자께서 이 말을 들으시고 크게 놀라시어 \"명의를 보내어 병세를 자세히 보고 오라. 만일 위중하면 짐이 친히 가 보겠다.\" 하시고 어의에게 명하여 보내셨다. 어의가 황명을 받들어 평국의 침소에 와서 맥을 짚어 보니 병세가 위중하지 않았다. 약을 가르쳐 주어 쓰라 하고 돌아와 천자께 아뢰었다.","sp":[[8,10,"P","천자"],[24,26,"P","홍계월"],[85,87,"P","천자"],[158,160,"P","어의"],[173,175,"P","어의"],[185,187,"P","홍계월"],[239,241,"P","천자"]]},{"c":5,"sub":"제 오 회: 계월이 녀ᄌᆞ의 본ᄉᆡᆨ이 탄로ᄒᆞ고 보국과 동방화촉을 ᄆᆡᆺ다","t":"한편 어의가 돌아와 천자께 아뢰었다. \"평국의 병세는 위중하지 않아 약을 가르쳐 주어 쓰라 하고 왔으나, 또한 괴이한 일이 있어 수상합니다.\" 천자께서 놀라 물으셨다. \"무슨 까닭이 있느냐?\" 어의가 엎드려 아뢰었다. \"평국의 맥을 보니 남자의 맥이 아니어서 이상합니다.\" 천자께서 그 말을 들으시고 말씀하셨다. \"평국이 여자라면 어찌 적진에 나가 적의 십만 대군을 무찌르고 왔겠느냐.\" 하시며 \"평국의 얼굴이 복숭아꽃 빛이고 온몸이 가냘프니 혹 미심쩍기는 하나 아직은 누설하지 마라.\" 하시고 자주 문병하셨다.","sp":[[3,5,"P","어의"],[11,13,"P","천자"],[22,24,"P","홍계월"],[80,82,"P","천자"],[108,110,"P","어의"],[123,125,"P","홍계월"],[153,155,"P","천자"],[176,178,"P","홍계월"],[222,224,"P","홍계월"]]},{"c":5,"sub":"제 오 회: 계월이 녀ᄌᆞ의 본ᄉᆡᆨ이 탄로ᄒᆞ고 보국과 동방화촉을 ᄆᆡᆺ다","t":"이때 평국은 병세가 점점 나아지자 생각하였다. '어의가 내 맥을 보았으니 반드시 본색이 드러날 것이다. 이제는 어쩔 수 없게 되었으니 여자 옷으로 갈아입고 규중에 몸을 숨겨 세월을 보내는 것이 옳다.' 하고 곧 남자 옷을 벗고 여자 옷을 입고 부모 앞에 뵈며 흐느끼니 두 뺨에 눈물이 줄줄 흘렀다. 부모도 눈물을 흘리며 위로하였다. 계월이 슬퍼하여 우는 모습은 가을 구월의 연꽃이 가랑비를 머금은 듯, 초승달이 시름겨운 구름에 잠긴 듯하였고, 곱고 아리따운 자태는 당대의 으뜸이었다.","sp":[[3,5,"P","홍계월"],[27,29,"P","어의"],[186,188,"P","홍계월"]]},{"c":5,"sub":"제 오 회: 계월이 녀ᄌᆞ의 본ᄉᆡᆨ이 탄로ᄒᆞ고 보국과 동방화촉을 ᄆᆡᆺ다","t":"이때 계월이 천자께 상소를 올리니 천자께서 보시매 이렇게 쓰여 있었다. \"한림학사 겸 대원수 좌승상 청주후 평국은 머리를 조아려 백 번 절하옵고 글 한 장을 올립니다. 신첩은 만 다섯 살에 장사랑의 난으로 부모를 잃고, 수적 맹길의 난을 만나 물속의 외로운 넋이 될 것을 여공의 은덕으로 살아났습니다. 그러나 곰곰이 생각해 보니 여자의 행실을 지켜서는 규중에서 늙어 부모의 해골도 찾지 못하게 되겠기에, 여자의 행실을 버리고 남자의 옷차림을 하여 황상을 속이고 조정에 들어왔습니다. 신첩의 죄는 만 번 죽어도 아깝지 않으니 달게 벌을 기다리며 유지(諭旨)와 관인을 올립니다. 임금을 속이고 윗사람을 업신여긴 첩의 죄를 다스리시어 속히 처형하여 주십시오.\"","sp":[[3,5,"P","홍계월"],[7,9,"P","천자"],[19,21,"P","천자"],[49,51,"P","홍계월"],[52,55,"P","보국"],[60,62,"P","홍계월"],[106,109,"P","장사랑"],[123,128,"P","맹길"],[152,154,"P","여공"],[250,252,"P","천자"]]},{"c":5,"sub":"제 오 회: 계월이 녀ᄌᆞ의 본ᄉᆡᆨ이 탄로ᄒᆞ고 보국과 동방화촉을 ᄆᆡᆺ다","t":"천자께서 보시고 용상을 치시며 좌우를 돌아보고 말씀하셨다. \"평국의 행동을 보고 누가 여자로 보았겠는가. 고금에 없는 일이로다. 천하가 넓다 하나 문무를 겸전하고 충성을 다해 나라에 보답하며 충효를 아울러 갖춘 재주는 남자라도 미치지 못할 것이다. 비록 여자이나 벼슬을 어찌 거두겠는가.\" 하시고 환관에게 명하여 유지와 인신을 도로 돌려보내시고 비답을 내리셨다. 계월이 황공하고 감사하여 받아 보니 이렇게 쓰여 있었다. \"경의 상소를 보고 놀랍고 한편 장하구나. 충효를 겸하여 반역의 무리를 없애고 사직을 보전한 것은 모두 경의 산과 바다 같은 은덕이다.","sp":[[0,2,"P","천자"],[34,36,"P","홍계월"],[203,205,"P","홍계월"]]},{"c":5,"sub":"제 오 회: 계월이 녀ᄌᆞ의 본ᄉᆡᆨ이 탄로ᄒᆞ고 보국과 동방화촉을 ᄆᆡᆺ다","t":"짐이 어찌 여자라 하여 꺼리겠는가. 유지와 인신을 도로 보내니 조금도 개의치 말고 경은 충성을 다해 나라에 보답하여 짐을 도우라.\" 계월이 사양하지 못하여 여자 옷을 입고 그 위에 조복을 입고, 거느리던 장수 백여 명과 군사 천여 명에게 갑옷과 투구를 갖추어 승상부 문 밖에 진을 치고 있게 하니 그 위엄이 엄숙하였다. 하루는 천자께서 위국공을 들라 하시어 말씀하셨다. \"짐이 원수의 상소를 본 뒤로 생각이 많다. 평국이 규중에서 홀로 늙으면 홍무의 혼백이 의지할 곳이 없을 것이니 어찌 슬프지 않겠는가.","sp":[[74,76,"P","홍계월"],[183,185,"P","천자"],[188,191,"P","홍무"],[211,213,"P","홍계월"],[232,234,"P","홍계월"],[248,250,"P","홍무"]]},{"c":5,"sub":"제 오 회: 계월이 녀ᄌᆞ의 본ᄉᆡᆨ이 탄로ᄒᆞ고 보국과 동방화촉을 ᄆᆡᆺ다","t":"또 평국의 혼인은 짐이 중매를 서고자 하는데 어떠한가?\" 위국공이 엎드려 아뢰었다. \"신의 뜻도 그러하니 소신이 나아가 의논하겠거니와, 평국의 배필은 누구로 정하려 하십니까?\" 천자께서 말씀하셨다. \"평국과 함께 배운 보국과 혼인을 정하고자 하니 경의 마음은 어떠한가?\" 위국공이 아뢰었다. \"신의 뜻도 그러하니 하교가 마땅합니다. 평국이 물에 빠져 죽을 목숨을 여공의 덕으로 살았고, 여공이 친자식같이 길러 부귀영화를 누리게 하고 이별했던 부모를 만나게 하였습니다. 또 보국과 함께 배워 함께 급제하고 폐하의 성덕으로 벼슬을 받아 만 리 싸움터에서 죽고 사는 고락을 함께하였으며, 돌아와서는 한 집에서 지내니 하늘이 정한 연분인가 합니다.\" [?]","sp":[[2,4,"P","홍계월"],[32,35,"P","홍무"],[76,78,"P","홍계월"],[99,101,"P","천자"],[112,114,"P","홍계월"],[122,124,"P","보국"],[152,155,"P","홍무"],[186,188,"P","홍계월"],[203,205,"P","여공"],[216,218,"P","여공"],[264,266,"P","보국"],[282,284,"P","천자"]]},{"c":5,"sub":"제 오 회: 계월이 녀ᄌᆞ의 본ᄉᆡᆨ이 탄로ᄒᆞ고 보국과 동방화촉을 ᄆᆡᆺ다","t":"하고 물러나와 계월을 불러 앉히고 천자께서 하교하신 말씀을 낱낱이 전하였다. 계월이 여쭈었다. \"소녀의 마음은 평생 홀로 늙어 부모님 슬하에 있다가, 부모님께서 돌아가신 뒤에 죽어 다시 남자로 태어나 공자와 맹자의 행실을 배우고자 하였습니다. 그런데 근본이 드러나 천자께서 이렇게 하교하시고, 부모님 슬하에 다른 자식이 없어 슬픈 마음을 품고 선영의 제사를 전할 곳이 없으니, 자식이 되어 부모님 명을 어찌 거역하며 천자의 하교를 어찌 거역하겠습니까. 하교를 좇아 보국을 섬겨 여공의 은혜를 만분의 일이라도 갚을까 하니, 부친께서는 이 사연을 천자께 아뢰어 주십시오.\"","sp":[[8,10,"P","홍계월"],[19,21,"P","천자"],[43,45,"P","홍계월"],[148,150,"P","천자"],[233,235,"P","천자"],[260,262,"P","보국"],[267,269,"P","여공"],[304,306,"P","천자"]]},{"c":5,"sub":"제 오 회: 계월이 녀ᄌᆞ의 본ᄉᆡᆨ이 탄로ᄒᆞ고 보국과 동방화촉을 ᄆᆡᆺ다","t":"하며 눈물을 흘리고 남자로 태어나지 못한 것을 한탄하였다. 이때 위국공이 곧 대궐에 들어가 계월이 한 말을 낱낱이 아뢰니, 천자께서 크게 기뻐하시어 곧 여공을 패초(牌招)하라 하시고 말씀하셨다. \"이 일은 천고에 드문 일이니 어찌 중매 소임을 소홀히 하겠는가.\" 그리고 여공에게 하교하셨다. \"평국과 보국을 부부로 정하고자 하니 경의 뜻은 어떠한가?\" 여공이 아뢰었다. \"폐하의 해와 달 같은 덕택으로 어진 며느리와 혼인을 맺어 주려 하시니 감사하기 그지없어 아뢸 말씀이 없습니다.\"","sp":[[36,39,"P","홍무"],[51,53,"P","홍계월"],[69,71,"P","천자"],[85,87,"P","여공"],[151,153,"P","여공"],[164,166,"P","홍계월"],[168,170,"P","보국"],[197,199,"P","여공"],[208,210,"P","천자"]]},{"c":5,"sub":"제 오 회: 계월이 녀ᄌᆞ의 본ᄉᆡᆨ이 탄로ᄒᆞ고 보국과 동방화촉을 ᄆᆡᆺ다","t":"하고 물러나와 보국을 불러 천자의 하교를 전하니, 보국이 크게 기뻐하여 엎드려 감사하고 부인과 온 집안 위아래가 다 기뻐하였다. 이때 천자께서 태사관을 불러 날을 받게 하시니 마침 봄 삼월 보름 무렵이었다. 천자께서 택일 단자와 예단 수백 필을 봉하여 위국공의 집으로 보내셨다. 이때 위국공이 택일 단자를 가지고 계월의 침소에 들어가 전하니 계월이 말했다. \"보국은 전에 중군으로서 여러 해 동안 수하로 부리던 사람인데, 내가 그 사람의 아내가 될 줄 어찌 알았겠습니까.","sp":[[8,10,"P","보국"],[15,17,"P","천자"],[28,30,"P","보국"],[49,51,"P","양부인"],[75,77,"P","천자"],[116,118,"P","천자"],[141,144,"P","홍무"],[159,162,"P","홍무"],[175,177,"P","홍계월"],[191,193,"P","홍계월"],[201,203,"P","보국"],[208,210,"P","보국"]]},{"c":5,"sub":"제 오 회: 계월이 녀ᄌᆞ의 본ᄉᆡᆨ이 탄로ᄒᆞ고 보국과 동방화촉을 ᄆᆡᆺ다","t":"다시는 그런 예를 쓰지 못할까 하니 이제 마지막으로 군례를 차리고자 합니다. 바라건대 부친께서는 이 뜻을 천자께 아뢰어 주십시오.\" 위국공이 곧 대궐에 들어가 천자께 아뢰니 천자께서 크게 웃으시고, 곧 군사 오천과 장수 백여 명에게 갑옷과 깃발을 갖추게 하여 원수에게 보내셨다. 이때 계월이 여자 옷을 벗고 갑옷과 투구를 갖추고 용봉 깃발과 황월과 수기를 잡고 행군하여 별궁에 자리 잡고 앉아, 군사를 시켜 보국에게 명령을 전하였다. 보국이 명령을 보고 분하기 그지없었으나 전에 평국의 위풍을 보았던지라,","sp":[[59,61,"P","천자"],[74,77,"P","홍무"],[89,91,"P","천자"],[97,99,"P","천자"],[145,147,"P","홍계월"],[159,161,"P","홍계월"],[228,230,"P","보국"],[243,245,"P","보국"],[268,270,"P","홍계월"]]},{"c":5,"sub":"제 오 회: 계월이 녀ᄌᆞ의 본ᄉᆡᆨ이 탄로ᄒᆞ고 보국과 동방화촉을 ᄆᆡᆺ다","t":"군령을 거역하지 못하고 갑옷과 투구를 갖추고 군문에 대령하였다. 이때 원수가 좌우를 돌아보며 말했다. \"중군이 어찌 이다지도 거만하냐. 어서 나와 뵈어라.\" 호령이 가을 서리 같으니 군졸들의 대답 소리에 장안이 끓는 듯하였다. 중군이 그 위풍에 겁을 먹고 갑옷을 끌며 몸을 굽혀 들어오는데 얼굴에 땀이 흘렀다. 급히 나아가 장대 앞에 엎드리니 원수가 정색하고 꾸짖었다. \"군법이 지극히 엄중하거늘, 중군이 되었으면 곧 대령하였다가 명령이 내리기를 기다려야 할 것인데, 장수의 명령을 중히 여기지 않고 태만한 마음을 품어 군령을 업신여기니 중군의 죄는 매우 무엄하다.","sp":[[39,41,"P","홍계월"],[58,60,"P","보국"],[127,129,"P","보국"],[192,194,"P","홍계월"],[223,225,"P","보국"],[301,303,"P","보국"]]},{"c":5,"sub":"제 오 회: 계월이 녀ᄌᆞ의 본ᄉᆡᆨ이 탄로ᄒᆞ고 보국과 동방화촉을 ᄆᆡᆺ다","t":"곧 군법으로 다스릴 것이나 십분 참작하거니와 그냥 두지는 못하겠다.\" 하고 군사에게 \"중군을 빨리 잡아내라.\" 호령하니 그 소리가 가을 서리 같았다. 무사들이 한꺼번에 함성을 지르며 달려들어 장대 앞에 꿇리니, 중군이 정신을 잃었다가 겨우 진정하여 아뢰었다. \"소장이 몸에 병이 있어 치료하다가 미처 대령하지 못하였습니다. 태만한 죄를 생각하면 만 번 죽어도 아깝지 않으나, 병든 몸이 무거운 매를 맞으면 목숨을 보전하지 못할 것이요, 만일 죽으면 부모에게 불효를 면치 못할 것입니다. 바라건대 원수께서는 강과 바다 같은 은덕을 내리시어 지난날의 정을 생각하시고 살려 주시면 불효를 면할까 합니다.\"","sp":[[48,50,"P","보국"],[118,120,"P","보국"],[277,279,"P","홍계월"]]},{"c":5,"sub":"제 오 회: 계월이 녀ᄌᆞ의 본ᄉᆡᆨ이 탄로ᄒᆞ고 보국과 동방화촉을 ᄆᆡᆺ다","t":"하며 수없이 애걸하니 원수가 속으로는 우스웠으나 겉으로는 호령하였다. \"중군이 몸에 병이 있다면서 어찌 영춘각에서 애첩 영춘과 밤낮으로 풍류를 즐기느냐. 그러나 사사로운 정이 없지 않아 용서하거니와 이후로는 그러지 마라.\" 하고 분부하니 보국이 백 번 절하여 사례하고 물러났다. 원수가 이렇게 종일 즐기다가 군사를 물리고 본궁으로 돌아오니, 보국은 원수에게 하직하고 돌아와 부모 앞에서 욕본 사연을 낱낱이 아뢰었다. 여공이 그 말을 듣고 크게 웃으며 칭찬하였다. \"내 며느리는 천고의 영웅 군자로다.\" 하고 보국에게 말했다. \"계월이 너를 욕보인 것은 다름이 아니라,","sp":[[12,14,"P","홍계월"],[40,42,"P","보국"],[58,60,"P","영춘"],[64,69,"P","영춘"],[133,135,"P","보국"],[156,158,"P","홍계월"],[191,193,"P","보국"],[195,197,"P","홍계월"],[233,235,"P","여공"],[284,286,"P","보국"],[295,297,"P","홍계월"]]},{"c":5,"sub":"제 오 회: 계월이 녀ᄌᆞ의 본ᄉᆡᆨ이 탄로ᄒᆞ고 보국과 동방화촉을 ᄆᆡᆺ다","t":"어명으로 배필을 정하시니 전에 중군으로 부리던 터라 다시는 부리지 못할까 하여 희롱한 것이니, 너는 조금도 허물하지 마라.\" 이때 천자께서 계월이 보국을 욕보였다는 말을 들으시고 상을 많이 내리셨다. 이윽고 전안(奠雁) 길일이 되어 위의를 갖추어 예식을 치르는데, 계월이 초록 저고리에 붉은 치마로 단장하고 시비들이 좌우에서 부축하여 나오는 거동이 엄숙하여 비녀 꽂은 장부였다. 아름다운 태도와 곱고 단정한 모습은 당대의 으뜸이었다. 또 장막 밖에는 여러 장수와 군졸이 갑옷과 투구를 갖추고 깃발과 창검을 좌우로 갈라 세워 호위하니 그 위의가 엄숙함을 헤아릴 수 없었다. 이때 보국도 위의를 갖추고 금 안장 얹은 준마에 두렷이 앉아 봉미선(鳳尾扇)으로 얼굴을 가리고 계월궁으로 들어와 전안하고 맞절하는 거동은,","sp":[[17,19,"P","보국"],[73,75,"P","천자"],[78,80,"P","홍계월"],[82,84,"P","보국"],[148,150,"P","홍계월"],[323,325,"P","보국"],[373,375,"P","홍계월"]]},{"c":5,"sub":"제 오 회: 계월이 녀ᄌᆞ의 본ᄉᆡᆨ이 탄로ᄒᆞ고 보국과 동방화촉을 ᄆᆡᆺ다","t":"하늘의 선관과 선녀가 반도(蟠桃)를 올리는 모습 같았다. 맞절을 마치고 날이 저물자 신랑이 촛불을 들고 침소에 이르니, 시녀들이 화촉을 받들고 들어갔다. 한 선녀가 붉은 치마 푸른 저고리 차림으로 일어나 맞으니, 두 신인이 촛불 아래 마주 앉으매 신랑의 풍채와 신부의 용모가 해와 달처럼 서로 빛을 다투었다. 보국이 얼굴 가득 봄바람을 띠고 한참 뒤 몸을 굽혀 두 손을 모으고 말했다. \"전날 대원수의 지위에 높이 앉아 보국을 애매한 죄로 얽어 꿇릴 때 오늘이 있을 줄 뜻하였겠소?\" 신부가 쪽 찐 머리를 숙이고 웃기만 하고 대답하지 않으니, 보국이 나아가 촛불을 끄고 옥 같은 손을 이끌어 비단 휘장 안으로 들어가 함께 잠자리에 드니 원앙과 비취새 같은 즐거움이 지극하였다.","sp":[[8,10,"P","선녀"],[88,90,"P","선녀"],[173,175,"P","보국"],[221,223,"P","홍계월"],[235,237,"P","보국"],[304,306,"P","보국"]]},{"c":5,"sub":"제 오 회: 계월이 녀ᄌᆞ의 본ᄉᆡᆨ이 탄로ᄒᆞ고 보국과 동방화촉을 ᄆᆡᆺ다","t":"이렇게 밤을 지내고 이튿날 해 뜰 무렵 두 사람이 위국공과 정렬부인에게 뵈니 위국공 부부가 기쁨을 이기지 못하였다. 또 기주후와 공렬부인에게 뵈니 기주후가 크게 기뻐하며 말했다. \"세상일은 참으로 헤아릴 수 없구나. 너를 내 며느리로 삼을 줄 어찌 알았겠느냐.\" 계월이 다시 절하고 말했다. \"소부의 죽을 목숨을 구해 주신 은혜와 십삼 년을 길러 주셨는데도 근본을 아뢰지 않은 죄는 만 번 죽어도 아깝지 않습니다. 또 하늘이 도우시어 시부모로 섬기게 하시니 이는 소녀의 소원입니다.\" 하고 종일 모시고 이야기하다가 하직하고 본궁으로 돌아오는데, 금덩을 타고 호위를 받으며 중문을 나서다가 눈을 들어 영춘각을 바라보니 애첩 영춘이 난간에 걸터앉아 있었다.","sp":[[28,31,"P","홍무"],[33,37,"P","양부인"],[43,46,"P","홍무"],[67,70,"P","여공"],[72,76,"P","공렬부인"],[82,85,"P","여공"],[147,149,"P","홍계월"],[335,337,"P","영춘"],[345,350,"P","영춘"]]},{"c":5,"sub":"제 오 회: 계월이 녀ᄌᆞ의 본ᄉᆡᆨ이 탄로ᄒᆞ고 보국과 동방화촉을 ᄆᆡᆺ다","t":"계월이 크게 노하여 덩을 멈추고 무사에게 호령하여 영춘을 끌어내려 덩 앞에 꿇리고 호령하였다. \"네가 중군의 세력을 믿고 교만 방자하여 내 행차를 보고도 감히 난간에 높이 걸터앉아 움직이지 않으니, 중군의 힘만 믿고 이같이 교만한 너 같은 요망한 년을 어찌 살려 두겠느냐. 마땅히 군법을 세우리라.\" 하고 무사에게 호령하여 문 밖에 내어 베라 하였다. 무사들이 명을 듣고 달려들어 영춘을 끌어내려 베니, 군졸과 시비들이 겁에 질려 바로 보지 못하였다.","sp":[[0,2,"P","홍계월"],[28,30,"P","영춘"],[57,59,"P","보국"],[111,113,"P","보국"],[213,215,"P","영춘"]]},{"c":5,"sub":"제 오 회: 계월이 녀ᄌᆞ의 본ᄉᆡᆨ이 탄로ᄒᆞ고 보국과 동방화촉을 ᄆᆡᆺ다","t":"이때 보국은 영춘을 죽였다는 말을 듣고 분한 마음을 이기지 못하여 부모에게 여쭈었다. \"계월이 전에는 대원수가 되어 소자를 중군으로 부렸으니 장막 안의 일이라 업신여기지 못하였거니와, 지금은 소자의 아내인데 소자가 사랑하는 영춘을 애매하게 죽여 마음을 불편하게 할 수 있습니까?\" 여공이 이 말을 듣고 말리며 말했다. \"계월이 비록 네 아내가 되었으나 벼슬이 그대로 있어 놓지 않았고 의기가 당당하여 족히 너를 부릴 사람인데도 예로써 너를 섬기니 어찌 그 마음을 그르다 하겠느냐.","sp":[[3,5,"P","보국"],[7,9,"P","영춘"],[49,51,"P","홍계월"],[58,60,"P","홍계월"],[69,71,"P","보국"],[125,127,"P","영춘"],[157,159,"P","여공"],[179,181,"P","홍계월"]]},{"c":5,"sub":"제 오 회: 계월이 녀ᄌᆞ의 본ᄉᆡᆨ이 탄로ᄒᆞ고 보국과 동방화촉을 ᄆᆡᆺ다","t":"또 영춘이 네 첩이라 하여 제 스스로 교만하다가 죽었으니 누구를 원망하겠느냐. 또 계월이 설령 궁에서 궁비를 잘못 죽였다 한들 누가 그르다 하겠느냐. 너는 조금도 개의치 말고 마음을 변하지 마라. 만일 영춘을 죽였다 하여 꺼리는 마음을 두면 부부의 의리도 변할 것이요, 또 천자께서 주장하신 혼인이라 네게 해로운 일이 있을 것이니 부디 조심하라.\" 보국이 여쭈었다. \"부친께서는 부당한 말씀을 하십니다. 세상에 대장부가 되어 계집의 괄시를 당하겠습니까?\" 하고 그 뒤로는 계월의 방에 들지 않았다. 계월이 생각하기를 '영춘 일로 꺼려서 오지 않는구나. [?]","sp":[[2,4,"P","영춘"],[46,48,"P","홍계월"],[113,115,"P","영춘"],[153,155,"P","천자"],[195,197,"P","보국"],[264,266,"P","홍계월"],[279,281,"P","홍계월"],[290,292,"P","영춘"]]},{"c":5,"sub":"제 오 회: 계월이 녀ᄌᆞ의 본ᄉᆡᆨ이 탄로ᄒᆞ고 보국과 동방화촉을 ᄆᆡᆺ다","t":"누가 보국을 남자라 하겠는가. 여자에도 미치지 못하는구나.' 하고 남자로 태어나지 못한 것을 분하게 여겨 눈물을 흘리며 세월을 보냈다. 한편 이때 남관장이 장계를 올리니 천자께서 급히 뜯어 보셨다. \"오왕과 초왕이 반역하여 지금 장안을 침범하려 합니다. 오왕은 구덕지를 얻어 대원수로 삼고 초왕은 장맹길을 얻어 선봉으로 삼아 장수 천여 명과 군사 십만을 거느리고 호주 북쪽 땅 십여 성의 항복을 받고 형주 자사 완태를 베고 짓쳐 오니, 소장의 힘으로는 막을 길이 없어 감히 아룁니다. 바라건대 황상께서는 어진 명장을 보내어 막으십시오.\"","sp":[[3,5,"P","보국"],[95,97,"P","천자"],[112,114,"P","여공"],[116,118,"P","홍무"],[142,144,"P","여공"],[146,149,"P","구덕지"],[155,157,"P","홍계월"],[162,164,"P","홍무"],[166,169,"P","맹길"],[276,278,"P","천자"]]},{"c":5,"sub":"제 오 회: 계월이 녀ᄌᆞ의 본ᄉᆡᆨ이 탄로ᄒᆞ고 보국과 동방화촉을 ᄆᆡᆺ다","t":"천자께서 보시고 크게 놀라시어 조정 신하들을 모아 의논하시니, 우승상 정연태가 아뢰었다. \"이 도적은 좌승상 평국을 보내어 막아야 할 것이니 급히 부르십시오.\" 천자께서 들으시고 한참 있다가 말씀하셨다. \"평국이 전에는 세상에 나와 있었기에 불러 나랏일을 의논하였거니와, 지금은 규중의 여자이니 어찌 불러서 싸움터에 보내겠는가.\" 여러 신하가 아뢰었다. \"평국이 지금 규중에 있으나 이름이 조정과 민간에 알려져 있고 또한 벼슬과 녹봉이 그대로 있으니 어찌 꺼리겠습니까.\"","sp":[[0,2,"P","천자"],[35,38,"P","정연태"],[39,42,"P","정연태"],[57,60,"P","보국"],[61,63,"P","홍계월"],[90,92,"P","천자"],[115,117,"P","홍계월"],[199,201,"P","홍계월"]]},{"c":5,"sub":"제 오 회: 계월이 녀ᄌᆞ의 본ᄉᆡᆨ이 탄로ᄒᆞ고 보국과 동방화촉을 ᄆᆡᆺ다","t":"천자께서 마지못하여 급히 평국을 부르셨다. 이때 평국은 규중에 홀로 있으면서 날마다 시비를 데리고 장기와 바둑으로 세월을 보내고 있었는데, 사관이 나와 부르신다는 명을 전하였다. 평국이 크게 놀라 급히 여자 옷을 벗고 조복을 입고 사관을 따라 탑전에 엎드리니, 천자께서 크게 기뻐하며 말씀하셨다. \"경이 규중에 있는 까닭에 오래 보지 못하여 밤낮으로 그리워하였는데, 이제 경을 보니 기쁘기 그지없도다. 짐이 덕이 없어 지금 오와 초 두 나라가 반역하여 호주 북쪽 땅의 항복을 받고 남관을 흩뜨려 황성을 침범하려 한다 하니, 경은 스스로 나서서 사직을 보전하게 하라.\" 평국이 엎드려 아뢰었다. \"신첩이 외람되이 폐하를 속이고 공후의 작록을 받아 영화롭게 지내 온 것이 황공한데, 죄를 용서하시고 이토록 아껴 주시니 신첩이 비록 어리석으나 힘을 다해 폐하의 성은을 만분의 일이라도 갚을까 하니 근심하지 마십시오.\" 하였다.","sp":[[0,2,"P","천자"],[14,16,"P","홍계월"],[27,29,"P","홍계월"],[100,102,"P","홍계월"],[146,148,"P","천자"],[318,320,"P","홍계월"],[342,344,"P","천자"],[419,421,"P","천자"]]},{"c":6,"sub":"뎨 륙 회: 양원슈가 군ᄉᆞ를 거나려 역젹을 치고 젹쟝 ᄆᆡᆼ길이 황셩을 범ᄒᆞ다가 사로잡히다","t":"한편 천자께서 크게 기뻐하시어 곧 천 명의 군사와 만 필의 말을 징발하여 상림원에 진을 치니, 원수가 친히 붓을 잡아 보국에게 명령을 전하였다. \"지금 적병이 급하니 중군은 어서 대령하여 군령을 어기지 마라.\" 보국이 명령의 사연을 보고 분함을 이기지 못하여 부모에게 여쭈었다. \"계월이 또 소자를 중군으로 부리려 하니 이런 일이 어디 있습니까?\" 여공이 말했다. \"내가 전에 너에게 무어라 이르더냐. 계월을 괄시하다가 이런 일을 당하니 어찌 그르다 하겠느냐.","sp":[[3,5,"P","천자"],[53,55,"P","홍계월"],[66,68,"P","보국"],[93,95,"P","보국"],[118,120,"P","보국"],[157,159,"P","홍계월"],[167,169,"P","보국"],[195,197,"P","여공"],[225,227,"P","홍계월"]]},{"c":6,"sub":"뎨 륙 회: 양원슈가 군ᄉᆞ를 거나려 역젹을 치고 젹쟝 ᄆᆡᆼ길이 황셩을 범ᄒᆞ다가 사로잡히다","t":"나랏일이 지극히 중하니 어쩔 수 없다.\" 하고 어서 가라고 재촉하였다. 보국이 하는 수 없어 갑옷과 투구를 갖추고 진문에 나아가 원수 앞에 엎드리니 원수가 분부하였다. \"만일 명령을 거역하는 자가 있으면 군법으로 다스리겠다.\" 보국이 겁을 먹고 중군 처소로 돌아와 명령이 내리기를 기다렸다. 원수가 여러 장수에게 각각 소임을 정하고 가을 구월 갑자일에 행군하여 십일월 초하루에 남관에 이르러 사흘 동안 진을 치고 머물렀다. 곧 떠나 닷새 만에 천축산을 지나 영정루에 이르니, 적병이 넓은 들판에 진을 쳤는데 굳기가 철통같았다.","sp":[[40,42,"P","보국"],[72,74,"P","홍계월"],[83,85,"P","홍계월"],[127,129,"P","보국"],[137,139,"P","보국"],[163,165,"P","홍계월"]]},{"c":6,"sub":"뎨 륙 회: 양원슈가 군ᄉᆞ를 거나려 역젹을 치고 젹쟝 ᄆᆡᆼ길이 황셩을 범ᄒᆞ다가 사로잡히다","t":"원수가 적진을 마주하여 진을 치고 호령하였다. \"장수의 명령을 어기는 자는 세워 둔 채 베겠다.\" 호령이 가을 서리 같으니 여러 장수와 군졸이 겁에 질려 어찌할 줄 몰랐고, 보국도 몹시 조심하였다. 이튿날 원수가 중군에게 분부하였다. \"오늘은 중군이 나가 싸우라.\" 중군이 명을 받고 말에 올라 석 자 장검을 들고 적진을 가리키며 외쳤다. \"나는 명나라 중군장 보국이다. 대원수의 명을 받아 너희 머리를 베려 하니 어서 나와 내 칼을 받아라.\" 적장 운평이 그 소리를 듣고 크게 노하여 말을 몰아 달려들었다.","sp":[[0,2,"P","홍계월"],[97,99,"P","보국"],[115,117,"P","홍계월"],[119,121,"P","보국"],[136,138,"P","보국"],[149,151,"P","보국"],[198,201,"P","보국"],[202,204,"P","보국"],[209,211,"P","홍계월"],[252,254,"P","운평"]]},{"c":6,"sub":"뎨 륙 회: 양원슈가 군ᄉᆞ를 거나려 역젹을 치고 젹쟝 ᄆᆡᆼ길이 황셩을 범ᄒᆞ다가 사로잡히다","t":"보국이 기세등등하여 장검을 들고 서로 싸우는데, 몇 합이 못 되어 보국이 칼을 날려 운평의 칼 든 팔을 베니 운평이 다급하여 말 아래로 떨어졌다. 보국이 운평의 머리를 베어 들고 본진으로 돌아오는데, 적장 구덕지가 크게 노하여 장검을 높이 들고 말을 몰아 크게 함성을 지르며 달려들었다. 어디서 났는지 모를 적병이 사방에서 달려들므로 보국이 겁에 질려 피하려 하였으나, 순식간에 적장이 함성을 지르며 보국을 천여 겹으로 에워싸고 짓쳐 왔다.","sp":[[0,2,"P","보국"],[37,39,"P","보국"],[47,49,"P","운평"],[61,63,"P","운평"],[82,84,"P","보국"],[86,88,"P","운평"],[115,118,"P","구덕지"],[187,189,"P","보국"],[224,226,"P","보국"]]},{"c":6,"sub":"뎨 륙 회: 양원슈가 군ᄉᆞ를 거나려 역젹을 치고 젹쟝 ᄆᆡᆼ길이 황셩을 범ᄒᆞ다가 사로잡히다","t":"위급해지자 보국이 하늘을 우러러 탄식하였다. 이때 원수가 급한 것을 보고 급히 말을 몰아 장검을 날리며 적진을 이리저리 치고 들어, 동쪽에 번뜩 서쪽 장수를 베고 남쪽에 번뜩 북쪽 장수를 베며 본진으로 돌아왔다. 보국을 구하면서 적장 오십여 명을 단칼에 없앴다. 이때 보국이 원수 보기를 부끄러워하니 원수가 보국을 꾸짖었다. \"저러고서 평소에 남자라 하며 나를 업신여겼는데 이제도 그리하겠는가.\" 하며 한없이 조롱하였다.","sp":[[6,8,"P","보국"],[28,30,"P","홍계월"],[119,121,"P","보국"],[150,152,"P","보국"],[154,156,"P","홍계월"],[168,170,"P","홍계월"],[172,174,"P","보국"]]},{"c":6,"sub":"뎨 륙 회: 양원슈가 군ᄉᆞ를 거나려 역젹을 치고 젹쟝 ᄆᆡᆼ길이 황셩을 범ᄒᆞ다가 사로잡히다","t":"이때 원수가 장대에 자리 잡고 앉아 구덕지의 머리를 함에 봉하여 황성으로 보냈다. 이때 오왕과 초왕 두 왕이 서로 의논하였다. \"평국의 용맹을 보니 옛날 조자룡(趙子龍)이라도 당하지 못할 것이다. 어찌 대적하겠으며, 명장 구덕지를 잃었으니 누구와 더불어 큰일을 도모하겠는가. 이제는 우리 두 나라가 평국의 손에 망하겠구나.\" 하며 눈물을 흘리니 맹길이 말했다. \"대왕은 염려하지 마십시오. 소장에게 묘책이 하나 있습니다. 평국이 아무리 영웅이라도 이 계교는 어찌할 줄 모를 것입니다. 평국이 모르게 군사를 거느리고 오초령을 넘어 양자강을 지나 바로 황성을 기습하면 천자가 반드시 황성을 버리고 항서를 올릴 것이니 그리하십시다.\" 하고 곧 관평을 불러 말했다. \"그대는 본진을 지키고, 평국이 아무리 싸우자고","sp":[[3,5,"P","홍계월"],[20,23,"P","구덕지"],[49,51,"P","여공"],[53,55,"P","홍무"],[72,74,"P","홍계월"],[124,127,"P","구덕지"],[167,169,"P","홍계월"],[193,195,"P","맹길"],[203,205,"P","서달"],[236,238,"P","홍계월"],[271,273,"P","홍계월"],[316,318,"P","천자"],[357,359,"P","관평"],[383,385,"P","홍계월"]]},{"c":6,"sub":"뎨 륙 회: 양원슈가 군ᄉᆞ를 거나려 역젹을 치고 젹쟝 ᄆᆡᆼ길이 황셩을 범ᄒᆞ다가 사로잡히다","t":"하여도 나가지 말고 내가 돌아오기를 기다려라.\" 하고 이날 밤 삼경에 장수 백여 명과 군사 일천 명을 거느리고 황성으로 갔다. 이때 천자께서 구덕지의 머리를 받아 보시고 크게 기뻐하시어 신하들을 모아 평국 부부를 칭찬하시고 태평하게 지내셨다. 그런데 이때 오호동 관수가 장계를 올렸다. \"양자강 사장에 천 명의 군사와 만 필의 말이 들어오며 황성을 침범하려 합니다.\" 천자께서 크게 놀라시어 조정 신하들을 모아 의논하시는데, 적장 맹길이 동문을 쳐부수고 들어와 백성을 무수히 죽이고 대궐에 불을 질러 불빛이 하늘을 찌르니, 장안의 모든 백성이 물 끓듯 하며 도망하였다.","sp":[[74,76,"P","천자"],[79,82,"P","구덕지"],[112,114,"P","홍계월"],[206,208,"P","천자"],[241,243,"P","맹길"]]},{"c":6,"sub":"뎨 륙 회: 양원슈가 군ᄉᆞ를 거나려 역젹을 치고 젹쟝 ᄆᆡᆼ길이 황셩을 범ᄒᆞ다가 사로잡히다","t":"천자께서 크게 놀라고 겁에 질려 용상을 두드리다가 기절하시니, 우승상 정현태가 천자를 등에 업고 북문을 열고 도망하였다. 모시는 신하 백여 명이 따라 천태령을 넘어가는데, 적장 맹길이 천자가 도망하는 것을 보고 크게 외쳤다. \"명나라 황제는 달아나지 말고 항복하라.\" 하며 쫓아오니 신하들도 넋을 잃고 죽기로 달아났다. 그런데 앞에 큰 강이 가로막고 있으므로 천자께서 하늘을 우러러 탄식하셨다. \"이제는 죽겠구나. 앞에는 큰 강이요 뒤에는 적병이 급하니 이 일을 어찌하겠는가.\"","sp":[[0,2,"P","천자"],[35,38,"P","정연태"],[39,42,"P","정연태"],[44,46,"P","천자"],[99,101,"P","맹길"],[103,105,"P","천자"],[201,203,"P","천자"]]},{"c":6,"sub":"뎨 륙 회: 양원슈가 군ᄉᆞ를 거나려 역젹을 치고 젹쟝 ᄆᆡᆼ길이 황셩을 범ᄒᆞ다가 사로잡히다","t":"하시며 자결하려 하시는데, 맹길이 벌써 달려들어 창으로 천자를 겨누며 말했다. \"죽기가 아깝거든 어서 항서를 올려라.\" 신하들이 애걸하였다. \"종이와 붓이 없으니 성안에 들어가 항서를 써서 올릴 것이니 장군은 우리 황상을 해치지 마십시오.\" 맹길이 눈을 부릅뜨고 꾸짖었다. \"너희 왕이 목숨이 아깝거든 손가락을 깨물고 옷자락을 뜯어 항서를 올려라.\" 천자께서 혼비백산하여 용포 소매를 뜯고 손가락을 입에 물고 하늘을 우러러 통곡하셨다. \"수백 년 사직이 내게 와서 망할 줄 어찌 알았겠는가.\"","sp":[[15,17,"P","맹길"],[31,33,"P","천자"],[120,122,"P","천자"],[135,137,"P","맹길"],[196,198,"P","천자"]]},{"c":6,"sub":"뎨 륙 회: 양원슈가 군ᄉᆞ를 거나려 역젹을 치고 젹쟝 ᄆᆡᆼ길이 황셩을 범ᄒᆞ다가 사로잡히다","t":"하시며 크게 통곡하시니 밝은 해가 빛을 잃고 초목이 빛을 잃었다. 이때 원수는 진중에서 적진을 깨뜨릴 묘책을 궁리하다가 저절로 마음이 산란하여 창밖에 나가 천문을 살펴보니, 자미성(紫微星)이 제자리를 떠나고 모든 별에 살기가 등등하여 은하수에 비치고 있었다. 원수가 크게 놀라 중군장을 불러 말했다. \"내가 천기를 살펴보니 천자의 위태로움이 경각에 달렸다. 내가 말 한 필로 가려 하니 장군은 여러 장수와 군졸을 거느리고 진문을 굳게 닫고 내가 돌아오기를 기다리라.\" 하고 곧 갑옷과 투구를 갖추고 말 한 필에 칼 한 자루로 길을 떠났는데, 동쪽 하늘이 밝아 왔다.","sp":[[40,42,"P","홍계월"],[145,147,"P","홍계월"],[155,158,"P","보국"],[181,183,"P","천자"]]},{"c":6,"sub":"뎨 륙 회: 양원슈가 군ᄉᆞ를 거나려 역젹을 치고 젹쟝 ᄆᆡᆼ길이 황셩을 범ᄒᆞ다가 사로잡히다","t":"바라보니 하룻밤 사이에 황성에 이르렀다. 성안에 들어가 보니 장안이 비었고 궁궐이 불타 빈터만 남아 있었다. 원수가 크게 놀라 크게 통곡하며 두루 다녔으나 한 사람도 없었다. 천자께서 가신 곳을 알지 못해 망극하기 그지없었는데, 문득 수채 구멍에서 한 노인이 나오다가 급히 도로 들어갔다. 원수가 급히 쫓아가며 말했다. \"나는 도적이 아니라 대국의 대원수 평국이니 놀라지 말고 나와 천자께서 계신 곳을 일러라.\" 그 노인이 그제야 도로 기어 나와 크게 통곡하였다.","sp":[[61,63,"P","홍계월"],[98,100,"P","천자"],[162,164,"P","홍계월"],[196,198,"P","홍계월"],[199,201,"P","홍계월"],[214,216,"P","천자"]]},{"c":6,"sub":"뎨 륙 회: 양원슈가 군ᄉᆞ를 거나려 역젹을 치고 젹쟝 ᄆᆡᆼ길이 황셩을 범ᄒᆞ다가 사로잡히다","t":"원수가 자세히 보니 기주후 여공이었다. 급히 말에서 내려 엎드려 통곡하였다. \"시아버님께서는 무슨 까닭으로 이 수채 구멍에 몸을 숨기고 계십니까? 소부의 부모와 시어머님은 어디로 피란하셨는지 아십니까?\" 여공이 원수의 옷을 붙들고 울며 말했다. \"뜻밖에 도적이 들어와 대궐에 불을 지르고 노략이 매우 심하니 장안의 모든 백성이 도망하여 갔다. 나는 갈 길을 몰라 이 구멍에 들어와 피란하였는데, 사돈 내외와 네 시어머니는 난리 때 간 곳을 알지 못하겠다.\" 하고 통곡하였다. [?]","sp":[[0,2,"P","홍계월"],[11,14,"P","여공"],[15,17,"P","여공"],[114,116,"P","여공"],[118,120,"P","홍계월"],[230,234,"P","공렬부인"]]},{"c":6,"sub":"뎨 륙 회: 양원슈가 군ᄉᆞ를 거나려 역젹을 치고 젹쟝 ᄆᆡᆼ길이 황셩을 범ᄒᆞ다가 사로잡히다","t":"원수가 위로하였다. \"설마 만나 뵐 날이 없겠습니까.\" 하고 또 물었다. \"황상께서는 어디 계십니까?\" 여공이 대답하였다. \"여기 숨어서 보니 한 신하가 천자를 업고 북문으로 도망하여 천태령을 넘어가는데, 그 뒤를 도적이 따라갔으니 반드시 위급하실 것이다.\" 원수가 크게 놀라 말했다. \"천자를 구하러 가니 소부가 돌아오기를 기다리십시오.\" 하고 말에 올라 천태령을 넘어가는데, 순식간에 한수 북산에 이르러 바라보니 십 리 모래밭에 적병이 산과 들을 뒤덮어 가득하고 \"항복하라!\" 하는 소리에 산천이 진동하였다.","sp":[[0,2,"P","홍계월"],[42,44,"P","천자"],[58,60,"P","여공"],[86,88,"P","천자"],[145,147,"P","홍계월"],[161,163,"P","천자"]]},{"c":6,"sub":"뎨 륙 회: 양원슈가 군ᄉᆞ를 거나려 역젹을 치고 젹쟝 ᄆᆡᆼ길이 황셩을 범ᄒᆞ다가 사로잡히다","t":"원수가 이 말을 듣고 머리털이 곤두서 크게 외쳤다. \"적장은 들어라. 우리 황상을 해치지 마라. 평국이 여기 왔노라.\" 맹길이 겁에 질려 말을 돌려 도망하니 원수가 크게 외쳤다. \"네가 가면 어디로 가겠느냐. 달아나지 말고 내 칼을 받아라.\" 하며 화살같이 달려가니, 원수의 준총마가 주홍 같은 입을 벌리고 순식간에 맹길이 탄 말의 꼬리를 물고 늘어졌다. 맹길이 크게 놀라 몸을 돌려 긴 창을 높이 들고 원수를 치려 하였다.","sp":[[0,2,"P","홍계월"],[42,44,"P","천자"],[54,56,"P","홍계월"],[67,69,"P","맹길"],[88,90,"P","홍계월"],[150,152,"P","홍계월"],[177,179,"P","맹길"],[199,201,"P","맹길"],[226,228,"P","홍계월"]]},{"c":6,"sub":"뎨 륙 회: 양원슈가 군ᄉᆞ를 거나려 역젹을 치고 젹쟝 ᄆᆡᆼ길이 황셩을 범ᄒᆞ다가 사로잡히다","t":"원수가 크게 노하여 칼을 들어 맹길을 치니 두 팔이 떨어졌다. 곧 사로잡고, 또 이리저리 치고 들어 적진의 장졸을 모두 없애니 흐르는 피가 바다 같고 주검이 산 같았다. 이때 천자께서는 신하들과 함께 넋을 잃고 어찌할 줄 모르다가 손가락을 깨물어 쓰려 하시는데, 원수가 급히 말에서 내려 엎드려 통곡하며 아뢰었다. \"폐하께서는 옥체를 보전하십시오. 평국이 왔습니다.\" 천자께서 정신이 혼미한 가운데 평국이라는 말을 들으시고 한편 반기며 한편 슬퍼하시어 원수의 손을 잡고 눈물을 흘리며 말씀을 잇지 못하셨다.","sp":[[0,2,"P","홍계월"],[17,19,"P","맹길"],[98,100,"P","천자"],[147,149,"P","홍계월"],[177,179,"P","천자"],[195,197,"P","홍계월"],[206,208,"P","천자"],[223,225,"P","홍계월"],[253,255,"P","홍계월"]]},{"c":6,"sub":"뎨 륙 회: 양원슈가 군ᄉᆞ를 거나려 역젹을 치고 젹쟝 ᄆᆡᆼ길이 황셩을 범ᄒᆞ다가 사로잡히다","t":"원수가 황상의 옥체를 보호하니 이윽고 정신을 진정하시고 원수를 다시 보시며 사례하셨다. \"짐이 이제 막 외로운 넋이 될 것을 원수의 덕으로 사직을 다시 보전하게 되었으니 원수의 은혜를 무엇으로 다 갚겠는가. 강산을 반으로 나누어 주어도 부족하겠도다.\" 하시고 물으셨다. \"원수는 만 리 변방에서 어찌 알고 와서 구하였는가?\" 원수가 엎드려 아뢰었다. \"천기를 보고 군사를 중군에게 맡기고 밤낮으로 길을 재촉하여 황성에 이르니 장안이 비어 있고 폐하께서 계신 곳을 몰라 머뭇거리던 차에, 시아버지 여공이 수채 구멍에서 나오기에","sp":[[0,2,"P","홍계월"],[4,6,"P","천자"],[31,33,"P","홍계월"],[70,72,"P","홍계월"],[95,97,"P","홍계월"],[152,154,"P","홍계월"],[182,184,"P","홍계월"],[208,210,"P","보국"],[248,250,"P","천자"],[272,276,"P","여공"],[277,279,"P","여공"]]},{"c":6,"sub":"뎨 륙 회: 양원슈가 군ᄉᆞ를 거나려 역젹을 치고 젹쟝 ᄆᆡᆼ길이 황셩을 범ᄒᆞ다가 사로잡히다","t":"물어보고 급히 와서 적장 맹길을 사로잡고 나머지는 다 없앴습니다.\" 하며 대강 아뢰고 나왔다. 맹길이 타던 말은 원수가 타고, 행군북은 맹길의 등에 지우고, 신하들이 북을 울리며 만세를 부르고 호호탕탕하게 환궁하셨다. 이때 천자께서 말 위에서 용포 소매를 날리며 춤을 추시며 즐거워하시니, 신하들과 원수도 한꺼번에 팔을 들고 춤을 추며 만세를 부르고 즐기며 천태령을 넘어왔다. 그러나 장안은 소란하고 대궐은 터만 남았으니 어찌 한심하지 않겠는가.","sp":[[14,16,"P","맹길"],[53,55,"P","맹길"],[63,65,"P","홍계월"],[76,78,"P","맹길"],[125,127,"P","천자"],[167,169,"P","홍계월"]]},{"c":6,"sub":"뎨 륙 회: 양원슈가 군ᄉᆞ를 거나려 역젹을 치고 젹쟝 ᄆᆡᆼ길이 황셩을 범ᄒᆞ다가 사로잡히다","t":"천자께서 좌우를 돌아보며 말씀하셨다. \"짐이 덕이 없어 죄 없는 백성과 황후와 황태자가 불 속의 외로운 넋이 되었으니 무슨 면목으로 천자의 자리를 회복하여 차지하겠는가.\" 하시고 통곡하시니 원수가 여쭈었다. \"폐하께서는 너무 염려하지 마십시오. 하늘이 성상을 내실 때 저 무도한 도적으로 하여금 화를 당하게 하신 것이요, 둘째는 소신을 내어 화란을 평정하게 하신 것이니 하늘이 다 정하신 바라 어찌 하늘의 운수를 면하겠습니까. 슬픔을 참으시고 거처를 정하신 뒤에 황후와 태자의 행방을 알아보십시다.\" 천자께서 말씀하셨다. \"대궐이 빈터만 남았으니 어디에 자리를 잡겠는가.\"","sp":[[0,2,"P","천자"],[40,42,"P","황후"],[44,47,"P","태자"],[74,76,"P","천자"],[106,108,"P","홍계월"],[117,119,"P","천자"],[141,143,"P","천자"],[259,261,"P","황후"],[263,265,"P","태자"],[280,282,"P","천자"]]},{"c":6,"sub":"뎨 륙 회: 양원슈가 군ᄉᆞ를 거나려 역젹을 치고 젹쟝 ᄆᆡᆼ길이 황셩을 범ᄒᆞ다가 사로잡히다","t":"하시는데, 이때 여공이 수채 구멍에서 나와 천자께 엎드려 통곡하였다. \"소신이 살기만 도모하여 폐하를 모시지 못하였으니 소신을 속히 처형하시어 뒷사람을 징계하십시오.\" 천자께서 서글피 말씀하셨다. \"짐이 경 때문에 이번 변을 당한 것이 아니니 어찌 경의 죄라 하겠는가. 조금도 그런 말은 하지 마라.\" 여공이 또 아뢰었다. \"폐하께서 아직 머무르실 궁궐이 없으니 우선 종남산 원수의 집으로 돌아가심이 좋을까 합니다.\" 천자께서 그 말을 따르시어 곧 종남산 아래로 와서 보시니 외로운 집만 남아 있었다. 원수가 시자에게 명하여 방 하나를 쓸고 닦게 하고, 위국공이 쓰던 황화전에 자리하시게 하였다. 이튿날 해 뜰 무렵 원수가 아뢰었다. \"도적을 벨 무사가 없으니 폐하께서는 살펴 주십시오.\"","sp":[[9,11,"P","여공"],[24,26,"P","천자"],[53,55,"P","천자"],[94,96,"P","천자"],[169,171,"P","여공"],[182,184,"P","천자"],[210,212,"P","홍계월"],[234,236,"P","천자"],[281,283,"P","홍계월"],[310,313,"P","홍무"],[345,347,"P","홍계월"],[370,372,"P","천자"]]},{"c":6,"sub":"뎨 륙 회: 양원슈가 군ᄉᆞ를 거나려 역젹을 치고 젹쟝 ᄆᆡᆼ길이 황셩을 범ᄒᆞ다가 사로잡히다","t":"하고 자리를 차리고 대 위에 높이 앉아 무사에게 호령하였다. \"도적을 차례로 앉혀라.\" 원수가 석 자 장검을 들어 적졸을 다 벤 뒤에 칼을 비껴들고 천자 앞에 아뢰었다. \"저 도적은 소신과 하늘을 함께 이고 살 수 없는 원수입니다. 죄목을 기록할 것이니 살펴 주십시오.\" 하고 원수가 급히 자리에 앉아 맹길을 결박하여 가까이 꿇리고 소리를 높여 크게 꾸짖었다. \"네가 초나라 땅에 산다 하니 그 지명을 자세히 일러라.\" 맹길이 아뢰었다. \"본래 사는 곳은 소상강 근처입니다.\" 원수가 말했다. \"네가 수적이 되어 강 위를 다니며 장삿배를 빼앗아 먹었느냐?\" 맹길이 아뢰었다. \"과연 흉년을 당하여 굶주림을 견디지 못해 도적 무리를 데리고 수적이 되어 사람을 죽이고 재물을 빼앗아 먹었습니다.\" 원수가 또 물었다. \"그러함이 분명하면,","sp":[[49,51,"P","홍계월"],[83,85,"P","천자"],[123,125,"P","홍계월"],[155,157,"P","홍계월"],[169,171,"P","맹길"],[235,237,"P","맹길"],[267,269,"P","홍계월"],[312,314,"P","맹길"],[388,390,"P","홍계월"]]},{"c":6,"sub":"뎨 륙 회: 양원슈가 군ᄉᆞ를 거나려 역젹을 치고 젹쟝 ᄆᆡᆼ길이 황셩을 범ᄒᆞ다가 사로잡히다","t":"아무 해에 엄자릉의 조대에서 홍시랑 부인을 비단으로 묶고 그 품에 안은 어린아이를 자리에 싸서 강물에 넣은 일이 있느냐? 바로 말하라.\" 맹길이 그 말을 듣고 꿇어앉으며 말했다. \"이제는 죽게 되었으니 어찌 속이겠습니까. 과연 그런 일이 있습니다.\" 원수가 노기등등하여 소리 높여 크게 꾸짖었다. \"나는 다른 사람이 아니라 그때 자리에 싸서 물에 넣은 계월이다.\" 맹길이 그 말을 듣고 더욱 정신이 아득하였다.","sp":[[16,19,"P","홍무"],[20,22,"P","양부인"],[77,79,"P","맹길"],[140,142,"P","홍계월"],[197,199,"P","홍계월"],[204,206,"P","맹길"]]},{"c":6,"sub":"뎨 륙 회: 양원슈가 군ᄉᆞ를 거나려 역젹을 치고 젹쟝 ᄆᆡᆼ길이 황셩을 범ᄒᆞ다가 사로잡히다","t":"원수가 분기가 크게 일어 친히 내려가 맹길의 상투를 잡고 목을 묶어 나무에 매달고 \"너 같은 놈은 조각조각 오려 내리라.\" 하고 배를 갈라 간을 꺼내 하늘에 고하였다. 그리고 천자께 아뢰었다. \"폐하의 넓으신 덕택으로 평생 한마음에 맺혔던 소원을 다 풀었으니 이제 죽어도 한이 없습니다.\" 천자께서 사연을 들으시고 칭찬하셨다. \"이는 경의 충효에 하늘이 감동하신 것이다.\" 하시고 즐거워하셨다. 이때 천자께서 보국의 소식을 몰라 염려하시니,","sp":[[0,2,"P","홍계월"],[21,23,"P","맹길"],[98,100,"P","천자"],[109,111,"P","천자"],[162,164,"P","천자"],[224,226,"P","천자"],[229,231,"P","보국"]]},{"c":6,"sub":"뎨 륙 회: 양원슈가 군ᄉᆞ를 거나려 역젹을 치고 젹쟝 ᄆᆡᆼ길이 황셩을 범ᄒᆞ다가 사로잡히다","t":"원수가 아뢰었다. \"신이 보국을 데려오겠습니다.\" 하고 이날 떠나려 하는데 문득 중군이 장계를 올렸다. 천자께서 곧 뜯어 보시니 이렇게 쓰여 있었다. \"대명국 대사마 대장군 중군 신 보국은 황공하여 백 번 절하옵고 황상 탑하에 올립니다. 원수 평국이 황상을 구하러 가고 소신이 무거운 소임을 홀로 맡아 도적 칠 방략이 없었는데, 하늘이 돕고 신령이 도우시어 한 번 북을 쳐 오와 초 두 나라의 항복을 받았습니다.\"","sp":[[0,2,"P","홍계월"],[14,16,"P","보국"],[45,47,"P","보국"],[58,60,"P","천자"],[89,96,"P","보국"],[97,99,"P","보국"],[102,104,"P","보국"],[120,122,"P","천자"],[133,135,"P","홍계월"],[136,138,"P","홍계월"],[140,142,"P","천자"]]},{"c":7,"sub":"제 칠 회: 오쵸양왕을 사로잡아 졍법ᄒᆞ고 황후와 ᄐᆡᄌᆞ를 구ᄒᆞ야 황궁에 도라오다","t":"천자께서 다 읽으시고 원수를 돌아보며 말씀하셨다. \"이제 보국이 오와 초 두 왕을 사로잡았다 하니 나랏일에 이런 다행이 어디 있겠는가. 이런 소식을 듣고 짐이 어찌 앉아서만 있겠는가.\" 하시고 신하들을 거느리고 거둥하시어 평국을 선봉으로 삼고 천자께서 스스로 중군이 되어 좌우의 호위를 받으며 보국의 진을 향해 가셨다. 선봉장 평국은 갑옷과 투구를 갖추고 백총마를 타고 수기를 잡고 앞서 나아갔다. 이때 보국은 오와 초 두 왕을 잡아 앞세우고 승전고를 울리며 황성으로 향하였다. 여러 날 만에 황성 삼십 리 밖에 이르러 앞을 바라보니 한 장수가 모래밭으로 들어오고 있었다.","sp":[[0,2,"P","천자"],[12,14,"P","홍계월"],[32,34,"P","보국"],[124,126,"P","홍계월"],[136,138,"P","천자"],[145,147,"P","보국"],[164,166,"P","보국"],[183,185,"P","홍계월"],[226,228,"P","보국"]]},{"c":7,"sub":"제 칠 회: 오쵸양왕을 사로잡아 졍법ᄒᆞ고 황후와 ᄐᆡᄌᆞ를 구ᄒᆞ야 황궁에 도라오다","t":"보국이 살펴보니 수기와 칼빛은 원수의 칼과 수기인데 말은 준총마가 아니라 백총마였다. 보국은 온갖 의심이 들어 전군에 명을 내려 진을 치라 하고 생각하였다. '필시 적장 맹길의 복병이로구나. 우리 원수의 모양을 흉내 내어 나를 속여 꾀어내려는 것이다.' 하고 더욱 의심하여 어찌할 줄 몰랐다. 이때 천자께서 이 모습을 보시고 원수 평국을 불러 말씀하셨다. \"짐이 보국을 보니 원수를 보고 적장으로만 여겨 의심하는 모양이다. 원수는 거짓으로 적장인 척하여 중군을 속이고 오늘 재주를 시험하여 짐이 구경하게 하라.\" 원수가 웃으며 아뢰었다. \"폐하께서 이렇게 하교하시니 소신의 뜻과 같습니다. 이제 분부를 받들겠습니다.\" 하고 원수가 갑옷 위에 검은 군복을 껴입고,","sp":[[0,2,"P","보국"],[17,19,"P","홍계월"],[48,50,"P","보국"],[95,97,"P","맹길"],[110,112,"P","홍계월"],[167,169,"P","천자"],[182,184,"P","홍계월"],[185,187,"P","홍계월"],[203,205,"P","보국"],[210,212,"P","홍계월"],[237,239,"P","홍계월"],[254,256,"P","보국"],[287,289,"P","홍계월"],[302,304,"P","천자"],[349,351,"P","홍계월"]]},{"c":7,"sub":"제 칠 회: 오쵸양왕을 사로잡아 졍법ᄒᆞ고 황후와 ᄐᆡᄌᆞ를 구ᄒᆞ야 황궁에 도라오다","t":"모래밭에 나서며 수기를 높이 들고 말을 채찍질하여 보국의 진으로 거침없이 달려갔다. 이때 보국은 정말 적장인 줄 알고 갑옷을 입고 말에 올라 달려들었다. 평국이 예전에 곽도사에게 배운 술법을 쓰니 순식간에 큰바람이 일어나며 검은 구름과 안개가 자욱하여 지척을 분간할 수 없었다. 보국이 어찌할 줄 몰라 겁에 질려 허둥대는데, 평국이 대취타를 울리며 한꺼번에 달려들어 보국의 창을 빼앗아 들고 보국의 멱살을 잡아 공중에 들고 말을 채찍질하여 천자 계신 곳으로 갔다. 이때 보국이 숨을 쉬지 못하고 소리를 크게 하여 원수를 불렀다. \"평국은 어디 가서 보국이 죽는 줄 모르는가.\" 하며 우는 소리가 처량하니 진중이 요란하고 천지가 뒤집히는 듯하였다. 원수가 이 말을 듣고 웃으며 말했다. \"네가 어찌","sp":[[28,30,"P","보국"],[50,52,"P","보국"],[86,88,"P","홍계월"],[94,97,"P","곽도사"],[156,158,"P","보국"],[182,184,"P","홍계월"],[205,207,"P","보국"],[219,221,"P","보국"],[246,248,"P","천자"],[263,265,"P","보국"],[287,289,"P","홍계월"],[297,299,"P","홍계월"],[307,309,"P","보국"],[362,364,"P","홍계월"]]},{"c":7,"sub":"제 칠 회: 오쵸양왕을 사로잡아 졍법ᄒᆞ고 황후와 ᄐᆡᄌᆞ를 구ᄒᆞ야 황궁에 도라오다","t":"평국에게 달려오면서 평국을 또 무슨 일로 부르느냐?\" 하며 손뼉을 치고 크게 웃으니, 보국이 그 말을 듣고 정신을 차려 보니 과연 평국이 분명하였다. 평국을 보자 슬픈 마음은 간 데 없고 도리어 부끄러워 수치스러운 마음을 걷잡지 못하여 눈물을 거두었다. 이때 천자께서 보시고 크게 웃으시며 보국의 손을 잡고 말씀하셨다. \"중군은 오늘 원수에게 욕본 것을 조금도 개의치 마라. 이번에 원수가 제 뜻으로 한 것이 아니라 짐이 경들의 재주를 보려고 시킨 것이다. 지금은 싸움터라 욕을 보았으나 평정한 뒤 황성에 돌아가면 예로써 중군을 섬길 것이니 부부의 의를 상하지 마라.\" 하시고 보국을 위로하시니, 보국이 그제야 웃고 엎드려 아뢰었다. \"폐하의 하교가 지당하십니다.\" 그리고 천자를 모시고 황성으로 돌아가는데, 오와 초 두 왕의 등에 행군북을","sp":[[0,2,"P","홍계월"],[11,13,"P","홍계월"],[48,50,"P","보국"],[73,75,"P","홍계월"],[84,86,"P","홍계월"],[145,147,"P","천자"],[162,164,"P","보국"],[180,182,"P","보국"],[187,189,"P","홍계월"],[214,216,"P","홍계월"],[292,294,"P","보국"],[323,325,"P","보국"],[334,336,"P","보국"],[356,358,"P","천자"],[377,379,"P","천자"]]},{"c":7,"sub":"제 칠 회: 오쵸양왕을 사로잡아 졍법ᄒᆞ고 황후와 ᄐᆡᄌᆞ를 구ᄒᆞ야 황궁에 도라오다","t":"지우고 무사에게 북을 울리게 하며 넓은 들을 뒤덮고 별사곡을 지나 황성에 이르렀다. 종남산 아래에 이르러 천자께서 황화전에 자리하시고 무사에게 명하여 오와 초 두 왕을 결박하여 섬돌 아래 꿇리고 꾸짖으셨다. \"너희가 무엇이 부족하여 태평성대에 반역의 마음을 품고 임금을 속여 한 지방을 어지럽히고, 황성을 침범하여 백성을 어지럽히며 재물을 노략하였느냐. 하늘이 무심치 않으시어 너희를 잡아 왔으니 종묘사직에 다행이다. 너희를 다 죽여 국법을 바로 세우고 온 나라에 빛내리라. 너희는 원한을 품지 말고 사형을 받아라.\" 하시고 곧 무사에게 명하여 원문 밖에 내어 처형하라 하셨다. 그리고 천자께서 새로이 황후와 태자가 화재를 당한 일을 깊이 슬퍼하시어 그들을 위해 신위를 차리고 제문을 지어 제사 지내시니 조정의 모든 관원이 한꺼번에 통곡하였다.","sp":[[59,61,"P","천자"],[328,330,"P","천자"],[337,339,"P","황후"],[341,343,"P","태자"]]},{"c":7,"sub":"제 칠 회: 오쵸양왕을 사로잡아 졍법ᄒᆞ고 황후와 ᄐᆡᄌᆞ를 구ᄒᆞ야 황궁에 도라오다","t":"원수가 갖은 방법으로 옥체를 보호하여 천자께서 간신히 진정하셨다. 군사를 먹이고 위로한 뒤 여러 장수의 공을 차례로 적으시고, 새로 국호를 고쳐 즉위하시고 조서를 내려 만과를 보여 조정의 자리를 정하셨다. 보국을 좌승상으로 봉하시고 평국에게는 대사마 대장군 위왕의 직첩을 내리시고 못내 기뻐하셨다. 이때 평국이 여쭈었다. \"신첩이 외람되이 폐하의 넓으신 덕택으로 봉작을 입어 벼슬이 재상의 반열에 있고, 이제 천하를 평정하였으나 이는 다 폐하의 큰 업이 높고 성하신 덕과 강과 바다 같은 덕입니다.","sp":[[0,2,"P","홍계월"],[21,23,"P","천자"],[115,117,"P","보국"],[119,122,"P","보국"],[130,132,"P","홍계월"],[136,143,"P","보국"],[144,146,"P","홍계월"],[170,172,"P","홍계월"],[190,192,"P","천자"],[245,247,"P","천자"]]},{"c":7,"sub":"제 칠 회: 오쵸양왕을 사로잡아 졍법ᄒᆞ고 황후와 ᄐᆡᄌᆞ를 구ᄒᆞ야 황궁에 도라오다","t":"어찌 신첩의 공이라 하겠습니까. 하물며 친부모와 시부모를 잃었으니 신첩의 팔자가 기박하여 이러합니다. 이제는 여자의 도리를 차려 부모님 두 분의 자리를 지키고자 합니다.\" 하고 병부 열두 개와 대원수의 인수(印綬)와 수기를 바치며 울었다. 천자께서 슬퍼하시며 위로하셨다. \"이는 짐이 박복한 탓이니 경을 보기가 부끄럽도다. 그러나 위국공 부부와 공렬부인은 난리를 당해 어느 곳으로 피란하였을 것이니 소식이 있을 것이다. 경은 안심하라.\" 하시고 또 말씀하셨다. \"경이 규중에 있겠다 하며 병부와 인신을 다 바치니 다시는 자주 보지 못하겠도다. 경의 사정은 그러하나 임금과 신하의 의리를 잃지 말고 한 달에 한 번씩 조회하여 짐의 울적한 마음을 덜어 다오.\" 하시고 조정 신하에게 명하여 인신과 병부를 도로 [?]","sp":[[109,111,"P","홍계월"],[134,136,"P","천자"],[185,188,"P","홍무"],[193,197,"P","공렬부인"]]},{"c":7,"sub":"제 칠 회: 오쵸양왕을 사로잡아 졍법ᄒᆞ고 황후와 ᄐᆡᄌᆞ를 구ᄒᆞ야 황궁에 도라오다","t":"내어 주시며 말씀하셨다. \"이 병부와 인신은 하늘이 경에게 맡기신 것일 뿐 아니라 짐이 어찌 거두겠는가.\" 하시며 안심하라 하셨다. 평국이 이때를 당하여 어찌하겠는가. 머리를 조아려 엎드리고 인신을 도로 차고 보국과 함께 조정에서 물러나오니, 누가 그 위엄을 두려워하고 칭찬하지 않았겠는가. 평국이 돌아와 곧 여자 옷으로 갈아입고 그 위에 또 조복을 입고 여공에게 뵈니, 여공이 크게 기뻐하여 일어나 자리를 비켜 마주 앉았다. 원수는 마음에 미안하여 못내 몸 둘 바를 몰라 하였다.","sp":[[74,76,"P","홍계월"],[117,119,"P","보국"],[163,165,"P","홍계월"],[199,201,"P","여공"],[208,210,"P","여공"],[239,241,"P","홍계월"]]},{"c":7,"sub":"제 칠 회: 오쵸양왕을 사로잡아 졍법ᄒᆞ고 황후와 ᄐᆡᄌᆞ를 구ᄒᆞ야 황궁에 도라오다","t":"평국이 여공을 모시고 위국공 내외와 시어머니의 행방을 이야기하며, 필시 환란 때 피하지 못하였을 것이라 아뢰었다. 그리고 조정의 신하들을 다 청한 뒤 부모 두 분의 빈소와 시어머니의 빈소를 차리고 제수를 갖추고 제문을 지어 승상 보국과 함께 상복을 입고 발상하여 하늘을 부르며 통곡하니, 참석한 사람들이 차마 보지 못하였다. 날이 저물자 각각 집으로 돌아갔고, 그 뒤로는 예로써 여공을 섬기니 여공은 한편 기쁘고 한편 두려워하였다. 한편 이때 위국공은 피란하여 부인과 공렬부인과 춘낭과 양윤을 데리고 동쪽으로 가다가 한 물가에 이르렀는데, 여러 시녀가 황후와 황태자를 모시고 강가에 앉아 건너지 못하고 서로 붙들고 통곡하고 있었다.","sp":[[0,2,"P","홍계월"],[4,6,"P","여공"],[12,15,"P","홍무"],[20,24,"P","공렬부인"],[96,100,"P","공렬부인"],[125,130,"P","보국"],[212,214,"P","여공"],[220,222,"P","여공"],[248,251,"P","홍무"],[258,260,"P","양부인"],[262,266,"P","공렬부인"],[268,270,"P","춘낭"],[272,274,"P","양윤"],[309,311,"P","황후"],[313,316,"P","태자"]]},{"c":7,"sub":"제 칠 회: 오쵸양왕을 사로잡아 졍법ᄒᆞ고 황후와 ᄐᆡᄌᆞ를 구ᄒᆞ야 황궁에 도라오다","t":"위국공이 급히 나아가 엎드리니 황후와 태자가 보시고 못내 기뻐하며 눈물을 흘리셨다. 위국공이 위로하였다. \"이번 변란은 어찌할 수 없었으나 천자의 성덕이 크시니 어찌 하늘이 무심하겠습니까. 바라건대 황후 전하께서는 옥체를 보호하십시오.\" 그러는데 문득 남쪽에서 사람 소리가 들려 살펴보니, 앞에는 하늘에 닿을 듯한 큰 산이 있어 갈 곳이 없었다. 이에 위국공이 황후와 태자를 모시고 여러 부인과 시녀를 데리고 그 산으로 들어가니, 수많은 봉우리와 골짜기가 눈앞에 둘러 있고 난새와 봉황과 공작이 사방으로 오가며, 푸른 소나무와 대나무가 울창하여 지척의 동안도 분간할 수 없었다.","sp":[[0,3,"P","홍무"],[17,19,"P","황후"],[21,23,"P","태자"],[47,50,"P","홍무"],[78,80,"P","천자"],[111,113,"P","황후"],[197,200,"P","홍무"],[202,204,"P","황후"],[206,208,"P","태자"],[217,219,"P","양부인"]]},{"c":7,"sub":"제 칠 회: 오쵸양왕을 사로잡아 졍법ᄒᆞ고 황후와 ᄐᆡᄌᆞ를 구ᄒᆞ야 황궁에 도라오다","t":"험한 길을 걸어 들어가며 멀고 가까운 곳을 바라보니 솔숲 사이에 초당 하나가 보였다. 위국공이 몹시 다행으로 여겨 들어가 주인을 청하니, 한 도사가 초당에 앉아 있다가 위국공을 보고 급히 내려와 소매를 잡고 물었다. \"무슨 일로 이 깊은 산중에 들어오셨습니까?\" 위국공이 답례하고 탄식하였다. \"나라의 운수가 불행하여 뜻밖에 난리를 만나 황후와 태자를 모시고 피란하다가 이곳에 왔습니다.\" 도사가 놀라 물었다. \"어디 계십니까?\" 위국공이 대답하였다. \"황후와 여러 부인은 밖에 계십니다.\" 도사가 말했다. \"황후와 여러 부인은 안으로 모시고, 위국공과 태자는 초당에 머물러 계시다가 세상이 평정된 뒤에 황성으로 가시게 하십시오.\"","sp":[[48,51,"P","홍무"],[79,81,"P","곽도사"],[94,97,"P","홍무"],[147,150,"P","홍무"],[189,191,"P","황후"],[193,195,"P","태자"],[218,220,"P","곽도사"],[241,244,"P","홍무"],[254,256,"P","황후"],[261,263,"P","양부인"],[275,277,"P","곽도사"],[285,287,"P","황후"],[292,294,"P","양부인"],[305,308,"P","홍무"],[310,312,"P","태자"]]},{"c":7,"sub":"제 칠 회: 오쵸양왕을 사로잡아 졍법ᄒᆞ고 황후와 ᄐᆡᄌᆞ를 구ᄒᆞ야 황궁에 도라오다","t":"하니 위국공이 나와 황후와 여러 부인과 시녀는 안으로 모시고 태자와 위국공은 초당에 머물렀다. 밤낮으로 황성 소식을 알 길이 없어 서러워하였는데, 하루는 도사가 산 위에 올라 천기를 살펴보고 서글피 내려와 위국공에게 말했다. \"제가 오늘 천기를 살펴보니 이제는 평국과 보국이 도적을 없애고 본국에 돌아와 여공을 섬기며 상공과 부인의 영위를 차리고 밤낮 통곡으로 지냅니다. 황상께서는 황후와 황태자의 생사를 알지 못하시어 눈물로 지내시니 상공은 서둘러 나가십시오.\"","sp":[[3,6,"P","홍무"],[11,13,"P","황후"],[18,20,"P","양부인"],[34,36,"P","태자"],[38,41,"P","홍무"],[86,88,"P","곽도사"],[115,118,"P","홍무"],[146,148,"P","홍계월"],[150,152,"P","보국"],[170,172,"P","여공"],[182,184,"P","양부인"],[208,210,"P","천자"],[214,216,"P","황후"],[218,221,"P","태자"]]},{"c":7,"sub":"제 칠 회: 오쵸양왕을 사로잡아 졍법ᄒᆞ고 황후와 ᄐᆡᄌᆞ를 구ᄒᆞ야 황궁에 도라오다","t":"위국공이 놀라 말했다. \"제가 평국의 아비인 줄 어찌 아십니까?\" 도사가 말했다. \"저절로 알 만합니다.\" 하고 길을 재촉하며 \"봉서 한 통을 평국에게 전해 주십시오.\" 하였다. 위국공이 사례하였다. \"존공의 덕택으로 죽을 목숨을 건져 무사히 돌아가니 은혜는 잊기 어렵거니와, 이 땅의 지명은 무엇이라 합니까?\" 도사가 말했다. \"이 땅의 지명은 익주이고 산 이름은 천명산이라 하거니와, 저는 정처 없이 다니는 사람입니다. 산수를 구경하러 다니다가 황후와 상공을 구하려고 이 산중에 왔는데, 이제는 저도 함께 떠나 촉 땅의 명산으로 들어가려 합니다. 이후로는 다시 뵐 길이 없으니 섭섭하기 그지없으나 부디 조심하여 평안히 가십시오.\"","sp":[[0,3,"P","홍무"],[17,19,"P","홍계월"],[37,39,"P","곽도사"],[80,82,"P","홍계월"],[100,103,"P","홍무"],[175,177,"P","곽도사"],[251,253,"P","황후"]]},{"c":7,"sub":"제 칠 회: 오쵸양왕을 사로잡아 졍법ᄒᆞ고 황후와 ᄐᆡᄌᆞ를 구ᄒᆞ야 황궁에 도라오다","t":"하고 길을 재촉하니, 위국공이 도사에게 아쉽게 작별하고 황후와 태자와 부인들을 모시고 시녀를 거느리고 절벽 사이로 내려와 백운동 어귀에 나오니 전에 보던 황하강이 있었다. 강까지 오며 지난 일을 생각하여 눈물을 흘리며 백사장을 지나 소봉대를 넘고 보춘동을 지나 오경루에 와서 하룻밤을 머물렀다. 이튿날 길을 떠나 파주성 문 밖에 이르니, 수문장이 문을 굳게 닫고 군사를 시켜 물었다. \"너희 행색을 보니 어떤 사람들이기에 이리 초라하냐? 바른대로 일러 사실을 숨기지 마라.\" 하고 성문을 열지 않았다. 시녀와 위국공이 크게 소리 질러 말했다. \"우리는 변란에 황후와 태자를 모시고 피란하였다가 지금 황성으로 돌아가는 길이니 너희는 의심하지 말고 어서 성문을 열어라.\" 군사가 이","sp":[[12,15,"P","홍무"],[17,19,"P","곽도사"],[31,33,"P","황후"],[35,37,"P","태자"],[39,41,"P","양부인"],[285,288,"P","홍무"],[313,315,"P","황후"],[317,319,"P","태자"]]},{"c":7,"sub":"제 칠 회: 오쵸양왕을 사로잡아 졍법ᄒᆞ고 황후와 ᄐᆡᄌᆞ를 구ᄒᆞ야 황궁에 도라오다","t":"말을 듣고 급히 관수에게 아뢰니, 관수가 이 말을 듣고 놀라 급히 나와 성문을 열고 엎드려 여쭈었다. \"정말 모르고 성문을 늦게 열었으니 원컨대 벌을 받겠습니다.\" 태자와 위국공이 위로하였다. \"사정이 그러했을 것이니 관수는 안심하고 개의치 마라.\" 하시고 관으로 들어가니, 관수가 황후 일행을 모셔 대접하며 한편으로 장문(狀聞)을 천자께 올렸다. 이때 천자께서는 황후와 태자가 화재로 죽은 줄 아시고 대궐 안에 신위를 차려 예를 갖추어 제사 지내시며 눈물을 그치지 않으셨는데, 이때 남관장이 장문을 올렸다.","sp":[[92,94,"P","태자"],[96,99,"P","홍무"],[158,160,"P","황후"],[186,188,"P","천자"],[198,200,"P","천자"],[204,206,"P","황후"],[208,210,"P","태자"]]},{"c":7,"sub":"제 칠 회: 오쵸양왕을 사로잡아 졍법ᄒᆞ고 황후와 ᄐᆡᄌᆞ를 구ᄒᆞ야 황궁에 도라오다","t":"천자께서 뜯어 보시니 이렇게 쓰여 있었다. \"위국공 홍무가 황후와 태자를 모시고 남관에 머물러 있습니다.\" 천자께서 다 읽으시고 한편 기쁘고 한편 슬퍼하시어 곧 계월에게 알리시니, 계월이 조서를 받들어 보고 크게 기뻐하였다. 곧 조복을 입고 대궐에 들어가 엎드려 은혜에 감사하고 나오려 하니 천자께서 반기시며 말씀하셨다. \"하늘이 짐을 위해 내신 바를 무엇으로 갚겠는가.\" 계월이 머리를 조아려 아뢰었다. \"이는 다 폐하의 넓으신 덕으로 하늘이 살피신 것이니 어찌 신의 아비의 공이라","sp":[[0,2,"P","천자"],[25,28,"P","홍무"],[29,31,"P","홍무"],[33,35,"P","황후"],[37,39,"P","태자"],[60,62,"P","천자"],[90,92,"P","홍계월"],[101,103,"P","홍계월"],[163,165,"P","천자"],[209,211,"P","홍계월"],[233,235,"P","천자"]]},{"c":7,"sub":"제 칠 회: 오쵸양왕을 사로잡아 졍법ᄒᆞ고 황후와 ᄐᆡᄌᆞ를 구ᄒᆞ야 황궁에 도라오다","t":"하겠습니까.\" 하였다. 천자께서 곧 위의를 갖추어 승상 보국을 위유사(慰諭使)로 보내셨다. 천자께서는 신하들을 거느리고 요지원에서 기다리시고, 계월은 대원수의 위의를 차려 낙성관까지 나가 맞으라 하시고 나가셨다. 이때 보국이 위의를 갖추어 길을 떠나 남관에 이르러 위국공 내외와 어머니께 엎드려 통곡하니, 위국공이 승상의 손을 잡고 울며 말했다. \"하마터면 너를 다시 보지 못할 뻔하였구나.\" 하고 슬퍼하기를 마지않았다. 이튿날 황후는 준마에 두렷이 앉았고, 삼천 궁녀는 초록 저고리에 붉은 치마 차림으로 화촉을 들고 연(輦)과 덩을 호위하였으며, 좌우에 풍류를 세우고 승상은 그 뒤에서 군사를 거느리고 오니 그 찬란함을 어찌 다 헤아리겠는가. [?]","sp":[[13,15,"P","천자"],[28,33,"P","보국"],[51,53,"P","천자"],[80,82,"P","홍계월"],[85,87,"P","홍계월"],[122,124,"P","보국"],[148,151,"P","홍무"],[171,174,"P","홍무"],[240,242,"P","황후"]]},{"c":7,"sub":"제 칠 회: 오쵸양왕을 사로잡아 졍법ᄒᆞ고 황후와 ᄐᆡᄌᆞ를 구ᄒᆞ야 황궁에 도라오다","t":"떠난 지 사흘 만에 낙성관에 이르렀다. 이때 계월이 낙성관에 와서 기다리다가 황후의 행차가 오시는 것을 보고 급히 나가 맞아 모시고 평안히 오셨는지 문안한 뒤, 물러나와 시부모 앞에 엎드려 통곡하였다. 위국공과 두 부인이 계월의 손을 잡고 울며 한편 기뻐하고 한편 슬퍼하였다. 밤새도록 그리던 정을 이야기하고 이튿날 해 뜰 무렵 길을 떠나 청운관에 이르니, 천자께서 백관을 거느리시고 대 위에 자리하시어 황후를 맞으셨다. 이윽고 황후 일행이 대 아래에 이르러 엎드리니 천자께서 눈물을 흘리시며 한편 기쁘고 한편 슬퍼하시어 피란하던 사연을 물으셨다. 황후와 태자가 앞뒤로 고생하던 사연을 낱낱이 아뢰고 위국공을 만난 일을 자세히 아뢰니, 천자께서 들으시고 위국공에게 사례하셨다. \"경이 아니었다면 황후와 태자를 어찌 다시 보았겠는가.\"","sp":[[25,27,"P","홍계월"],[43,45,"P","황후"],[113,116,"P","홍무"],[120,122,"P","양부인"],[124,126,"P","홍계월"],[200,202,"P","천자"],[226,228,"P","황후"],[240,242,"P","황후"],[262,264,"P","천자"],[307,309,"P","황후"],[311,313,"P","태자"],[336,339,"P","홍무"],[356,358,"P","천자"],[366,369,"P","홍무"],[389,391,"P","황후"],[393,395,"P","태자"]]},{"c":7,"sub":"제 칠 회: 오쵸양왕을 사로잡아 졍법ᄒᆞ고 황후와 ᄐᆡᄌᆞ를 구ᄒᆞ야 황궁에 도라오다","t":"하시고 거듭 사례하시니 위국공 부부가 황공하여 감사하고 물러나왔다. 이날 떠나 환궁하시는데 천자께서 선봉이 되어 환궁하시고 큰 잔치를 베푸셨다. 원수와 보국과 위국공을 불러 조정 신하들을 거느리시고 안팎 잔치를 차려 즐기셨다. 하루는 호부상서를 불러 하교하셨다. \"궁궐을 전과 같이 짓되 날을 받아 공사를 시작하여 며칠 안에 이루어라.\" 호부에서 건축을 시작하여 서둘러 지으니 불과 서너 달 만에 공사를 마쳤다. 기이한 꽃과 풀을 곳곳에 심고 층층 꽃계단을 쌓고, 황후와 함께 새로이 즐거워하셨다.","sp":[[13,16,"P","홍무"],[51,53,"P","천자"],[81,83,"P","홍계월"],[85,87,"P","보국"],[89,92,"P","홍무"],[260,262,"P","황후"]]},{"c":7,"sub":"제 칠 회: 오쵸양왕을 사로잡아 졍법ᄒᆞ고 황후와 ᄐᆡᄌᆞ를 구ᄒᆞ야 황궁에 도라오다","t":"하루는 위국공이 계월과 보국을 불러 도사의 봉서를 주었다. 계월이 받아 뜯어 보니 선생의 필적이었다. 그 글에 이렇게 쓰여 있었다. \"편지 한 통을 평국과 보국에게 부치노라. 슬프다. 명현동에서 함께 공부하던 정은 백옥같이 견고하고 소중하도다. 한 번 이별한 뒤로 정처 없이 버려진 몸이 적막한 산과 들을 떠돌아다니면서 너희를 생각하는 정을 어찌 다 헤아리겠느냐마는, 늙은이가 갈 길이 만 리에 막혔으니 슬프다, 눈물이 학창의(鶴氅衣)를 적시도다.","sp":[[4,7,"P","홍무"],[9,11,"P","홍계월"],[13,15,"P","보국"],[20,22,"P","곽도사"],[33,35,"P","홍계월"],[46,48,"P","곽도사"],[83,85,"P","홍계월"],[87,89,"P","보국"]]},{"c":7,"sub":"제 칠 회: 오쵸양왕을 사로잡아 졍법ᄒᆞ고 황후와 ᄐᆡᄌᆞ를 구ᄒᆞ야 황궁에 도라오다","t":"이후로는 다시 보지 못할 것이니 부디 위로는 천자를 섬겨 충성을 다하고 아래로는 부모를 섬겨 효성을 다하며, 전날의 호기를 누르고 예로써 남편을 섬기며, 그리던 한을 풀고 부디 무량히 지내기를 빈다.\" 평국과 보국이 다 읽고 못내 울며 그 은혜를 생각하여 공중을 향해 수없이 절하였다. 이때 천자께서 위국공의 벼슬을 올리시어 홍무를 초왕으로 봉하시고 여공을 오왕으로 봉하시며 채색 비단을 많이 내리시고 말씀하셨다. \"제후국의 일을 잘 다스리라.\" 하시고 길을 재촉하시니, 오와 초 두 왕이 천은에 엎드려 감사하고 물러나와 행장을 차려 떠나는데, 이때를 당하여 부모와 자식이 이별하는 정은 비할 데가 없었다.","sp":[[25,27,"P","천자"],[113,115,"P","홍계월"],[117,119,"P","보국"],[163,165,"P","천자"],[168,171,"P","홍무"],[182,184,"P","홍무"],[186,188,"P","홍무"],[196,198,"P","여공"],[200,202,"P","여공"]]},{"c":7,"sub":"제 칠 회: 오쵸양왕을 사로잡아 졍법ᄒᆞ고 황후와 ᄐᆡᄌᆞ를 구ᄒᆞ야 황궁에 도라오다","t":"두 왕이 길을 떠나 여러 날 만에 각각 제 나라에 이르니 문무백관이 예를 갖추어 나와 맞이하였다. 왕위에 올라 국호를 고치고 백성과 정사를 한마음으로 다스리니 온 나라가 칭송하였다. 이때 승상 보국의 나이가 사십오 세였다. 삼남 일녀를 두었는데 모두 부모의 풍모를 닮아 충효를 겸하였다. 맏아들은 오나라 태자로 봉하시고 둘째 아들은 초나라 태자로 봉하시고, 셋째 아들은 이름난 가문과 혼인하여 벼슬이 시랑에 이르러 충성으로 임금을 섬기고 백성을 인의로 사랑하였다.","sp":[[105,110,"P","보국"],[170,172,"P","태자"],[190,192,"P","태자"],[224,226,"P","홍무"]]},{"c":7,"sub":"제 칠 회: 오쵸양왕을 사로잡아 졍법ᄒᆞ고 황후와 ᄐᆡᄌᆞ를 구ᄒᆞ야 황궁에 도라오다","t":"이때 천자의 성덕이 세상을 진동하시니 때가 화평하고 해마다 풍년이 들어 사방에 아무 일이 없었다. 백성이 격양가를 부르고 배불리 먹고 배를 두드리니, 산에는 도적이 없고 길에 떨어진 것을 줍지 않아 요임금의 해와 달이요 순임금의 하늘과 땅이었다. 이때 계월의 자손이 대대로 공후의 작록을 누리고 만세토록 이어져 끝없이 전하니, 이렇게 장하고 기이한 일이 고금에 또 있겠는가. 세상일이 하늘이 맺어 준 정이 그러하기에 사적을 대강 기록하여 천하의 여러 군자에게 전하여 본받게 하노라. 이 아래에 짧은 기담소설 한 편을 붙인다.","sp":[[3,5,"P","천자"],[141,143,"P","홍계월"]]},{"c":8,"sub":"부록 죠션야담: 거울을 더지고 크게 울다가 다시 랑군을 만나다","t":"조선 이조 중엽 시절에 나라는 태평하고 백성은 편안하며 집집마다 넉넉하고 사람마다 풍족하여, 예악과 문물과 제도와 법도가 찬란하게 일어나니 예의염치와 효제충신을 어리석은 사내라도 모르는 사람이 없었다. 이때 한 재상이 딸을 두었는데, 자질이 비범하고 덕이 조용하고 단정하며, 게다가 꽃이 부끄러워하고 달이 숨을 만한 자태와 물고기가 가라앉고 기러기가 떨어질 만한 얼굴을 지녔으니 참으로 한 시대의 경국지색이었다. 재상이 매우 아껴 손바닥 위의 보옥같이 사랑하였다. 나이 열여섯에 이르자 그와 같은 짝을 얻어 배필을 정해 주었는데, 겨우 한 해 만에 그 사위가 죽으니 사방을 둘러보아도 의지할 친척이 없어 의탁할 곳이 없었다.","sp":[]},{"c":8,"sub":"부록 죠션야담: 거울을 더지고 크게 울다가 다시 랑군을 만나다","t":"딸은 남편을 선산에 안장하고 삼년상을 겨우 마치고 친정으로 돌아와 부모 슬하에서 세월을 보냈다. 부모 된 마음에 그 일생을 생각하여 가엾게 여겼다. 하루는 재상이 바깥채에 있다가 안채에 들어가 후원 초당 앞에 이르니, 그 딸이 홀로 방 안에 앉아 고운 단장과 화려한 옷차림으로 체경(體鏡)을 마주하여 앞뒤로 비추어 돌아보더니, 이어 거울을 던지고 얼굴을 가리며 크게 울었다. 재상이 그 모습을 보고 마음에 몹시 측은하여 곧 바깥채로 나와 두어 식경을 앉아 있었다. 마침 친근한 무변(武弁)이 있어 자주 문하에 드나드는 자가 왔는데, 그 사람은 나이가 젊고 사람됨이 영리하나 형편이 가난하여 아내도 집도 없이 지내고 있었다.","sp":[]},{"c":8,"sub":"부록 죠션야담: 거울을 더지고 크게 울다가 다시 랑군을 만나다","t":"재상이 좌우를 물리치고 일러 말했다. \"내가 자네 신세를 살펴보니 몹시 곤궁하구나. 그대가 내 사위가 되는 것이 어떠한가?\" 그 사람이 황송하여 대답하였다. \"소인은 대감께서 분부하시는 뜻을 알지 못하여 감히 명을 받들지 못하겠습니다.\" 재상이 말했다. \"내가 농담하는 것이 아니다.\" 하고 궤 속에서 은자 한 봉을 꺼내 주며 말했다. \"이것을 가지고 가서 튼튼한 말과 가마를 세내어 가지고 오늘 밤 파루(罷漏) 뒤에 와서 뒷문 밖에서 기다리되 부디 약속을 어기지 마라.\" 그 무변이 반신반의하며 받아 가지고 나와 그 말대로 가마와 말을 갖추어 그 집 뒷문에 가서 기다렸다. 얼마 지나지 않아 어둠 속에서 재상이 한 여자를 이끌고 나와 가마에 태우고 당부하였다. \"곧장","sp":[]},{"c":8,"sub":"부록 죠션야담: 거울을 더지고 크게 울다가 다시 랑군을 만나다","t":"북관(北關)으로 가서 잘 살아라.\" 하고 곧 안방으로 들어가 목 놓아 크게 울며 말했다. \"내 딸이 자결하였구나.\" 온 집안 사람이 모두 슬피 울며 그 청춘을 불쌍히 여겼다. 재상이 울다가 정신을 진정하고 흐느끼며 말했다. \"내 딸이 평소에 사람 보기를 싫어하였으니 내가 친히 염습하겠다. 비록 저희 남매 사이라도 볼 까닭이 없다.\" 하고 스스로 염습하여 발치에 장사 지냈다. 한편 그 무변은 앞뒤 곡절을 알지 못하고 가마를 따라 성 밖으로 나와 그 재상의 분부대로 북관으로 향하였다. 종일 가다가 날이 저물면 주막을 찾아 묵고 이튿날 또 행장을 수습하여, 여러 날 만에 북관에 이르니 산천이 수려하고 사람들이 순박하며 번화한 서울은 이미 멀었다.","sp":[]},{"c":8,"sub":"부록 죠션야담: 거울을 더지고 크게 울다가 다시 랑군을 만나다","t":"속세의 티끌에 물들 일이 없었다. 벼슬과 공명을 뜬구름에 버려 두고 깨끗한 곳에 초가 몇 칸을 마련하여 거처를 정한 뒤 앞뒤 곡절을 들으니 다름이 아니었다. 재상은 이팔청춘에 홀로 된 딸을 눈앞에 두고 보니 그 정경이 가엾고 애처로웠으나, 사대부가의 풍속으로 예법이 분명하여 개가할 길이 전혀 없었다. 다만 문하에 드나들던 무변이 젊어서 홀로 살고 사람됨이 단아하며 마음 씀과 처신이 진실하고 거짓이 없으므로, 딸의 일생을 맡겨 청상과부의 신세를 면하게 한 것이었다. 무변은 좋은 인연을 이어 부부의 즐거움을 이룬 뒤 부부가 화락하여, 재상의 은덕으로 홀아비 신세도 면하였거니와 대를 이어 조상의 제사를 받들게 해 준 것에 감탄하였다. 그 뒤 몇 해가 지나 그 재상의 아들이 수의어사(繡衣御史)가 되어 북관을 암행하다가 한 곳에 이르니, 산림과 물과 돌이 기이한 가운데 초가 몇 칸이 매우 정결하였다.","sp":[]},{"c":8,"sub":"부록 죠션야담: 거울을 더지고 크게 울다가 다시 랑군을 만나다","t":"어사가 잠시 쉬어 가려고 들어가니 주인이 나와 맞았다. 안부 인사를 마치고 좌우를 살펴보니 두 아이가 곁에 앉아 글을 읽는데, 생김새가 맑고 빼어나며 자기 얼굴과 꽤 닮은 데가 있었다. 마음에 몹시 이상히 여겼고, 또 날이 이미 저물고 길에 지쳐 하룻밤 묵게 되었다. 밤이 깊은 뒤 안채에서 문득 한 여자가 나와 손을 잡고 우는데, 어사가 놀라 자세히 보니 바로 이미 죽은 누이였다. 놀라움을 이기지 못해 어찌 된 일인지 물으니, 바로 아버지의 뜻에 따라 인연을 맺어 이곳에 살고 있으며 이미 두 아들을 낳아 가르치고 있는데 바로 이 아이들이라고 하였다.","sp":[]},{"c":8,"sub":"부록 죠션야담: 거울을 더지고 크게 울다가 다시 랑군을 만나다","t":"어사는 정신을 잃은 듯 한동안 묵묵히 앉아 있다가 다시 진정한 뒤 반가움을 이기지 못하여, 남매가 그리워하던 정을 대강 풀고 부모님 두 분의 안부도 전하였다. 또 그때 장사 지낸 일과 부모 형제가 애달파하던 일을 한바탕 이야기하다가 날이 밝았다. 어사의 행색은 암행이라 비밀스러운 일이 많으므로 곧 애틋하게 작별하고 암행을 마치고 복명한 뒤 집에 돌아와 부친을 뵈었다. 마침 조용한 때라 소리를 낮추어 아뢰었다. \"이번 길에 정말 괴이하고 이상한 일을 보았습니다.\" 그러자 재상이 눈을 부릅뜨고 한참 바라보며 말하지 않으므로, 그 아들은 감히 말을 꺼내지 못하고 물러갔다. 홍계월전 끝.","sp":[[321,324,"P","홍계월"]]}]});
